const HEALTH_PROFILES={
  none:{he:"ללא",en:"None",emoji:"",carbMax:55,protMin:18,protPerKg:1.2,protPerKgMax:1.6,fatMax:30,fiberMin:50,kcalOffset:0,note:{he:"",en:""}},
};
// תיקון (לבקשת המשתמש: "איך אתה מציע לפתור את הפער" — בין הטקסט-ההסברי של פאנל-החלבון, שמתאר במפורש שיעד-
// החלבון-לק"ג אמור לנוע לפי רמת-פעילות (0.8 מועטה, 1.2-1.4 סיבולת, 1.6-2.2 התנגדות, לפי ISSN/ACSM), לבין
// החישוב בפועל, שהשתמש בערך-קבוע-אחד (hp.protPerKg) בלי שום קשר לרמת-הפעילות שנבחרה בפרופיל) — במקום להוסיף
// פרמטר "act" חדש לעשרות חתימות-פונקציה בכל הקובץ (hp כבר מועבר לכל מקום, act לא), מתאימים את protPerKg
// *פעם אחת* כאן, לפי רמת-הפעילות, ומעבירים הלאה את הפרופיל-המותאם כרגיל דרך hp הקיים — בלי לגעת בשום חתימה.
// המקדם למועטה/בינונית/גבוהה נבחר כך שה"בינונית" (ברירת המחדל) נשארת בדיוק כמו הערך הקיים היום (1.2) —
// כל העבודה האינטנסיבית שכבר נעשתה על אכילת-חלבון בסימולציות ממשיכה להיות תקפה לברירת-המחדל, לא משתנה.
// התקרה הקלינית (protPerKgMax) לעולם לא מותאמת כאן — מגבלה קלינית (למשל מחלת כליות) לא אמורה "לעלות" רק כי
// המשתמש בחר רמת-פעילות גבוהה יותר; ה-multiplier חל אך ורק על הרצפה (protPerKg)
const ACTIVITY_PROTEIN_MULT = {low:0.85, medium:1.0, high:1.25};
// תיקון (לבקשת המשתמש: "וכיצד היא מותאמת לגיל?") — הטקסט-ההסברי של פאנל-החלבון כבר מתאר במפורש שגיל 65+
// אמור לקבל רצפה של כ-1.0-1.2 גר'/ק"ג למניעת סרקופניה (אובדן מסת שריר עם הגיל), בלי קשר לרמת-הפעילות —
// גם קשיש בפעילות-מועטה לא אמור לרדת מתחת לרצפה הזו, בשונה ממבוגר צעיר בפעילות-מועטה. נוספה רצפת-גיל
// שחלה *אחרי* ההתאמה-לפי-פעילות: אם התוצאה יצאה מתחת ל-1.1 (אמצע הטווח המתועד) וגם הגיל 65+, מעלים ל-1.1.
// זו רצפה-מגינה בלבד, לא מכפיל-נוסף — לא "מוסיפה" לגיל-הצעיר, רק מונעת מגיל-מבוגר לרדת נמוך מדי בפעילות-מועטה
const AGE_PROTEIN_FLOOR_65 = 1.1;
function resolveHealthProfile(profile){
  const base = HEALTH_PROFILES[profile?.healthProfile||"none"]||HEALTH_PROFILES.none;
  const mult = ACTIVITY_PROTEIN_MULT[profile?.activity||"medium"] ?? 1.0;
  const age = parseFloat(profile?.age)||0;
  let protPerKg = base.protPerKg*mult;
  if (age>=65) protPerKg = Math.max(protPerKg, AGE_PROTEIN_FLOOR_65);
  if (mult===1.0 && age<65) return base;
  return {...base, protPerKg: Math.round(protPerKg*100)/100};
}

