const F=(a,b,c,d,e,f,g,h,i,j,k,l,m,n,o,p,q,r,s,t,u,v,w,x,y,z,A,B,C,D,E,F2,G,H)=>({kcal:a,protein:b,carbs:c,fat:d,fiber:e,omega3:f,omega6:g,omega9:h,vitA:i,vitC:j,vitD:k,vitE:l,vitK:m,vitB1:n,vitB2:o,vitB3:p,vitB6:q,vitB9:r,vitB12:s,calcium:t,iron:u,zinc:v,magnesium:w,potassium:x,selenium:y,iodine:z,choline:A,copper:B,manganese:C,sodium:D,phosphorus:E,vitB5:F2,satFat:G,cholesterol:H});

