// היחידה האמריקאית המוכרת לו (US customary), לא רק גרמים. בעברית ממשיך להציג גרמים בלבד כרגיל, ללא שינוי.
// 1 גרם = 0.035274 oz בדיוק (המרה סטנדרטית) — מוצג עם ספרה עשרונית אחת, שמספיקה לדיוק מטבחי סביר.
function fmtWeightG(g,lang){
  const grams=Math.round(g);
  if(lang!=="he"){
    const oz=fmtN(g*0.035274,1);
    return `${grams}g (${oz}oz)`;
  }
  return `${grams}גר׳`;
}
function snapQtr(ratio){return Math.round(ratio*4)/4;} // מעגל תמיד לרשת רבעי-יחידה נקייה (0.25/0.5/0.75/1...), מונע סחיפה כמו 0.26
function fmtQty(v){
  // תיקון (לבקשת המשתמש): לעולם לא להציג כמות "כמעט שלמה" כמו 0.99 — מיושר לשלם כשקרוב אליו במידה זניחה (±0.03),
  // הפרש שיכול לנבוע מעיגולי-רוחב זעירים בין שלבי הבנייה/עדכון המתכון. כמויות שברירי-יחידה אמיתיות (כמו 0.3 אבוקדו)
  // רחוקות בהרבה מהסף הזה ולא מושפעות
  const rounded = Math.round(v);
  if (rounded>0 && Math.abs(v-rounded) < 0.05) return rounded.toString();
  // מציג כמויות ברבעי יחידה כשבר נקי (¼ ½ ¾) במקום עשרוני; נופל לעשרוני רגיל אם לא מיושר לרבע
  const whole=Math.floor(v);
  const frac=Math.round((v-whole)*4)/4;
  const fracStr={0:"",0.25:"¼",0.5:"½",0.75:"¾"}[frac];
  if (fracStr!==undefined) {
    if (!whole && !frac) return "0";
    return `${whole||""}${fracStr}`;
  }
  return fmtN(v,2).toString();
}
