// באפליקציה (כרטיס ארוחה, סיכום יומי, אחוז מהיעד) — ראה calcKcalActual למטה. בלי היישור הזה, מנוע היצירה האוטומטי
// היה אוכף תקרת קלוריות מול ערך ה-kcal הגולמי מבסיס הנתונים, בעוד המשתמש רואה על המסך מספר אחר (מחושב מחדש
// מהמאקרו) — כך שיום שהמנוע "חשב" שהוא בדיוק 100% יכול היה להיראות למשתמש כ-103%. עכשיו שני המספרים תמיד זהים.
// זמינות ביולוגית: השריה מפחיתה חומצה פיטית (פיטאט) בקטניות ודגנים — המעכב האנטי-תזונתי המרכזי לספיגת ברזל,
// אבץ וסידן. מודל בינארי לבקשת המשתמש: בונוס קבוע לכל אחד משלושת המינרלים, רק לפריטי קטנית/דגן, רק כשמסומן
// "מושרה" (soaked=true על הפריט הבודד). ברירת המחדל (סטטוס לא ידוע/לא מסומן) היא ללא בונוס — כלומר תואם בדיוק
// את התנהגות האפליקציה כפי שהייתה עד כה (ערכי per100 כפי שהם, ללא שינוי), לא מניחים השריה שלא אושרה במפורש.
// גודל הבונוס: ברזל +15%, אבץ +25% (הכי מושפע מפיטאט), סידן +10% (פחות מושפע מהשריה בהקשר הזה מאשר אוקסלאט).
const SOAK_BIOAVAIL_BOOST = {iron:1.15, zinc:1.25, calcium:1.10};
const SOAKABLE_CATS = new Set(["קטנית","דגן"]);
function isSoakableFk(fk){ const fd=FDB[fk]||TEMP_FDB[fk]; return !!fd && SOAKABLE_CATS.has(fd.cat) && !fd._isRecipe; }
// ביצועים: בנייה בלולאה אחת (במקום reduce עם העתקת-אובייקט בכל צעד, שהייתה ריבועית וצרכה ~70% מזמן תכנון השבוע) — תוצאה זהה
function zeroNut(){const o={};for(let i=0;i<ALL_KEYS.length;i++)o[ALL_KEYS[i]]=0;return o;}
function ingNut(fk,g,soaked){const fd=FDB[fk]||TEMP_FDB[fk];if(!fd)return zeroNut();const f=g/100;const p=fd.per100;const nut={};for(let i=0;i<ALL_KEYS.length;i++){const k=ALL_KEYS[i];nut[k]=(p[k]||0)*f;}if(soaked&&SOAKABLE_CATS.has(fd.cat)&&!fd._isRecipe){Object.keys(SOAK_BIOAVAIL_BOOST).forEach(k=>{nut[k]=(nut[k]||0)*SOAK_BIOAVAIL_BOOST[k];});}nut.kcal=calcKcalActual(nut);return nut;}
function sumNuts(arr){const acc=zeroNut();for(let j=0;j<arr.length;j++){const n=arr[j];if(!n)continue;for(let i=0;i<ALL_KEYS.length;i++){const k=ALL_KEYS[i];acc[k]=(acc[k]||0)+(n[k]||0);}}return acc;}
// לבקשת המשתמש: "האם הספיגה המשוערת... יכולה להיות מדד משמעותי יותר מאשר עמידה ב-RDA?" — הערכה לא-מחייבת,
// מוצגת כמידע נוסף בלבד, שלא משנה שום החלטת-תכנון בפועל (לא בוחרת מזון, לא קובעת יעד). מבוססת בחלקה על
// מדידות-איזוטופים שפורסמו בפועל (Weaver et al., שנות ה-90) לפריטים ספציפיים, ובחלקה על קירוב-משפחתי לפריטים
// שלא נחקרו ישירות (מסומן בנפרד למטה). ברירת-המחדל (30%) משקפת את הנחת-הספיגה הממוצעת שכבר מגולמת ב-RDA עצמו.
const CALCIUM_ABSORPTION_RATES = {
  // נמדד ישירות במחקרי איזוטופים-כפולים (Weaver, מקורות פורסמו)
  broccoli: 0.61, kale: 0.61, whiteBeans: 0.17, almonds: 0.21,
  soymilkFortified: 0.24, soymilkOrgPlain: 0.24, tofuCalciumSet: 0.31, tofu: 0.31,
  spinach: 0.05, // אוקסלט קיצוני — ספיגה נמוכה מאוד למרות תוכן-סידן גבוה
  // קירוב-משפחתי (לא נמדד ישירות; מוערך דומה לברוקולי/קייל בגלל תוכן-אוקסלט/פיטאט נמוך דומה במשפחת המצליבים)
  cauliflower: 0.55, cabbageWhite: 0.55, cabbageRed: 0.55, brusselsSp: 0.55,
};
const CALCIUM_ABSORPTION_STUDIED = new Set(["broccoli","kale","whiteBeans","almonds","soymilkFortified","soymilkOrgPlain","tofuCalciumSet","tofu","spinach"]);
const CALCIUM_ABSORPTION_DEFAULT = 0.30;
function estimateAbsorbedCalcium(items){
  let absorbed=0, hasEstimatedItem=false;
  (items||[]).forEach(({fk,g,soaked})=>{
    const nut = ingNut(fk,g,soaked);
    const rawCa = nut.calcium||0;
    if (rawCa<=0) return;
    const rate = CALCIUM_ABSORPTION_RATES[fk] ?? CALCIUM_ABSORPTION_DEFAULT;
    if (!(fk in CALCIUM_ABSORPTION_RATES) || !CALCIUM_ABSORPTION_STUDIED.has(fk)) hasEstimatedItem=true;
    absorbed += rawCa*rate;
  });
  return {absorbed, hasEstimatedItem};
}
// עוזר משותף (לבקשת המשתמש, אחרי דיווח על ארוחת צהריים עם תבשיל גריסי-פנינה-ועדשים + אורז חום מבושל יחד —
// עודף פחמימות בלי מספיק חלבון): קובע את הקטגוריה ה"אפקטיבית" של פריט/מתכון לצורך מניעת כפילות דגן/קטנית
// באותה ארוחה. מתכון שמשלב דגן וקטנית יחד (כמו תבשיל גריסי פנינה ועדשים) נחשב אך ורק כ"דגן" — לעולם לא
// כ"קטנית" — כדי שהוא ימנע דגן נוסף באותה ארוחה, אבל עדיין ידרוש שתתלווה אליו מנת קטנית אמיתית ונפרדת (לא
// יסתמך על החלבון המדולל שבתוך התבשיל עצמו). מתכון קטנית-בלבד (בלי שום דגן מוטמע) עדיין נחשב "קטנית" כרגיל.
function capCatOf(fk){
  const fd=FDB[fk]||TEMP_FDB[fk]; if(!fd) return undefined;
  if (fd._isRecipe) {
    const ings=fd._ings||[];
    if (ings.some(ing=>(FDB[ing.fk]||TEMP_FDB[ing.fk])?.cat==="דגן")) return "דגן";
    if (ings.some(ing=>(FDB[ing.fk]||TEMP_FDB[ing.fk])?.cat==="קטנית")) return "קטנית";
  }
  return fd.cat==="מאפה"?"דגן":fd.cat;
}
// תיקון (נמצא ע"י בדיקה עצמית שהריץ בפועל את מנגנון היצירה 5 פעמים ברצף, לבקשת המשתמש): רשת הביטחון הסופית
// שמקצצת חזרה ל-100% מהיעד הקלורי רצה *לפני* תוספת המלח/נורי/וואקמה (applySodiumSaltTopup) — ותוספת המלח
// עצמה מוסיפה עוד כמה קק"ל (נורי/וואקמה לא לגמרי אפסיים), מה שדחף ימים ל-100.2%-100.3% (כ-7 קק"ל מעל) גם
// אחרי כל התיקונים הקודמים. פונקציה משותפת אחת שמריצים *שוב* אחרי תוספת המלח, בכל שלושת מנגנוני היצירה
// וגם בשני מנגנוני ההפצה ברמת השבוע — כדי שהתקרה הקשיחה תמיד תהיה המילה האחרונה באמת, לא משנה מה נוסף אחריה
function trimToCalorieTarget(plan, tgt){
  const totalKcalNow = () => sumNuts(Object.values(plan).flat().map(({fk,g,soaked})=>ingNut(fk,g,soaked))).kcal;
  const TRIM_PRIORITY = ["oliveOil","almondbutter","peanutButter","walnuts","cashews","sunflowerS","pumpkinS","hazelnuts","brazilNuts","flaxseed","pistachio","almonds","chiaseeds","avocado","tahini"];
  let guardTrim=0;
  while (totalKcalNow() > tgt+0.5 && guardTrim<60) {
    guardTrim++;
    const over = totalKcalNow() - tgt;
    const flat = Object.keys(plan).flatMap(mk=>(plan[mk]||[]).map((it,idx)=>({...it,mk,idx})));
    let acted=false;
    for (const fk of TRIM_PRIORITY) {
      const loc = flat.find(it=>it.fk===fk);
      if (!loc) continue;
      const fd=FDB[fk]; if(!fd) continue;
      const kcalPerG=(fd.per100.kcal||0)/100;
      if (kcalPerG<=0) continue;
      const minG=2;
      if (loc.g<=minG) continue;
      const reduceG=Math.min(loc.g-minG, Math.max(0.5, over/kcalPerG));
      const newG=+(loc.g-reduceG).toFixed(1);
      if (newG<=minG*0.5) { plan[loc.mk].splice(loc.idx,1); }
      else { plan[loc.mk][loc.idx]={...plan[loc.mk][loc.idx], g:newG}; }
      acted=true;
      break;
    }
    if (!acted) {
      // רשת ביטחון אחרונה (נמצאה ע"י בדיקה עצמית בתרחיש קיצון: יום שמורכב כולו ממתכונים ללא אף פריט גולמי
      // עצמאי מהרשימה למעלה, למשל בלי שום שמן/אגוז בודד) — אם אין שום פריט מהרשימה הקבועה לקצץ ממנו, מקצצים
      // חלקית את המנה (g) של הפריט הכי-קלורי בתפריט שהוא בכלל לא מתכון, כדי שהתקרה הקשיחה עדיין תמיד תנצח,
      // גם במקרה הקיצון הזה. לא נוגעים במתכונים עצמם (אי אפשר "לקצץ חלקית" רכיב בודד בתוך מתכון סגור)
      const nonRecipe = flat.filter(it=>{ const fd=FDB[it.fk]; return fd && !fd._isRecipe; })
        .map(it=>({...it, kcal: ingNut(it.fk,it.g).kcal}))
        .sort((a,b)=>b.kcal-a.kcal);
      const biggest = nonRecipe[0];
      if (biggest && biggest.g>1) {
        const fd=FDB[biggest.fk];
        const kcalPerG=(fd.per100.kcal||0)/100;
        if (kcalPerG>0) {
          // תיקון (לבקשת המשתמש: "אל תציע חלקי יחידות ירק/קטנית - רק שלמות") — רשת-הביטחון-האחרונה-הזו
          // פועלת על כל פריט-גולמי, לא רק על TRIM_PRIORITY (שמן/אגוזים, גמישים בכוונה) — אם קטנית/ירק נבחר
          // כאן, הקיצוץ-המדויק-לגרם היה יוצר כמות-שברית. נוסף עיגול-ליחידה-שלמה גם כאן
          const wholeStepLast = isWholeUnitCountable(biggest.fk, fd) ? wholeUnitStepG(biggest.fk) : null;
          if (wholeStepLast && wholeStepLast>0) {
            const currentUnitsLast = biggest.g / wholeStepLast;
            const flooredUnitsLast = Math.floor(currentUnitsLast + 1e-6);
            const targetUnitsLast = (Math.abs(currentUnitsLast-flooredUnitsLast) > 0.05) ? flooredUnitsLast : Math.max(0, flooredUnitsLast-1);
            const newGLast = Math.round(targetUnitsLast*wholeStepLast*10)/10;
            if (newGLast < wholeStepLast*0.5) plan[biggest.mk].splice(biggest.idx,1);
            else plan[biggest.mk][biggest.idx]={...plan[biggest.mk][biggest.idx], g:newGLast};
            acted=true;
          } else {
          const reduceG=Math.min(biggest.g-1, Math.max(0.5, over/kcalPerG));
          const newG=+(biggest.g-reduceG).toFixed(1);
          if (newG<=0.5) plan[biggest.mk].splice(biggest.idx,1);
          else plan[biggest.mk][biggest.idx]={...plan[biggest.mk][biggest.idx], g:newG};
          acted=true;
          }
        }
      }
    }
    if (!acted) break;
  }
  return plan;
}
// תקרת בטיחות (UL) למנגן — גרסה שנייה, מתוקנת (לבקשת המשתמש, אחרי שהגרסה הראשונה רק הסירה/הקטינה כמויות בלי
// להשלים את הקלוריות שאבדו, מה שגרם ל"קיצוץ קלורי" לא-רצוי בהצעות). העיקרון עכשיו: **החלפה, לא הסרה** —
// כשהמנגן חוצה את התקרה, מחפשים תחליף מאותה קטגוריית מזון בדיוק (כדי לשמור על ההיגיון הקולינרי: דגן בדגן,
// אגוז באגוז וכו') עם יחס מנגן/קלוריה נמוך יותר, ומחליפים בכמות ששומרת על אותה תרומה קלורית בדיוק (לא רק
// אותם גרמים) — כך שסך הקלוריות של התפריט לא זז כלל. רק אם אין שום תחליף מתאים באותה קטגוריה (למשל אם כל
// שאר הפריטים בקטגוריה כבר בשימוש היום, או שגם הם עתירי-מנגן), נופלים לצמצום הדרגתי עם השלמת הקלוריות
// שהתפנו ממקור דל-מנגן כלשהו (לא בהכרח מאותה קטגוריה) — כדי שגם במקרה הזה סך הקלוריות יישאר קרוב ליעד.
function trimManganeseUL(plan, dri){
  const ul = dri?.manganese?.ul;
  if (!ul) return plan;
  const totalMn = () => sumNuts(Object.values(plan).flat().map(({fk,g,soaked})=>ingNut(fk,g,soaked))).manganese||0;
  const usedFksToday = () => new Set(Object.values(plan).flat().map(it=>it.fk));
  const LOW_MN_FILLERS = ["apple","orange","banana","tomato","cucumber","carrot","watermelon","redPepper"];
  const addLowMnFiller = mkTarget => {
    // תיקון-באג (לבקשת המשתמש, אחרי דיווח על תפוזים/תפוחים כפולים שחזרו בפועל): המילוי הזה יכול להוסיף פרי
    // (apple/orange/banana ברשימה) בלי שום מודעות למגבלת יחידה-אחת-פרי-לארוחה שנאכפת ע"י enforceFruitOnePerMeal —
    // אם הארוחה כבר יש בה פרי, מדלגים על מועמדי-פרי ברשימה ומחפשים מועמד לא-פרי במקום
    const mealAlreadyHasFruit = (plan[mkTarget]||[]).some(it=>{const ifd=FDB[it.fk]; return ifd&&ifd.cat==="פרי";});
    const filler = LOW_MN_FILLERS.find(fk=>{
      if (usedFksToday().has(fk) || !FDB[fk]) return false;
      if (mealAlreadyHasFruit && FDB[fk].cat==="פרי") return false;
      return true;
    });
    if (filler) {
      const fillerFd = FDB[filler];
      const fillerStep = wholeUnitStepG(filler) || (getServingUnit(filler,fillerFd,"he")?.g||100);
      plan[mkTarget].push({fk:filler, g:fillerStep});
    }
  };
  let guard=0;
  while (totalMn() > ul && guard<30) {
    guard++;
    const flat = Object.keys(plan).filter(mk=>mk!=="snack").flatMap(mk=>(plan[mk]||[]).map((it,idx)=>({mk,idx,orig:it})));
    // תיקון (לבקשת המשתמש: "לחם בלי ממרח" — נמצא שממרחים המכילים טחינה (עתירת-מנגן) יכולים להיבחר כאן
    // כ"תורם-המנגן-הגדול ביותר" ולהיחתך/להימחק, בלי שום מודעות שזה בדיוק הממרח ש-enforceBreadSpreadPairing
    // הוסיפה כדי לזווג עם הלחם): הוחרגו מתכוני-ממרח ופריטי-ממרח-גולמיים מהמועמדים
    const RAW_SPREAD_FKS_MN = new Set(["avocado","tahini","tahiniRaw","peanutButter","almondbutter"]);
    const isSpreadHere = fk => {
      const fd = FDB[fk]||TEMP_FDB[fk]; if (!fd) return false;
      if (!fd._isRecipe) return RAW_SPREAD_FKS_MN.has(fk);
      return bookCategoryOf({name:fd.he||"", foodGroup:fd._foodGroup||"", type:fd._recipeType||"", ings:fd._ings||[]})==="ממרחים";
    };
    // תיקון-באג (לבקשת המשתמש, אחרי 612% UL בפועל): לפני התיקון, המועמדים כללו רק פריטים גולמיים (FDB בלבד) —
    // כשכל תרומת המנגן החריגה הגיעה ממתכונים (TEMP_FDB), הפונקציה פשוט ויתרה (candidates.length===0) בלי לגעת
    // בהם בכלל. עכשיו מתכונים נכללים גם הם כמועמדים לגיטימיים
    const candidates = flat.filter(({orig})=>!isSpreadHere(orig.fk)).map(({mk,idx,orig})=>{
      const fd=FDB[orig.fk]||TEMP_FDB[orig.fk]; if (!fd) return null;
      const mnContrib=(fd.per100.manganese||0)*orig.g/100;
      if (mnContrib<=0) return null;
      const mnPerKcal = fd.per100.kcal>0 ? (fd.per100.manganese||0)/fd.per100.kcal : Infinity;
      return {mk,idx,orig,fd,mnContrib,mnPerKcal};
    }).filter(Boolean).sort((a,b)=>b.mnContrib-a.mnContrib);
    if (!candidates.length) break;
    const worst = candidates[0];

    // מתכון: אי אפשר "להחליף רכיב" בתוך מתכון קבוע — מקטינים מנה אחת (servingG) בכל פעם, או מסירים לגמרי אם
    // כבר במנה אחת בודדת, ומפצים חלקית על הקלוריות שהתפנו עם פריט דל-מנגן, בדיוק כמו ברשת הביטחון הרגילה למטה
    if (worst.fd._isRecipe) {
      const servingG = worst.fd._servingG || worst.orig.g;
      if (worst.orig.g <= servingG*1.01) {
        plan[worst.mk].splice(worst.idx,1);
      } else {
        const newG = Math.max(servingG, worst.orig.g - servingG);
        if (newG>=worst.orig.g) plan[worst.mk].splice(worst.idx,1);
        else plan[worst.mk][worst.idx] = {...worst.orig, g:newG};
      }
      addLowMnFiller(worst.mk);
      continue;
    }
    const worstKcal = ingNut(worst.orig.fk, worst.orig.g).kcal;

    // שלב א: חיפוש תחליף מאותה קטגוריה בדיוק, עם יחס מנגן/קלוריה נמוך משמעותית מהמקור, שעדיין לא בשימוש היום
    const usedToday = usedFksToday();
    const sameCategoryAlternatives = Object.keys(FDB).filter(fk=>{
      if (usedToday.has(fk) || fk===worst.orig.fk) return false;
      const fd=FDB[fk]; if (!fd||fd._isRecipe||fd.cat!==worst.fd.cat||fd.cat==="מן החי") return false;
      if ((fd.per100.kcal||0)<=0) return false;
      const mnPerKcal = (fd.per100.manganese||0)/fd.per100.kcal;
      return mnPerKcal < worst.mnPerKcal*0.6; // רק תחליף שבאמת משפר משמעותית, לא שיפור שולי
    }).sort((a,b)=>(FDB[a].per100.manganese/FDB[a].per100.kcal)-(FDB[b].per100.manganese/FDB[b].per100.kcal));

    if (sameCategoryAlternatives.length) {
      const subFk = sameCategoryAlternatives[0];
      const subFd = FDB[subFk];
      let newG = (worstKcal/subFd.per100.kcal)*100;
      const wholeStep = wholeUnitStepG(subFk);
      if (wholeStep) newG = Math.max(wholeStep, Math.round(newG/wholeStep)*wholeStep);
      // תיקון-באג (לבקשת המשתמש, אחרי דיווח חוזר על ריבוי-פרי בפועל): החלפה קלורית-שווה בין שני פירות עם צפיפות-
      // קלוריות שונה (למשל בננה→תפוז) יכולה בקלות "לנחות" על 2+ יחידות שלמות של התחליף — בניגוד למגבלת יחידה-
      // אחת-פרי-לארוחה שנאכפת ע"י enforceFruitOnePerMeal. מגבילים במפורש ליחידה אחת בדיוק כשמדובר בקטגוריית פרי
      if (subFd.cat==="פרי" && wholeStep) newG = wholeStep;
      plan[worst.mk][worst.idx] = {fk:subFk, g:Math.round(newG*10)/10};
      continue; // החלפה קלורית-שווה — סך הקלוריות לא זז, ממשיכים לסיבוב הבא
    }

    // שלב ב (רשת ביטחון): אין תחליף מתאים באותה קטגוריה — מצמצמים בהדרגה את הפריט, ומשלימים בחזרה את הקלוריות
    // שהתפנו ממקור דל-מנגן כלשהו (לא בהכרח מאותה קטגוריה), כדי שסך הקלוריות יישאר קרוב ליעד ולא "יקטן סתם"
    const wholeStep = wholeUnitStepG(worst.orig.fk);
    const minG = wholeStep ? wholeStep*0.5 : 2;
    if (worst.orig.g<=minG) { plan[worst.mk].splice(worst.idx,1); }
    else {
      const step = wholeStep || Math.max(2, Math.round(worst.orig.g*0.2));
      const newG = Math.max(minG, worst.orig.g-step);
      if (newG>=worst.orig.g) { plan[worst.mk].splice(worst.idx,1); }
      else plan[worst.mk][worst.idx] = {...worst.orig, g:newG};
    }
    addLowMnFiller(worst.mk);
  }
  return plan;
}
// תיקון (לבקשת המשתמש: "כעת גם מנגן וגם סלניום חורגים" — אותר: לסלניום לא היה שום מנגנון-אכיפה פעיל בכלל,
// למרות שהממשק עצמו מזהיר במפורש שזה אחד משלושת הנוטריאנטים שבאמת אפשר לחצות מתזונה טבעונית רגילה (בעיקר
// אגוזי ברזיל, 1917 מק"ג/100 גר' — יחידה בודדת יכולה לקרב לתקרה לבדה). בנוי במבנה זהה בדיוק ל-trimManganeseUL
function trimSeleniumUL(plan, dri){
  const ul = dri?.selenium?.ul || 400;
  const totalSe = () => sumNuts(Object.values(plan).flat().map(({fk,g,soaked})=>ingNut(fk,g,soaked))).selenium||0;
  const usedFksToday = () => new Set(Object.values(plan).flat().map(it=>it.fk));
  const LOW_SE_FILLERS = ["apple","orange","banana","tomato","cucumber","carrot","watermelon","redPepper"];
  const addLowSeFiller = mkTarget => {
    const mealAlreadyHasFruit = (plan[mkTarget]||[]).some(it=>{const ifd=FDB[it.fk]; return ifd&&ifd.cat==="פרי";});
    const filler = LOW_SE_FILLERS.find(fk=>{
      if (usedFksToday().has(fk) || !FDB[fk]) return false;
      if (mealAlreadyHasFruit && FDB[fk].cat==="פרי") return false;
      return true;
    });
    if (filler) {
      const fillerFd = FDB[filler];
      const fillerStep = wholeUnitStepG(filler) || (getServingUnit(filler,fillerFd,"he")?.g||100);
      plan[mkTarget].push({fk:filler, g:fillerStep});
    }
  };
  let guard=0;
  while (totalSe() > ul && guard<30) {
    guard++;
    const flat = Object.keys(plan).filter(mk=>mk!=="snack").flatMap(mk=>(plan[mk]||[]).map((it,idx)=>({mk,idx,orig:it})));
    // תיקון (לבקשת המשתמש: "לחם בלי ממרח" — אותו תיקון בדיוק כמו ב-trimManganeseUL)
    const RAW_SPREAD_FKS_SE = new Set(["avocado","tahini","tahiniRaw","peanutButter","almondbutter"]);
    const isSpreadHereSe = fk => {
      const fd = FDB[fk]||TEMP_FDB[fk]; if (!fd) return false;
      if (!fd._isRecipe) return RAW_SPREAD_FKS_SE.has(fk);
      return bookCategoryOf({name:fd.he||"", foodGroup:fd._foodGroup||"", type:fd._recipeType||"", ings:fd._ings||[]})==="ממרחים";
    };
    const candidates = flat.filter(({orig})=>!isSpreadHereSe(orig.fk)).map(({mk,idx,orig})=>{
      const fd=FDB[orig.fk]||TEMP_FDB[orig.fk]; if (!fd) return null;
      const seContrib=(fd.per100.selenium||0)*orig.g/100;
      if (seContrib<=0) return null;
      const sePerKcal = fd.per100.kcal>0 ? (fd.per100.selenium||0)/fd.per100.kcal : Infinity;
      return {mk,idx,orig,fd,seContrib,sePerKcal};
    }).filter(Boolean).sort((a,b)=>b.seContrib-a.seContrib);
    if (!candidates.length) break;
    const worst = candidates[0];

    if (worst.fd._isRecipe) {
      const servingG = worst.fd._servingG || worst.orig.g;
      if (worst.orig.g <= servingG*1.01) {
        plan[worst.mk].splice(worst.idx,1);
      } else {
        const newG = Math.max(servingG, worst.orig.g - servingG);
        if (newG>=worst.orig.g) plan[worst.mk].splice(worst.idx,1);
        else plan[worst.mk][worst.idx] = {...worst.orig, g:newG};
      }
      addLowSeFiller(worst.mk);
      continue;
    }
    const worstKcal = ingNut(worst.orig.fk, worst.orig.g).kcal;

    const usedToday = usedFksToday();
    const sameCategoryAlternatives = Object.keys(FDB).filter(fk=>{
      if (usedToday.has(fk) || fk===worst.orig.fk) return false;
      const fd=FDB[fk]; if (!fd||fd._isRecipe||fd.cat!==worst.fd.cat||fd.cat==="מן החי") return false;
      if ((fd.per100.kcal||0)<=0) return false;
      const sePerKcal = (fd.per100.selenium||0)/fd.per100.kcal;
      return sePerKcal < worst.sePerKcal*0.6;
    }).sort((a,b)=>(FDB[a].per100.selenium/FDB[a].per100.kcal)-(FDB[b].per100.selenium/FDB[b].per100.kcal));

    if (sameCategoryAlternatives.length) {
      const subFk = sameCategoryAlternatives[0];
      const subFd = FDB[subFk];
      let newG = (worstKcal/subFd.per100.kcal)*100;
      const wholeStep = wholeUnitStepG(subFk);
      if (wholeStep) newG = Math.max(wholeStep, Math.round(newG/wholeStep)*wholeStep);
      if (subFd.cat==="פרי" && wholeStep) newG = wholeStep;
      plan[worst.mk][worst.idx] = {fk:subFk, g:Math.round(newG*10)/10};
      continue;
    }

    const wholeStep = wholeUnitStepG(worst.orig.fk);
    const minG = wholeStep ? wholeStep*0.5 : 2;
    if (worst.orig.g<=minG) { plan[worst.mk].splice(worst.idx,1); }
    else {
      const step = wholeStep || Math.max(2, Math.round(worst.orig.g*0.2));
      const newG = Math.max(minG, worst.orig.g-step);
      if (newG>=worst.orig.g) { plan[worst.mk].splice(worst.idx,1); }
      else plan[worst.mk][worst.idx] = {...worst.orig, g:newG};
    }
    addLowSeFiller(worst.mk);
  }
  return plan;
}
// פירוק משוער למרכיבים גולמיים עבור "מנות מוכנות" שקיימות במאגר כערך תזונתי אחד (per100) בלי מתכון רשום —
// כדי שגם הן יתפרקו כראוי ברשימת הקניות השבועית (ולא יופיעו כפריט קניה אחד לא-ניתן-לקנייה בשם "מג'דרה" למשל).
// היחסים משוערים לצורך רשימת קניות בלבד — אינם משפיעים על חישוב הערכים התזונתיים (שממשיך להתבסס על per100 המדויק).
const DISH_BREAKDOWN={
  tomatoSalsa:[{fk:"tomato",r:.65},{fk:"onion",r:.2},{fk:"cilantroLeaf",r:.1},{fk:"lemon",r:.05}],
};
// כינוי: ל"פשטידת כרובית" יש גם ערך per100 עצמאי במאגר וגם מתכון אמיתי עם רכיבים רשומים תחת מזהה אחר — מצביעים לאותו מתכון
const DISH_ALIAS={};
// מרכז את כל הארוחות של כל ימות השבוע לרשימת רכיבי מזון גולמיים בגרמים (מתכונים ומנות מוכנות מפורקים למרכיביהם היחסיים)
function computeShoppingList(meals,recipes){
  const recipeById={}; (recipes||[]).forEach(r=>{recipeById[r.id]=r;});
  const acc={};
  const add=(fk,g)=>{ if(!g||g<=0) return; acc[fk]=(acc[fk]||0)+g; };
  Object.values(meals||{}).forEach(day=>{
    MEAL_KEYS.forEach(mk=>{
      (day?.[mk]||[]).forEach(({fk,g})=>{
        const aliasId=DISH_ALIAS[fk];
        const rec=recipeById[fk]||(aliasId?recipeById[aliasId]:null);
        if(rec){
          const totalG=rec.ings.reduce((s,x)=>s+x.g,0)||1;
          const ratio=g/totalG;
          rec.ings.forEach(ri=>add(ri.fk,ri.g*ratio));
        } else if(DISH_BREAKDOWN[fk]){
          DISH_BREAKDOWN[fk].forEach(({fk:rfk,r})=>add(rfk,g*r));
        } else if(FDB[fk]){
          add(fk,g);
        }
      });
    });
  });
  return acc;
}
// מקבץ את התוצאה לפי קטגוריית מזון, ממויין לפי סדר הקטגוריות ולפי כמות יורדת בתוך כל קבוצה
function groupShoppingList(acc){
  const groups={};
  Object.entries(acc).forEach(([fk,g])=>{
    const fd=FDB[fk]; if(!fd) return;
    (groups[fd.cat]=groups[fd.cat]||[]).push({fk,g,fd});
  });
  CATEGORIES_HE.forEach(c=>{ if(groups[c]) groups[c].sort((a,b)=>b.g-a.g); });
  return groups;
}
