function isPantryFk(fk){const fd=FDB[fk];if(!fd)return false;return fd.cat==="תבלינים"||PANTRY_EXTRA_FKS.has(fk);}
// מיון "לפי סופר": קיבוץ קטגוריות התזונה למחלקות סופר פיזיות, לניווט מהיר בזמן קנייה בפועל
const AISLES_HE=["ירקנייה","מדף יבש וקטניות","מקררים ותחליפים","תבלינים ומדף אפייה","מוכן ושימורים"];
