const CAT_TO_AISLE={ירק:"ירקנייה",עלים:"ירקנייה",פרי:"ירקנייה",דגן:"מדף יבש וקטניות",קטנית:"מדף יבש וקטניות",זרעים:"מדף יבש וקטניות",אגוזים:"מדף יבש וקטניות",חלבון:"מקררים ותחליפים",שומן:"תבלינים ומדף אפייה",תבלינים:"תבלינים ומדף אפייה",תבשיל:"מוכן ושימורים",מרק:"מוכן ושימורים",מאפה:"מוכן ושימורים",מעובד:"מוכן ושימורים"};
