function balanceMealMacros(ings, kcalBudget, protectedFks=new Set(), vitEProtectThreshold=0){
  const scoreOf = mealMacroScore;
  const budget = kcalBudget==null ? Infinity : kcalBudget; // תקציב הקלוריות שמותר להוסיף בסה"כ (לא לגעת בו לצמצום)
  let list = (ings||[]).map(it=>({...it}));
  let kcalAdded = 0;
  // חיפוש "טיפוס גבעה" צעד-אחר-צעד: בכל סבב, בוחנים שלושה סוגי מהלכים אפשריים (צמצום פריט שומני קיים / הגדלת
  // פריט קטנית-חלבון קיים / הוספת פריט חלבון חדש) ובוחרים רק את המהלך שבאמת משפר הכי הרבה את הניקוד הכולל —
  // כך שאף מהלך לא "מתקן" מדד אחד תוך החמרה נטו של השני (הבאג הקודם: צמצום שומן שהוריד גם חלבון מתחת ליעד,
  // או הוספת חלבון שדחפה שומן מעל היעד). עוצרים כשאין יותר מהלך משפר, או אחרי תקרת צעדים סבירה.
  // מהלכי "הגדלה"/"הוספה" (היחידים שמוסיפים קלוריות) נבדקים תמיד מול kcalAdded+העלות שלהם ≤ budget — אם
  // התוספת הייתה חורגת מהתקציב שנותר ליום, המהלך פשוט לא נכלל בכלל במועמדים לאותו סבב (לא רק "מדורג נמוך")
  let guard=0;
  while (guard<24) {
    guard++;
    const cur = scoreOf(list);
    if (cur<=0.5) break; // כבר קרוב מספיק לשני היעדים
    let bestMove=null, bestScore=cur;

    // מהלך 1: צמצום כמות של פריט שתורם שומן — רק ממשפחות שומן מובהקות (שומן/אגוזים/זרעים), לעולם לא פירות/ירקות/
    // דגנים שרק "נוגעים" בסף השומן באקראי (למשל גויאבה) — היו מועמדים לצמצום גם הם למרות שאינם מקור שומן אמיתי.
    // הצמצום תמיד בקפיצות של יחידת-מידה שלמה כשקיימת (wholeUnitStepG) — לעולם לא לשבר לגרמים חסרי-משמעות
    // (כמו 41 גרם גויאבה או 4 גרם צ׳יה) שאי אפשר למדוד בפועל במטבח
    // תיקון-באג (לבקשת המשתמש, אחרי שנמצא שוויטמין E ירד עקבית מתחת ליעד למרות שהלולאה הקודמת "השיגה" אותו): מהלך
    // הצמצום הזה בדיוק היה האשם — אגוזים/זרעים/שמנים הם גם המקור העיקרי של ויטמין E וגם "משפחת שומן" נקודתית,
    // אז אם לולאת ההשלמה למעלה (כלל 4) הוסיפה פריט כזה כדי להגיע ליעד ויטמין E, הצמצום כאן (כדי לאזן שומן/חלבון)
    // היה עלול לצמצם בדיוק את אותו פריט בחזרה — לפעמים כמעט לגמרי — בלי שום מודעות לכך שהוא "מוגן". protectedFks
    // (מועבר מבחוץ, ריק כברירת מחדל לשאר הקוראים לפונקציה) חוסם רק את מהלך הצמצום הזה על אותם פריטים ספציפיים —
    // לא את מהלכי ההגדלה/הוספה/הסרת-מנה, כדי לא לפגוע ביכולת לאזן שומן/חלבון בדרכים אחרות
    const FAT_SHRINK_CATS = new Set(["שומן","אגוזים","זרעים"]);
    list.forEach((it,idx)=>{
      const fd=FDB[it.fk]||TEMP_FDB[it.fk];
      if (!fd||fd._isRecipe) return;
      if (protectedFks.has(it.fk)) return;
      if (!FAT_SHRINK_CATS.has(fd.cat)) return;
      const nut=ingNut(it.fk,it.g);
      if (vitEProtectThreshold>0 && nut.vitE>=vitEProtectThreshold) return; // לבקשת המשתמש: לא לצמצם תורם ויטמין-E משמעותי, אם יש עוד מועמדים
      if (nut.fat<0.5) return;
      const step = wholeUnitStepG(it.fk);
      let newG;
      if (step) {
        const curSteps = Math.round(it.g/step);
        newG = Math.round(Math.max(0,curSteps-1)*step*10)/10;
      } else {
        newG = Math.max(0,Math.round(it.g*0.7*10)/10);
      }
      const trial = newG<4 ? list.filter((_,i)=>i!==idx) : list.map((x,i)=>i===idx?{...x,g:newG}:x);
      const s=scoreOf(trial);
      if (s<bestScore) { bestScore=s; bestMove={type:"shrink",idx,newG}; }
    });

    // מהלך 2: הגדלת פריט קטנית/חלבון קיים (לא מתכון) — רק אם נכנס בתקציב הקלורי שנותר
    list.forEach((it,idx)=>{
      const fd=FDB[it.fk]||TEMP_FDB[it.fk];
      if (!fd||fd._isRecipe) return;
      if (fd.cat!=="קטנית" && fd.cat!=="חלבון") return;
      const wholeStep=wholeUnitStepG(it.fk);
      const extraG = wholeStep!=null ? wholeStep : Math.round(it.g*0.3*10)/10;
      if (extraG<=0) return;
      const addedKcal = ingNut(it.fk,extraG).kcal;
      if (kcalAdded + addedKcal > budget) return; // חורג מתקציב הקלוריות שנותר — לא מועמד בכלל
      const trial = list.map((x,i)=>i===idx?{...x,g:x.g+extraG}:x);
      const s=scoreOf(trial);
      if (s<bestScore) { bestScore=s; bestMove={type:"grow",idx,extraG,addedKcal}; }
    });

    // מהלך 3: הוספת פריט חלבון חדש שעדיין לא בארוחה — רק אם נכנס בתקציב הקלורי שנותר
    // תיקון-באג (לבקשת המשתמש, לאחר שנצפתה ארוחת בוקר עם 4 פריטי קטנית נפרדים נערמים זה על זה — חומוס+שעועית
    // שחורה+שעועית לבנה+עדשים אדומות, בלי שום דגן): PROTEIN_BOOST_ITEMS הוא כמעט כולו פריטי קטנית/סויה, ומהלך זה
    // רץ עד 24 סבבים — כל סבב יכול היה להוסיף עוד פריט קטנית שונה כדי לשפר את אחוז החלבון במעט, בלי שום מודעות
    // לכך שהארוחה כבר מכילה קטנית אחת. עכשיו, ברגע שיש כבר פריט קטנית אחד בארוחה (גולמי או מוטמע בתוך מתכון),
    // מהלך זה מפסיק להציע עוד מועמדי קטנית/סויה נוספים — מותר לו עדיין להגדיל את הכמות של הפריט הקיים (מהלך 2)
    const alreadyHasLegumeOrSoy = list.some(it=>{
      const fd=FDB[it.fk]||TEMP_FDB[it.fk]; if(!fd) return false;
      if (fd.cat==="קטנית") return true;
      if (fd._isRecipe) return (fd._ings||[]).some(ing=>(FDB[ing.fk]||TEMP_FDB[ing.fk])?.cat==="קטנית");
      return false;
    });
    const usedSet = new Set(list.map(x=>x.fk));
    if (!alreadyHasLegumeOrSoy) for (const fk of PROTEIN_BOOST_ITEMS) {
      if (usedSet.has(fk)) continue;
      const fd=FDB[fk]; if(!fd) continue;
      const g = wholeUnitStepG(fk) || (getServingUnit(fk,fd,"he")?.g||100);
      const addedKcal = ingNut(fk,g).kcal;
      if (kcalAdded + addedKcal > budget) continue; // חורג מתקציב הקלוריות שנותר — לא מועמד בכלל
      const trial = [...list, {fk,g,_id:uid()}];
      const s=scoreOf(trial);
      if (s<bestScore) { bestScore=s; bestMove={type:"add",fk,g,addedKcal}; }
    }
    // תיקון (לבקשת המשתמש: יחס 2/3 תבשילי קטניות, לא קטנית גולמית) — נמצא בסימולציה על 40 שבועות שזהו המהלך
    // הדומיננטי-הנסתר האמיתי: מהלך 3 מציע רק פריטי-קטנית/סויה גולמיים (PROTEIN_BOOST_ITEMS), לעולם לא
    // מתכון-תבשיל-קטניות, כך שברגע שאין עדיין קטנית בארוחה, האלגוריתם תמיד "פותר" את זה עם גולמי, גם כשיש
    // תבשיל-קטניות מתאים בתקציב. מוסיפים כאן את אותם מועמדי-תבשיל (מנה מלאה/חלקית) לאותה תחרות-ניקוד ממש —
    // האלגוריתם עדיין בוחר את מה שבאמת הכי משפר את הציון, אבל עכשיו למתכון יש הזדמנות הוגנת להתחרות בכלל
    if (!alreadyHasLegumeOrSoy) {
      const legumeStewCands = Object.keys(TEMP_FDB).filter(id=>{
        const fd=TEMP_FDB[id]; if(!fd||!fd._isRecipe) return false;
        return bookCategoryOf({name:fd.he,type:fd._recipeType,foodGroup:fd._foodGroup,ings:fd._ings})==="תבשילי קטניות";
      });
      for (const rfk of legumeStewCands) {
        if (usedSet.has(rfk)) continue;
        const rfd = TEMP_FDB[rfk]; if (!rfd) continue;
        const fullG = rfd._servingG || 200;
        // תיקון (לבקשת המשתמש: "אל תציע רבעי מנות, רק שלמות") — מתכון מוצע רק במנה מלאה (הוסרו הניסיונות
        // במנות-חלקיות ¾/½/⅓ שהוספו בסבב הקודם לשיפור-יחס-הקטניות; זה בא על חשבון תצוגה של "¼ מנה"/"0 מנה"
        // מבלבלת ולא-אמיתית, שהמשתמש קבע כבלתי-קבילה)
        const rg = fullG;
        const rnut = ingNut(rfk, rg);
        if (rnut.kcal>0 && kcalAdded+rnut.kcal <= budget) {
          const rtrial = [...list, {fk:rfk,g:rg,_id:uid()}];
          const rs = scoreOf(rtrial);
          if (rs<bestScore) { bestScore=rs; bestMove={type:"add",fk:rfk,g:rg,addedKcal:rnut.kcal}; }
        }
      }
    }

    // מהלך 4 (חדש — לבקשת המשתמש, כדי ששומן≤25% יעמוד "בכל מקרה"): הסרה מלאה של מנה מורכבת עתירת-שומן —
    // מתכון (fd._isRecipe) או מנה גולמית מה-DB מקטגוריית תבשיל/מרק/מאפה/מעובד. מהלכים 1-3 לעולם לא נוגעים
    // בפריטים כאלה (הם לא "משפחת שומן" נקודתית, ולא ניתנים לצמצום הדרגתי — מנה היא תמיד יחידה שלמה אחת או
    // כלום), כך שקודם לתיקון הזה מנה עתירת-שומן בודדת (כמו חומוס+טחינה ביתי) יכלה לתקוע את הארוחה מעל 25%
    // שומן לצמיתות, בלי שום מהלך זמין שיכול לתקן זאת. בניגוד למהלכים 1-3, זו הסרה מלאה בלבד — אין "קצת פחות מנה"
    // תיקון-באג (לבקשת המשתמש, אחרי הרצת סימולציה על 30 שבועות שהראתה שרק 17% מהקטניות מגיעות כתבשיל-מתכון):
    // אותר שהמהלך הזה בדיוק היה הגורם הדומיננטי-הנסתר — מתכון-תבשיל-קטניות (לרוב מבוסס טופו/תמפה, עם שומן
    // בינוני) נבחר כאן פעמים רבות כ"מנה עתירת-שומן להסרה", ומהלך 3 מיד החליף אותו בקטנית גולמית רזה יותר
    // (חומוס/עדשים) כדי לשפר את אחוז-השומן — כך שהתבשיל-מהמתכונים נמחק לגמרי ולא הופיע כלל בפלט הסופי, גם
    // כשההוספה-בשלב-המוקדם-יותר בפועל הצליחה. מוגנים עכשיו מהסרה כאן מתכונים שמכילים קטנית (בין אם קוטגוריה
    // "טהורה" ובין אם קטנית+דגן משולבים) — שאר סוגי המתכונים (פשטידה/מרק ללא קטנית וכו') עדיין ניתנים להסרה כרגיל
    // תיקון-באג נוסף (לבקשת המשתמש: "נעלמו המנות ממתכונים, במיוחד תבשילי דגנים" — אותר בדיוק-דיבוג: מתכון-
    // תבשיל-דגן הצליח ב-tryAdd בשלב הראשוני, אך נעלם מהפלט הסופי) — אותה בעיה בדיוק, רק שההגנה כאן הוגבלה
    // לקטנית בלבד ומעולם לא הורחבה לדגן, למרות שדגן סובל מאותה תופעה זהה: מתכון-תבשיל-דגן (אורז/בורגול/קינואה)
    // גם הוא לרוב עתיר-שומן-בינוני יחסית לחלופה הגולמית (אורז/בורגול פשוט), ונבחר כאן להסרה מאותה סיבה בדיוק
    const RECIPE_HAS_LEGUME_INGS = it => {
      const fd=FDB[it.fk]||TEMP_FDB[it.fk];
      return !!(fd && fd._isRecipe && (fd._ings||[]).some(ing=>(FDB[ing.fk]||TEMP_FDB[ing.fk])?.cat==="קטנית"));
    };
    const RECIPE_HAS_GRAIN_INGS = it => {
      const fd=FDB[it.fk]||TEMP_FDB[it.fk];
      return !!(fd && fd._isRecipe && (fd._ings||[]).some(ing=>(FDB[ing.fk]||TEMP_FDB[ing.fk])?.cat==="דגן"));
    };
    list.forEach((it,idx)=>{
      const fd=FDB[it.fk]||TEMP_FDB[it.fk];
      if (!fd) return;
      if (RECIPE_HAS_LEGUME_INGS(it) || RECIPE_HAS_GRAIN_INGS(it)) return;
      const isDish = fd._isRecipe || ["תבשיל","מרק","מאפה","מעובד"].includes(fd.cat);
      if (!isDish) return;
      const nut=ingNut(it.fk,it.g);
      if (nut.fat<1) return; // מנות כמעט-נטולות-שומן לא מועמדות — אין טעם להסיר אותן בשביל שומן
      const trial = list.filter((_,i)=>i!==idx);
      const s=scoreOf(trial);
      if (s<bestScore) { bestScore=s; bestMove={type:"removeDish",idx}; }
    });

    if (!bestMove) break; // אין אף מהלך שמשפר את הניקוד הכולל בלי לחרוג מהתקציב — עוצרים כאן, גם אם היעד לא הושג במלואו
    if (bestMove.type==="shrink") {
      const {idx,newG}=bestMove;
      if (newG<4) list.splice(idx,1); else list[idx]={...list[idx],g:newG};
    } else if (bestMove.type==="grow") {
      const {idx,extraG,addedKcal}=bestMove;
      list[idx]={...list[idx], g:list[idx].g+extraG};
      kcalAdded += addedKcal;
    } else if (bestMove.type==="add") {
      list.push({fk:bestMove.fk, g:bestMove.g, _id:uid()});
      kcalAdded += bestMove.addedKcal;
    } else if (bestMove.type==="removeDish") {
      // תיקון-באג (לבקשת המשתמש, לאחר אכיפת תקרת 100% קלוריות): הסרת מנה משחררת בפועל קלוריות אמיתיות
      // מהתקציב היומי — אם לא זוקפים את זה כאן, kcalAdded נשאר כאילו שום דבר לא השתחרר, וכל מהלך "הוספה/הגדלה"
      // הבא באותו סבב עדיין נבדק מול אותה תקרה מקורית הקטנה, למרות שבפועל התפנה מקום גדול בהרבה. בלי התיקון
      // הזה, הסרת מנה עתירת-שומן (למשל 550 קק"ל) יכלה להשאיר את הארוחה עם "חור" קלורי גדול לצמיתות, גם כשהיה
      // אפשר למלא חלק ממנו בפריט חלבון חלופי דל-שומן יותר
      const removedNut = ingNut(list[bestMove.idx].fk, list[bestMove.idx].g);
      kcalAdded -= removedNut.kcal;
      list.splice(bestMove.idx,1);
    }
  }
  return list;
}


// משווה בין רשימת המרכיבים המקורית לבין הרשימה המאוזנת, ומחזירה בדיוק אילו פריטים נוספו/גדלו/הוקטנו/הוסרו —
// כדי שלפני לחיצה על "החל" אפשר יהיה לראות במדויק מה ישתנה בארוחה, לא רק את אחוזי המאקרו לפני/אחרי
function diffMealIngredients(before,after,lang){
  const beforeMap=new Map((before||[]).map(it=>[it.fk,it.g]));
  const afterMap=new Map((after||[]).map(it=>[it.fk,it.g]));
  const changes=[];
  afterMap.forEach((g,fk)=>{
    const oldG=beforeMap.get(fk);
    if (oldG==null) changes.push({fk,type:"added",newG:g,name:foodName(fk,lang)});
    else if (Math.abs(g-oldG)>0.5) changes.push({fk,type:g>oldG?"increased":"decreased",oldG,newG:g,name:foodName(fk,lang)});
  });
  beforeMap.forEach((g,fk)=>{
    if (!afterMap.has(fk)) changes.push({fk,type:"removed",oldG:g,name:foodName(fk,lang)});
  });
  return changes;
}


// כלל "יחידה שלמה בלבד": מזון שנמדד ביחידה טבעית/ביתית (עלה, אגוז, פרי, כוס, כף, פרוסה...) לעולם לא נחתך לחלקי-יחידה —
// כמו שתזונאי אמיתי היה חושב (2 או 3 עלי חסה, לא 2.5; אגוז ברזיל שלם, לא חצי; כוס שלמה, לא 0.88 כוס).
// מוחרג: מתכונים (מנה שלמה ממילא), תבלינים (מקובל למדוד ב-½/¼ כפית), וקטניות יבשות הנמדדות במפורש בגרם (weightOnly).
function wholeUnitStepG(fk){
  const fd=FDB[fk]||TEMP_FDB[fk];
  if(!fd||fd._isRecipe||fd.cat==="תבלינים") return null;
  const su=getServingUnit(fk,fd,"he");
  if(!su||su.weightOnly) return null;
  return su.g/(su.count||1);
}
// "מנה מורכבת": מתכון שהמשתמש יצר, או מזון מוגמר/מורכב בבסיס הנתונים (תבשיל, מרק, מאפה, מעובד — כלומר מנה שלמה בפני עצמה,
// לא רכיב בודד כמו ירק/פרי/דגן). לעולם לא מוצע פעמיים באותו יום — בדיוק כמו שתזונאי לא היה מגיש את אותו תבשיל גם לצהריים וגם לערב.
function isDishFk(fk){
  const fd=FDB[fk]||TEMP_FDB[fk];
  if(!fd) return false;
  return !!fd._isRecipe || ["תבשיל","מרק","מאפה","מעובד"].includes(fd.cat);
}
// תיקון-עצמי סופי: כל "מנה מורכבת" (מתכון שהמשתמש יצר, או מזון מוגמר מה-DB כמו תבשיל/מרק/מאפה/מעובד) היא תמיד מספר שלם
// של מנות — לעולם לא "¾ מנה" או "0.96 מנה". זה מתקן גם פריטים ישנים/תקועים מנתונים קודמים, לא רק פריטים חדשים שנוצרים כרגע.
// תיקון (לבקשת המשתמש, אחרי דיווח על "0.88 מנה אבוקדו" בפועל): החרגת קטגוריית "שומן" כולה מעיגול-ליחידות
// הייתה רחבה מדי — אבוקדו כן נכלל בקטגוריה הזו אבל יש לו יחידה טבעית ומשמעותית ("חצי אבוקדו"), בניגוד לשמן/
// טחינה/חמאות-אגוזים שהם באמת גמישים-רציפים (נמדדים בכפות אבל בלי "יחידה שלמה" טבעית). רק אלה מוחרגים כאן
const CONTINUOUS_FLEXIBLE_FKS = new Set(["oliveOil","tahini","tahiniRaw","tahiniFullRaw","cocoaButter","almondbutter","peanutButter"]);
function isWholeUnitCountable(fk, fd){
  if (!fd || fd._isRecipe) return false;
  if (fd.cat==="תבלינים") return false;
  if (CONTINUOUS_FLEXIBLE_FKS.has(fk)) return false;
  return true;
}
function normalizeRecipeServings(items){
  return (items||[]).map(it=>{
    const fd=FDB[it.fk]||TEMP_FDB[it.fk];
    if (!fd) return it;
    if (isDishFk(it.fk)) {
      const step = fd._isRecipe ? (fd._servingG||80) : (wholeUnitStepG(it.fk)||fd._servingG||100);
      const n = Math.max(1, Math.round(it.g/step));
      return {...it, g: Math.round(n*step*100)/100};
    }
    // תיקון (לבקשת המשתמש: "אל תציע 0.93 מנה, רק יחידות שלמות") — הפונקציה הזו טיפלה עד כה רק ב"מנות
    // מורכבות" (מתכון/תבשיל/מרק/מאפה), לא בפריטים גולמיים נספרים כמו דגן/קטנית/מוצרי-סויה (כוס קינואה,
    // כוס חומוס, גביע יוגורט) — שיכולים לצאת עם כמות שברית (0.93 כוס) ממנגנוני-תיקון מאוחרים יותר (קיצוץ-
    // תקרה, מילוי-רצפה, גיוון-קטניות). כאן מעגלים גם אותם ליחידה שלמה — לא שמן/תבלינים, שנשארים גמישים בכוונה
    if (!fd._isRecipe && isWholeUnitCountable(it.fk, fd)) {
      const step = wholeUnitStepG(it.fk);
      if (step && step>0) {
        const n = Math.round(it.g/step);
        if (n<=0) return null;
        return {...it, g: Math.round(n*step*100)/100};
      }
    }
    return it;
  }).filter(Boolean);
}

// רשת ביטחון סופית מאוחדת (לבקשת המשתמש, כמה כללים בבת אחת): רצה כצעד ממש-אחרון בכל אחד משלושת מחוללי היום
// (generateDayPlan / generatePersonalDayPlan / generateRecipesNSFDayPlan — וכל מה שעוטף אותם, כמו
// generateMixedDayPlan/generateWeekPlan) — אחרי כל שלבי הבנייה/איזון/מילוי הקודמים, כדי לתפוס כל הפרה
// אפשרית ללא תלות באיזה שלב מוקדם יותר גרם לה (למשל growMealS/growMealS2/FILLER_POOL שיכולים להגדיל פריט
