// לבקשת המשתמש (אחרי דיווח על שעועית מאש + תבשיל שעועית לבנה יחד בצהריים, ואז שעועית פינטו שוב בערב):
// הגדרת "משפחת קטנית" — סוגי שעועית שונים (לבנה/שחורה/מאש/פינטו/אדומה) נחשבים לאותה משפחה לצורך גיוון,
// גם אם המין הבוטני שונה. פועל גם על פריטים גולמיים (לא רק מתכונים, בניגוד לגרסה הקודמת)
function legumeFamilyOf(fk){
  const BEANS = new Set(["whiteBeans","blackBeans","redKidney","pintoBeans","mungBeans","broadBeans","blackEyedPeas"]);
  const LENTILS = new Set(["redLentils","greenLentils","brownLentils","blackLentils"]);
  const CHICKPEAS = new Set(["chickpeas","chickpeaFlour"]);
  const PEAS = new Set(["greenPeas","splitPeas"]);
  const SOY = new Set(["tofu","tempeh","natto","edamame"]);
  const OTHER = new Set(["lupinBeans","lupinBeansCooked"]);
  if (BEANS.has(fk)) return "beans";
  if (LENTILS.has(fk)) return "lentils";
  if (CHICKPEAS.has(fk)) return "chickpeas";
  if (PEAS.has(fk)) return "peas";
  if (SOY.has(fk)) return "soy";
  if (OTHER.has(fk)) return "other";
  return fk;
}
function legumeFamilyOfItem(it){
  const fd = FDB[it.fk]||TEMP_FDB[it.fk]; if (!fd) return null;
  if (!fd._isRecipe) return fd.cat==="קטנית" ? legumeFamilyOf(it.fk) : null;
  const domFk = dominantLegumeFk(fd);
  return domFk ? legumeFamilyOf(domFk) : null;
}
function enforceLegumeVarietyInMeal(plan){
  Object.keys(plan).forEach(mk=>{
    const items = plan[mk]||[];
    const withFamily = items.map((it,idx)=>({it,idx,fam:legumeFamilyOfItem(it)})).filter(x=>x.fam);
    if (withFamily.length<=1) return;
    const groups = {};
    withFamily.forEach(x=>{ (groups[x.fam]=groups[x.fam]||[]).push(x); });
    const removeIdxSet = new Set();
    Object.values(groups).forEach(group=>{
      if (group.length<=1) return;
      const sorted=[...group].sort((a,b)=>ingNut(b.it.fk,b.it.g).kcal-ingNut(a.it.fk,a.it.g).kcal);
      sorted.slice(1).forEach(x=>removeIdxSet.add(x.idx));
    });
    if (removeIdxSet.size) plan[mk]=items.filter((it,idx)=>!removeIdxSet.has(idx));
  });
  return plan;
}
