  const RAW_LEGUME_GRAIN_STAPLE = new Set(["chickpeas","redLentils","blackBeans","whiteBeans","greenLentils","mungBeans","splitPeas","brownRiceCooked","quinoaCooked","pearlBarleyCooked","freekeh","couscousCooked","buckwheatCooked","bulgurCooked"]);
