  let sodiumUsed=0, potassiumUsed=0, phosphorusUsed=0, dayKcalUsed=0;
  // תיקון (לבקשת המשתמש: "בצע את השינוי הנדרש" — הפוך את שלב הבחירה עצמו למודע-מצטבר לשומן/מנגן, לא רק תיקון
  // מאוחר בלולאות-מילוי): נמצא חוזר ונשנה שקצב-השומן/מנגן כבר חורג מהתקרה מתוך המתכונים שנבחרו כאן, בשלב
  // הבנייה הראשי — לפני שכל לולאת-מילוי מאוחרת יותר בכלל רצה. אותו דפוס בדיוק כמו sodiumUsed/potassiumUsed/
  // phosphorusUsed למעלה (שכבר עובד היטב ומונע חריגות דומות) מיושם כאן גם לשומן ומנגן: מעקב מצטבר, ונדחה כל
  // מועמד (מתכון או פריט גולמי) שהיה דוחף את הסך-היומי מעל התקרה — כדי שהקורא ינסה את המועמד הבא ברשימה
  const fatCapG = (tgt*0.26)/9;
  const manganeseCapMg = dri?.manganese?.ul || 15;
  // תיקון (לבקשת המשתמש: "כעת גם מנגן וגם סלניום חורגים") — אותו דפוס בדיוק, מורחב לסלניום: אין שום מנגנון-
  // אכיפה שהיה קיים לו קודם, למרות שהממשק עצמו מזהיר שזה אחד משלושת הנוטריאנטים שבאמת אפשר לחצות (בעיקר
  // אגוזי ברזיל, 1917 מק"ג/100 גר')
  const seleniumCapMcg = dri?.selenium?.ul || 400;
  let fatUsed=0, manganeseUsed=0, seleniumUsed=0;
  const usedFks = new Set(excludedFks); // כל פריט/מתכון פעם אחת בלבד ליום (חוץ ממשקה סויה/קינמון/מלח — ראו כלל 8/3 למטה) + זריעת המרכיבים הנמנעים
  // לבקשת המשתמש (אחרי שנמצא שוויטמין E ירד עקבית מתחת ליעד): פריטים שנוספו במפורש כדי להשלים כולין/ויטמין E
  // (כלל 4 למטה) מסומנים כאן כ"מוגנים" — trimMealS/trimMealS2/balanceMealMacros (בהמשך) מדלגים עליהם בבואם
  // לצמצם/להסיר פריט, כדי לא לבטל בשלב מאוחר יותר בדיוק את מה שהתווסף כדי להשיג את היעד
  const protectedMicroFks = new Set();
  // אותו תיקון, אבל דינמי (לא רק על פריטים שנוספו במפורש למעלה): כל פריט שתורם באמת משמעותית לוויטמין E באותו
  // רגע (≥10% מהיעד היומי במנה אחת — למשל זרעי חמניה/שקדים/שמן זית) מוגן גם הוא מצמצום/הסרה בכל שלושת המקומות,
  // כי התברר בבדיקה שרוב המקרים של ירידת ויטמין E לא הגיעו מפריטים שהלולאה למטה הוסיפה בעצמה, אלא מפריטים
  // עתירי-ויטמין-E שכבר היו חלק מהבחירה הראשונית (מתכון/מזון) והוסרו/צומצמו בטעות בשלבי האיזון המאוחרים יותר
  const vitEProtectThreshold = (dri?.vitE?.dri||15) * 0.03; // נבדק אמפירית מול 5% ו-10% — 3% נתן את השיפור הכי גדול בוויטמין E בלי לפגוע בקלוריות/נתרן

  const plan = {breakfast:[],snack:[],lunch:[],dinner:[]};
  // חלוקת תקציב בין הארוחות: בוקר מוגדל (יעד ≥700 קק"ל בהמשך), צהריים מוגדל מעט, ערב מצומצם, ביניים ללא שינוי
  const SHARE = {breakfast:.34, snack:.06, lunch:.34, dinner:.25};
  // גיל 65+: ארוחת הערב היא ארוחת חלבון — מקבלת מעט יותר מתקציב היום (על חשבון הבוקר)
  if ((dri?._age||0)>=65) { SHARE.dinner=.29; SHARE.breakfast=.30; }
  // כלל 9: ארוחת ביניים מטופלת בנפרד לגמרי בהמשך (אך ורק פרי) — כל שאר השלבים (מתכונים/ירק/משקה סויה+קינמון/
  // מילוי כללי) פועלים רק על שלוש הארוחות האחרות
  const NON_SNACK_MEALS = ["breakfast","lunch","dinner"];
  const MEAL_KEYS_LOCAL = ["breakfast","snack","lunch","dinner"];

  // budgetMult: כמה "גמישות" מעל תקציב-הארוחה הרגיל (SHARE[mk]) מותר לפריט בודד לחרוג ממנו. ברירת המחדל שונה
  // בין מתכון לפריט גולמי (ראו למטה) — שלב הסגירה הסופי (רצפת 99% קלורית) מעביר ערך גבוה בהרבה (3.0) במפורש
  // עבור שניהם, כי באותו שלב המטרה היחידה היא לקרב את סך היום ליעד; התקרה האמיתית שלא ניתן לחרוג ממנה היא
  // hardCapKcal הכוללת (globalHeadroom), לא חלוקת ה-SHARE בין הארוחות.
  // תיקון (לבקשת המשתמש — מתכון גדול "בלע" ארוחה שלמה ולא השאיר מקום לשום פריט נוסף, מה שיצר ארוחות
  // חד-גוניות של פריט אחד בלבד): לברירת המחדל של מתכון (fd._isRecipe) יש עכשיו תקרה נמוכה יותר (0.9, כלומר
  // *מתחת* לתקציב הרגיל של הארוחה, לא מעליו) — כדי שתמיד יישאר מרווח לפריטי ירק/פרי/אגוזים/זרעים שמתווספים
  // אחרי שלב מיקום המתכונים. פריטים גולמיים ממשיכים לקבל 1.25 כרגיל (לא היו הגורם לבעיה)
  function tryAdd(mk, fk, budgetMult){
    if (usedFks.has(fk)) return false;
    const fd = FDB[fk]||TEMP_FDB[fk]; if(!fd) return false;
    if (budgetMult==null) budgetMult = fd._isRecipe ? 0.9 : 1.25;
    // כלל 7 (מתוקן): פריטי "אגוזים" מוגבלים לכל היותר ל-10 גרם (15 גרם לאגוזי מלך) — אבל במקום לגזור ישירות
    // כמות גרם שרירותית (שיכולה ליצור חלקי-יחידה מוזרים כמו "17.5 פיסטוקים"), התקרה עצמה מוגדרת כיחידה-שלמה
    // מלאכותית אחת: לפריט עם ספירת-יחידות טבעית (כמו פיסטוקים, שם היחידה היא גרגר בודד) מחשבים כמה גרגרים
    // שלמים נכנסים בתקרת המשקל ומעגלים למטה (וכן — לפיסטוקים במפורש לא יותר מ-10 גרגרים, גם אם התקרה המשקלית
    // הייתה מאפשרת מעט יותר/פחות), ולפריט בלי ספירת-יחידות (כמו בוטנים) התקרה עצמה היא ה"יחידה". כך שלב
    // ה-wholeStep הרגיל (שכבר מטפל נכון ביחידות שלמות + תקציב) עושה את שאר העבודה: או שכל התקרה נכנסת בתקציב
    // (n=1), או שכלום לא נכנס (n=0, מדלגים) — לעולם לא פרוסה זעירה/חלקית של אגוז (כלל 1: לא חלקים זעירים של
    // בוטנים; כלל 2: לא 17.5 פיסטוקים, רק 18 גרגרים שלמים לכל היותר, או כלום)
    const isNutsCat = fd.cat==="אגוזים";
    let g = servingG(fk);
    let wholeStep;
    if (isNutsCat) {
      const capG = fk==="walnuts" ? 15 : 10;
      const su = getServingUnit(fk, fd, "he");
      if (su && su.count) {
        const gramsPerPiece = su.g/su.count;
        const pieceCap = fk==="pistachio" ? 10 : Math.max(1, Math.floor(capG/gramsPerPiece));
        wholeStep = pieceCap*gramsPerPiece;
      } else {
        wholeStep = capG;
      }
      g = wholeStep;
    } else {
      wholeStep = wholeUnitStepG(fk);
      if (wholeStep!=null) g = Math.max(wholeStep, Math.round(g/wholeStep)*wholeStep);
    }
    const mealBudget = tgt*SHARE[mk] - sumNuts(plan[mk].map(({fk,g,soaked})=>ingNut(fk,g,soaked))).kcal;
    const globalHeadroom = hardCapKcal - dayKcalUsed;
    const budget = Math.max(0, Math.min(mealBudget*budgetMult, globalHeadroom)); // מעט גמישות מעל תקציב-הארוחה, אך לעולם לא מעל התקרה הקשיחה הכוללת
    let nut = ingNut(fk,g);
    if (fd._isRecipe) {
      // תיקון (לבקשת המשתמש: "אל תציע רבעי מנות, רק שלמות") — הוסר הניסיון במנות-חלקיות (¾/½/⅓) שהוסף בסבב
      // קודם: מתכון מוצע רק כמנה מלאה; אם מנה מלאה לא נכנסת בתקציב, פשוט לא מוצע כאן בכלל (כמו לפני התיקון ההוא)
      if (nut.kcal > budget || nut.kcal <= 0) return false;
    } else if (wholeStep!=null) {
      let n = isNutsCat ? 1 : Math.round(g/wholeStep); // לאגוזים: תמיד "כל התקרה או כלום" — לעולם לא כפולות
      const unitNut = ingNut(fk,wholeStep);
      if (unitNut.kcal>0) n = Math.min(n, Math.floor(budget/unitNut.kcal + 1e-9));
      if (unitNut.sodium>0) n = Math.min(n, Math.floor((sodiumCap-sodiumUsed)/unitNut.sodium + 1e-9));
      if (n < 1) return false;
      g = n*wholeStep; nut = ingNut(fk,g);
    } else {
      if (nut.kcal<=0) return false;
      if (nut.kcal > budget) {
        if (budget <= 5) return false;
        const scale = budget/nut.kcal;
        if (scale < 0.4) return false;
        g = Math.round(g*scale*10)/10; nut = ingNut(fk,g);
      }
    }
    if (nut.sodium > (sodiumCap-sodiumUsed) + 0.5) return false;
    if (potassiumCap!=null && nut.potassium > (potassiumCap-potassiumUsed) + 0.5) return false;
    if (phosphorusCap!=null && nut.phosphorus > (phosphorusCap-phosphorusUsed) + 0.5) return false;
    // תיקון (לבקשת המשתמש: "בצע את השינוי הנדרש") — דוחים כאן, בשלב הבחירה עצמו, כל מועמד (מתכון/פריט) שהיה
    // דוחף את סך-היום מעל תקרת השומן (25% מהקלוריות) או תקרת המנגן (UL) — לפני שהוא בכלל נוסף, לא אחרי
    if (nut.fat > (fatCapG-fatUsed) + 0.5) return false;
    if (nut.manganese > (manganeseCapMg-manganeseUsed) + 0.3) return false;
    if (nut.selenium > (seleniumCapMcg-seleniumUsed) + 10) return false;
    // תיקון (לבקשת המשתמש: "אל תציע יותר משתי מנות של אותו תבשיל/מזון באותה ארוחה") — בדוק
    // כמה פעמים הצעת את אותו fk בארוחה הזאת כבר, ואם כבר שתיים — דחה
    const sameItemCountInMeal = (plan[mk]||[]).filter(item=>item.fk===fk).length;
    if (sameItemCountInMeal >= 2) return false;
    plan[mk].push({fk,g});
    usedFks.add(fk);
    dayKcalUsed += nut.kcal; sodiumUsed += nut.sodium||0; potassiumUsed += nut.potassium||0; phosphorusUsed += nut.phosphorus||0;
    fatUsed += nut.fat||0; manganeseUsed += nut.manganese||0; seleniumUsed += nut.selenium||0;
    return true;
  }

  // תיקון-באג (לבקשת המשתמש, אחרי גילוי מקרה עודף-יוד עצום של כ-694%): וואקמה שייכת קטגורית ל"ירק" ולכן נכנסה
  // בעבר גם ל-vegPool הכללי (מילוי "עוד ירק" גנרי לארוחה בלי סלט) — בלי שום התחשבות בכך שהיא ריכוזית ביוד פי
  // מאות מירק רגיל (24,000 מק"ג/100 גר' יבש). זה יכול היה להוסיף אותה כ"ירק סתם" באופן מקרי, ולפעמים אף לצד
  // מתכון סלט-הוואקמה עצמו (שכבר מכיל וואקמה), מה שיצר את העודף העצום שנצפה. כעת וואקמה מוחרגת מה-vegPool
  // הכללי — הכניסה היחידה שלה לתפריט היא דרך מתכון סלט-הוואקמה, או דרך מנגנון השלמת-היוד הייעודי למטה
  // תיקון (לבקשת המשתמש): בצל ירוק מוחרג גם כאן — הגיוני כרכיב בתוך תבשיל/סלט, לא כ"ירק" עצמאי מלא בפני עצמו
  // תיקון (לבקשת המשתמש: מציאת "תפוח אדמה טרי" בפועל בסימולציה) — המאגר הזה נבנה דינמית מכל פריטי-FDB עם
  // cat="ירק", בלי לעבור דרך EXCLUDED_FKS (שמשמש רק ל-rawPool במקום אחר) — כך שפקעות-גולמיות חמקו מהתיקון
  // הקודם. מוחרגות כאן גם הן במפורש, לא רק wakame/springOnion
  const vegPool = Object.keys(FDB).filter(fk=>FDB[fk]?.cat==="ירק" && fk!=="wakame" && fk!=="springOnion" && fk!=="potatoRaw" && fk!=="sweetPotatoRaw" && !RECIPE_ONLY_FKS.has(fk) && !FDB[fk]?._isRecipe);
  // כלל 1+2+6: מנסים למקם מתכון בכל אחת משלוש הארוחות הראשיות (לא בארוחת ביניים — כלל 9). מעדיפים בסדר הבא:
  // (א) "סלט ארוחה גדול" עם וואקמה — אך ורק פעם אחת קבועה בשבוע (ראה isWakameSaladDay למטה), (ב) מתכוני
  // "סלט" בעלי שם מועדף במפורש — סלט בסיס / סלט כרובים / סלט ארוחה קטן / סלט ארוחה בינוני, (ג) כל מתכון סלט
  // אחר (מזוהה לפי המילה "סלט" בשם), (ד) כל מתכון אחר. מסמנים לכל ארוחה אם קיבלה סלט בסוף
  const isSaladRecipe = r => (r?.name||"").includes("סלט") || SALAD_FOOD_GROUPS.has(r?.foodGroup);
  const PRIORITY_SALAD_NAMES = ["סלט בסיס","סלט כרובים","סלט ארוחה קטן","סלט ארוחה בינוני"];
  const isPrioritySaladRecipe = r => PRIORITY_SALAD_NAMES.some(name=>(r?.name||"").includes(name)) || r?.foodGroup==="סלט_בסיס";
  const recipeByIdNSF = {}; recipes.forEach(r=>{ recipeByIdNSF[r.id]=r; });
  // "משפחת סויה" רחבה — מוגדר כאן מוקדם (לפני כל שלבי מיקום המתכונים/סלטים) כדי שגם שלב א'/ב' (וואקמה/סלט) יוכלו
  // להשתמש בזה, לא רק שלב המילוי הכללי המאוחר יותר. בודק גם מתכון שמכיל רכיב-סויה כרכיב פנימי (למשל שקשוקה עם
  // טופו, או "קערת יוגורט סויה..."/"סלט חוגורט" עם יוגורט סויה) — כך שכל מתכון עתידי עם רכיב סויה מכוסה אוטומטית
  const SOY_FAMILY_NSF = new Set(["edamame","tofu","tempeh","natto","soymilkOrgPlain","soymilkFortified","soyYogurtPlain","soyYogurtOrgPlain"]);
  const isSoyFamilyItem = fk => {
    if (SOY_FAMILY_NSF.has(fk)) return true;
    const r = recipeByIdNSF[fk];
    return r ? (r.ings||[]).some(ing=>SOY_FAMILY_NSF.has(ing.fk)) : false;
  };
  const soyFamilyAlreadyInMeal = mk => plan[mk].some(it=>isSoyFamilyItem(it.fk));
  // עוזר כללי (לא רק סויה): בודק אם רכיב גולמי מסוים כבר נמצא בארוחה — כפריט עצמאי, או "מוסתר" בתוך מתכון שכבר
  // בארוחה (למשל זרעי פשתן בתוך "קערת יוגורט..." לא רק כפריט זרעי-פשתן עצמאי). משמש למניעת כפילות רכיב כשמתכון
  // ופריט גולמי זהה מגיעים משני שלבים נפרדים (למשל שלב המילוי הכללי של פשתן/צ'יה לעומת מתכון שכבר מכיל אותם)
  const ingredientAlreadyInMeal = (mk, fk) => plan[mk].some(it=>{
    if (it.fk===fk) return true;
    const r = recipeByIdNSF[it.fk];
    return r ? (r.ings||[]).some(ing=>ing.fk===fk) : false;
  });
  // כלל "זרע אחד לארוחה" (לא רק לא לחזור על אותו סוג זרע, אלא לא לערבב שני סוגי זרעים שונים, למשל פשתן+צ'יה,
  // באותה ארוחה) — בודק גם זרעים "מוסתרים" בתוך מתכון שכבר בארוחה, לא רק פריטי זרעים עצמאיים. מוגדר כאן מוקדם
  // כדי שגם שלב חלוקת הפשתן/צ'יה הייעודי (למטה) יוכל להשתמש בו, לא רק שלב המילוי הכללי המאוחר יותר
  const mealHasAnySeed = mk => plan[mk].some(it=>{
    const fd=FDB[it.fk]||TEMP_FDB[it.fk];
    if (fd?.cat==="זרעים") return true;
    const r = recipeByIdNSF[it.fk];
    return r ? (r.ings||[]).some(ing=>(FDB[ing.fk]?.cat)==="זרעים") : false;
  });

  // ===== כללי צירוף מתכונים לארוחות, לפי קטגוריות ספר המתכונים (לבקשת המשתמש) =====
  // צהריים: תבשיל דגן + תבשיל קטניות + סלט ירקות יחד.
  // בוקר: ארוחת סלט (בכל גודל) + משקה סויה/יוגורט סויה; אם הסלט "קטן" — גם מאפה וגם ממרח.
  // ערב: מסלול א' (תבשיל דגן + תבשיל קטניות, מנות קטנות-קלוריה) או מסלול ב' (קערה/פשטידה + מרק).
  // כל השלבים כאן רק מנסים (tryAdd מכבד תקציב/נתרן/כפילויות כרגיל) — אם לא נכנס, שלבי המילוי הכלליים שכבר קיימים ממשיכים כרגיל.
  const catOfRecipeId = fk => { const r=recipeByIdNSF[fk]; return r ? bookCategoryOf(r) : null; };
  // תיקון (לבקשת המשתמש): "סלט עדשים ירוקות" ודומיו מסווגים כ"סלטי ירקות" רק כי יש "סלט" בשם — אבל הם בעיקר
  // קטנית (עדשים), לא ירק. שתי הפונקציות האלה מזהות זאת, כדי (א) לא לסמוך על "סלט" כזה כמקור הירק המובטח של
  // הארוחה, ו-(ב) לא להציע תבשיל קטניות נוסף שגם בו עדשים כשכבר יש עדשים בארוחה משם אחר (מתכון או פריט)
  const LENTIL_FKS = new Set(["redLentils","greenLentils","brownLentils","blackLentils"]);
  const recipeHasLentil = fk => { const r=recipeByIdNSF[fk]; return r ? (r.ings||[]).some(ing=>LENTIL_FKS.has(ing.fk)) : false; };
  const recipeIsLegumeDominant = fk => {
    const r=recipeByIdNSF[fk]; if(!r) return false;
    const ings=r.ings||[]; const totalG=ings.reduce((s,ing)=>s+(ing.g||0),0); if(!totalG) return false;
    const legumeG=ings.filter(ing=>(FDB[ing.fk]||{}).cat==="קטנית").reduce((s,ing)=>s+(ing.g||0),0);
    return legumeG/totalG>0.35;
  };
  // תיקון (לבקשת המשתמש: "אם יש סלט קינואה, לא להציע גם טורטיית קינואה") — בדוק אם שתי מתכונים
  // חולקות את אותו מרכיב-דומיננטי (דגן/קטנית ראשיים) והימנע מהם באותה ארוחה
  const getDominantIngredients = fk => {
    const r=recipeByIdNSF[fk]; if(!r) return new Set();
    const ings=r.ings||[]; const totalG=ings.reduce((s,ing)=>s+(ing.g||0),0);
    if(!totalG) return new Set();
    const grainG=ings.filter(ing=>(FDB[ing.fk]||{}).cat==="דגן").reduce((s,ing)=>s+(ing.g||0),0);
    const legumeG=ings.filter(ing=>(FDB[ing.fk]||{}).cat==="קטנית").reduce((s,ing)=>s+(ing.g||0),0);
    const dominants = new Set();
    if(grainG/totalG>0.25) ings.filter(ing=>(FDB[ing.fk]||{}).cat==="דגן").forEach(ing=>dominants.add(ing.fk));
    if(legumeG/totalG>0.25) ings.filter(ing=>(FDB[ing.fk]||{}).cat==="קטנית").forEach(ing=>dominants.add(ing.fk));
    return dominants;
  };
  const sharesDominantIngredient = (fk1, fk2) => {
    const doms1 = getDominantIngredients(fk1);
    const doms2 = getDominantIngredients(fk2);
    return [...doms1].some(d=>doms2.has(d));
  };
  // תיקון (לבקשת המשתמש: "איך מתקנים... בעיה 1" — הרחבת קטגוריות, בהמשך לניתוח שנמצא ש-16 מתכונים לא
  // תואמים אף אחת מ-8 הקטגוריות שהתבניות מחפשות): הרחבה ממוקדת של שלוש קבוצות-המועמדים, לפי מה שהתגלה
  // בבדיקה — דייסות/קערות הן דגן-במהותן, חביטות (type="חביטה") הן לרוב קטניה-במהותן (קמח חומוס/עדשים),
  // וסלטי-פירות הן סלט-במהותן (רק הכילו מרכיב-פרי שגרם לסיווג השגוי)
  const grainStewPool = recipePool.filter(fk=>{
    const cat = catOfRecipeId(fk);
    if (cat==="תבשילי דגנים") return true;
    if (cat==="דייסות" || cat==="קערות") { const fd=TEMP_FDB[fk]; return fd?._foodGroup==="דגן"; }
    return false;
  });
  const legumeStewPool = recipePool.filter(fk=>{
    const cat = catOfRecipeId(fk);
    if (cat==="תבשילי קטניות") return true;
    // תיקון (לבקשת המשתמש: "לא רואה הצעות למרקים ולקערות דגנים - ודא שהם נגישים למנגנוני התכנון") — grainStewPool
    // כבר כלל קערות עם foodGroup="דגן", אבל legumeStewPool מעולם לא קיבל את אותה הרחבה עבור קערות מבוססות-קטנית
    // (כמו "קערת חומוס וירקות ים תיכונית בטחינה") — אי-עקביות שהצטמצמה את מאגר-הקטנית ללא סיבה
    if (cat==="קערות") { const fd=TEMP_FDB[fk]; return fd?._foodGroup==="קטנית"; }
    // תיקון (לבקשת המשתמש: "אל תוותר, רוצה שהם ייכללו" — שקשוקה טבעונית, type="תבשיל מחבת", לא נתפסה
    // על ידי ההתאמה הקודמת ל"חביטה" בלבד)
    // תיקון-באג נוסף (לבקשת המשתמש: "לא מציע כלום מקטגוריית מעשה מחבת/חביתות"): הבדיקה כתבה "חביטה" (עם ט)
    // בעוד שכל מתכוני החביתה בפועל מוגדרים type="חביתה" (עם ת) — טעות-כתיב שגרמה לכל ארבעת מתכוני החביתה
    // (חביתת קמח חומוס, חביתת עדשים, חביתת קישואים וקמח חומוס, ועוד) לא להיתפס כאן אף פעם, ולהיפול במקום זה
    // ל-otherRecipePool החלש בהרבה (רק כשלארוחה עדיין אין סלט)
    if (cat==="אחר") { const r=recipeByIdNSF[fk]; const t=r?.type||""; return t.includes("חביתה") || t.includes("תבשיל מחבת"); }
    return false;
  });
  const vegSaladPoolCat = recipePool.filter(fk=>{
    const cat = catOfRecipeId(fk);
    return cat==="סלטי ירקות" || cat==="סלטי פירות";
  });
  // תת-קבוצה של vegSaladPoolCat שבאמת מבוססת ירק (לא קטנית שהוצגה כ"סלט") — לשימוש כשצריך להבטיח ירק אמיתי
  const realVegSaladPoolCat = vegSaladPoolCat.filter(fk=>!recipeIsLegumeDominant(fk));
  const mealSaladPoolCat = recipePool.filter(fk=>catOfRecipeId(fk)==="ארוחות סלט");
  const bakedGoodPoolCat = recipePool.filter(fk=>catOfRecipeId(fk)==="מאפים");
  const spreadPoolCat = recipePool.filter(fk=>catOfRecipeId(fk)==="ממרחים");
  const piePoolCat = recipePool.filter(fk=>catOfRecipeId(fk)==="פשטידות");
  const soupPoolCat = recipePool.filter(fk=>catOfRecipeId(fk)==="מרקים");

  // תיקון-באג (לבקשת המשתמש, אחרי דיווח על ארוחות צהריים/ערב בלי שום ירק אמיתי): רשימת הגיבוי הקודמת של ירק גולמי
  // הייתה קטנה מדי (5 פריטים בלבד) *וגם* נכנסה ל-usedFks הרגיל (שאוכף "פעם אחת ליום"), כך שברגע שארוחה מוקדמת
  // "תפסה" עגבנייה/מלפפון וכו', לארוחות מאוחרות יותר לא נשאר אף מועמד ולא נוסף שום ירק. ירק גולמי בסיסי (עגבנייה,
  // מלפפון וכו') הגיוני לגמרי שיחזור על עצמו כמה פעמים באותו יום (גם בצהריים וגם בערב) — אז addFallbackVeg בכוונה
  // לא מסמן usedFks, כדי שאותו ירק יישאר זמין לארוחה הבאה. הרשימה עצמה גם הורחבה משמעותית.
  const VEG_FALLBACK_POOL = ["cucumber","tomato","carrot","redPepper","yellowPepper","greenPepper","cabbageRed","radish","zucchini","beet"];
  const addFallbackVeg = (mk) => {
    for (const fk of shuffleArr(VEG_FALLBACK_POOL)) {
      if ((plan[mk]||[]).some(it=>it.fk===fk)) continue; // כבר קיים בדיוק באותה ארוחה
      const fd = FDB[fk]; if (!fd) continue;
      let g = servingG(fk);
      // תיקון (לבקשת המשתמש: "השתמש במנות שלמות ולא ב 3/4") — החל עיגול יחידות-שלמות גם בירקות-גיבוי
      const wholeStep = wholeUnitStepG(fk);
      if (wholeStep!=null) g = Math.max(wholeStep, Math.round(g/wholeStep)*wholeStep);
      let nut = ingNut(fk,g);
      const used = sumNuts(plan[mk].map(({fk,g,soaked})=>ingNut(fk,g,soaked))).kcal;
      const headroom = Math.min(tgt*SHARE[mk]*1.3-used, hardCapKcal-dayKcalUsed);
      if (headroom < 5) continue;
      // תיקון (לבקשת המשתמש: "אל תציע חלקי יחידות ירק - רק שלמות") — הקנה-מידה-לפי-מרחב-פנוי הקודם הפיק
      // כמויות-שבריות (כמו 0.55 יחידת גזר). אם היחידה השלמה לא נכנסת, פשוט מדלגים על המועמד הזה במקום לצמצם
      if (nut.kcal > headroom) continue;
      if (nut.sodium > (sodiumCap-sodiumUsed)+0.5) continue;
      if (potassiumCap!=null && nut.potassium > (potassiumCap-potassiumUsed)+0.5) continue;
      if (phosphorusCap!=null && nut.phosphorus > (phosphorusCap-phosphorusUsed)+0.5) continue;
      plan[mk].push({fk,g});
      dayKcalUsed += nut.kcal; sodiumUsed += nut.sodium||0; potassiumUsed += nut.potassium||0; phosphorusUsed += nut.phosphorus||0;
      return true;
    }
    return false;
  };

  // צהריים: תבשיל דגן + תבשיל קטניות + סלט ירקות אמיתי (לבקשת המשתמש: הסלט נבחר קודם ומסונן ל"ירק אמיתי" —
  // כלומר לא סלט-עדשים שיוצג כ"ירק" בטעות — ואם כבר יש עדשים בסלט הזה, תבשיל הקטניות שנבחר אחריו מדלג על
  // מועמדים שגם בהם עדשים, כדי לא לקבל שתי מנות עדשים שונות באותה ארוחה)
  // תיקון-שורש (לבקשת המשתמש: "גיוון מתכונים נדרש ומשמעותי מאוד" — בענף experiment-recipe-variety) — אותר
  // שכל מקום כאן לקח רק את המועמד הראשון מהרשימה-המעורבבת ([0]), וניסה tryAdd עליו פעם אחת בלבד. אם המועמד
  // הזה (שהיה יכול להיות מתכון גדול) לא נכנס בתקציב-הצר של הארוחה, השבצה כולה ויתרה בלי לנסות את המועמד הבא
  // ברשימה — מה שהסביר למה תמיד אותם מתכונים-קטנים-במיוחד "ניצחו" (הם היחידים שתמיד נכנסים), ו-108 מתוך 145
  // מתכונים כמעט אף פעם לא נבחרו. הוחלף בלולאת for...break שמנסה את כל הרשימה המעורבבת, לא רק את הראשון
  {
    for (const vCand of usageWeightedOrderCapped(realVegSaladPoolCat.filter(fk=>!usedFks.has(fk)), recipeUsage, 2)) { if (tryAdd("lunch", vCand, 0.45)) break; }
    for (const gCand of usageWeightedOrder(grainStewPool.filter(fk=>!usedFks.has(fk)), recipeUsage)) { if (tryAdd("lunch", gCand, 0.85)) break; }
    const alreadyHasLentil = (plan.lunch||[]).some(it=>recipeHasLentil(it.fk));
    const legumeCands = legumeStewPool.filter(fk=>!usedFks.has(fk) && !(alreadyHasLentil && recipeHasLentil(fk)));
    for (const lCand of usageWeightedOrderCapped(legumeCands, recipeUsage, 2)) { if (tryAdd("lunch", lCand, 1.0)) break; }
    // רשת ביטחון: אם משום מה עדיין אין שום ירק אמיתי בארוחה (למשל כי realVegSaladPoolCat היה ריק/כולו כבר בשימוש)
    const hasRealVeg = (plan.lunch||[]).some(it=>{
      const fd=FDB[it.fk]||TEMP_FDB[it.fk]; if(!fd) return false;
      if (fd.cat==="ירק") return true;
      return fd._isRecipe && catOfRecipeId(it.fk)==="סלטי ירקות" && !recipeIsLegumeDominant(it.fk);
    });
    if (!hasRealVeg) addFallbackVeg("lunch");
  }

  // בוקר: ארוחת סלט + משקה סויה/יוגורט סויה; אם קטן — גם מאפה וגם ממרח
  // תיקון-שורש נוסף (אותו ענף): בוקר קיבל *רק* סוג-מתכון אחד (מארוחות-סלט) לכל אורך התהליך — לעולם לא
  // תבשיל-דגן/קטניות/מרק/פשטידה, ללא קשר לתקציב. זו הסיבה שכל תבשיל/מרק/פשטידה במאגר (108 מתוך 145!) לא
  // יכול היה להופיע בבוקר בשום מצב. נוסף כאן מסלול-חלופי (בהסתברות 45%, לגיוון בלי לבטל את מסלול-הסלט
  // כברירת-מחדל): תבשיל-דגן+קטניות קליל, במקום ארוחת-סלט, כשההסתברות "נופלת" על זה
  {
    const breakfastStewRoute = Math.random() < 0.45;
    let breakfastMainPlaced = false;
    if (breakfastStewRoute) {
      for (const gCand of usageWeightedOrder(grainStewPool.filter(fk=>!usedFks.has(fk)), recipeUsage)) { if (tryAdd("breakfast", gCand, 0.85)) { breakfastMainPlaced=true; break; } }
      const alreadyHasLentilB = (plan.breakfast||[]).some(it=>recipeHasLentil(it.fk));
      const legumeCandsB = legumeStewPool.filter(fk=>!usedFks.has(fk) && !(alreadyHasLentilB && recipeHasLentil(fk)));
      for (const lCand of usageWeightedOrderCapped(legumeCandsB, recipeUsage, 2)) { if (tryAdd("breakfast", lCand, 1.0)) { breakfastMainPlaced=true; break; } }
      if (!breakfastMainPlaced) {
        for (const sCand of usageWeightedOrder(soupPoolCat.filter(fk=>!usedFks.has(fk)), recipeUsage)) { if (tryAdd("breakfast", sCand, 0.6)) { breakfastMainPlaced=true; break; } }
      }
    }
    if (!breakfastMainPlaced) {
      let mCand = null;
      for (const cand of usageWeightedOrderCapped(mealSaladPoolCat.filter(fk=>!usedFks.has(fk)), recipeUsage, 2)) { if (tryAdd("breakfast", cand, 1.3)) { mCand=cand; break; } }
      if (mCand) {
        const soyCand = ["soymilkOrgPlain","soyYogurtPlain","soyYogurtOrgPlain"].find(fk=>!usedFks.has(fk));
        if (soyCand) tryAdd("breakfast", soyCand);
        const mRecipeName = recipeByIdNSF[mCand]?.name||"";
        if (mRecipeName.includes("קטן")) {
          // תיקון (לבקשת המשתמש: "אם יש סלט קינואה, לא להציע גם טורטיית קינואה") — בחר מאפה שלא חולק
          // את אותו מרכיב-דומיננטי עם הסלט שכבר בארוחה
          for (const bCand of usageWeightedOrder(bakedGoodPoolCat.filter(fk=>!usedFks.has(fk) && !sharesDominantIngredient(fk, mCand)), recipeUsage)) { if (tryAdd("breakfast", bCand)) break; }
          for (const spCand of usageWeightedOrder(spreadPoolCat.filter(fk=>!usedFks.has(fk)), recipeUsage)) { if (tryAdd("breakfast", spCand)) break; }
        }
      }
    } else {
      const soyCand = ["soymilkOrgPlain","soyYogurtPlain","soyYogurtOrgPlain"].find(fk=>!usedFks.has(fk));
      if (soyCand) tryAdd("breakfast", soyCand);
    }
    // תיקון (לבקשת המשתמש, אחרי הרצת סימולציה על 30 שבועות: "רק 17% מהקטניות הגיעו כתבשיל-מתכון, לעומת 83%
    // כקטנית גולמית-ממלאת") — הניסיון היחיד לתבשיל-קטניות בבוקר היה תלוי לגמרי ב-breakfastStewRoute (45% סיכוי),
    // ורק כשהוא לא הצליח למלא את הבוקר עם משהו אחר קודם. נוסף כאן ניסיון בלתי-תלוי נוסף: אם עדיין אין שום
    // תבשיל-קטניות בבוקר בכלל (ללא קשר למסלול/למה שכבר הצליח), מנסים להוסיף אחד כפריט משלים בתקציב קטן
    if (!(plan.breakfast||[]).some(it=>recipeHasLentil(it.fk)||catOfRecipeId(it.fk)==="תבשילי קטניות")) {
      for (const lCand of usageWeightedOrderCapped(legumeStewPool.filter(fk=>!usedFks.has(fk)), recipeUsage, 2)) { if (tryAdd("breakfast", lCand, 0.85)) break; }
    }
  }

  // ערב: מסלול א' (תבשיל דגן + תבשיל קטניות, מנות קטנות-קלוריה) או מסלול ב' (קערה/פשטידה + מרק) — נבחר לפי
  // dayIdx (יציב לאותו יום), נופל להסתברות 50/50 ללא dayIdx. שני המסלולים עשויים לקבל גם מאפה/ממרח כ"שאר הרכיבים"
  {
    const dinnerRouteA = dayIdx!=null ? (dayIdx%2===0) : (Math.random()<0.5);
    if (dinnerRouteA) {
      for (const gCand of usageWeightedOrder(grainStewPool.filter(fk=>!usedFks.has(fk)), recipeUsage)) { if (tryAdd("dinner", gCand, 0.8)) break; }
      const alreadyHasLentilD = (plan.dinner||[]).some(it=>recipeHasLentil(it.fk));
      const legumeCandsD = legumeStewPool.filter(fk=>!usedFks.has(fk) && !(alreadyHasLentilD && recipeHasLentil(fk)));
      for (const lCand of usageWeightedOrderCapped(legumeCandsD, recipeUsage, 2)) { if (tryAdd("dinner", lCand, 1.0)) break; }
    } else {
      for (const kCand of usageWeightedOrder(piePoolCat.filter(fk=>!usedFks.has(fk)), recipeUsage)) { if (tryAdd("dinner", kCand, 0.8)) break; }
      for (const sCand of usageWeightedOrder(soupPoolCat.filter(fk=>!usedFks.has(fk)), recipeUsage)) { if (tryAdd("dinner", sCand, 0.7)) break; }
      // תיקון (אותו תיקון בדיוק כמו בבוקר, למעלה): מסלול ב' של הערב מעולם לא ניסה תבשיל-קטניות בכלל — רק
      // פשטידה/מרק. מוסיפים ניסיון-נוסף בתקציב קטן אם עדיין אין תבשיל-קטניות בערב
      for (const lCand of usageWeightedOrderCapped(legumeStewPool.filter(fk=>!usedFks.has(fk)), recipeUsage, 2)) { if (tryAdd("dinner", lCand, 0.85)) break; }
    }
    if (Math.random()<0.4) {
      const bCand = usageWeightedOrder(bakedGoodPoolCat.filter(fk=>!usedFks.has(fk)), recipeUsage)[0];
      if (bCand) tryAdd("dinner", bCand);
      const spCand = usageWeightedOrder(spreadPoolCat.filter(fk=>!usedFks.has(fk)), recipeUsage)[0];
      if (spCand) tryAdd("dinner", spCand);
    }
  }
  // גיל 65+ (לבקשת המשתמש): ארוחות החלבון — צהריים וערב. אם התבשילים שנבחרו לא מביאים את הארוחה לסף הלאוצין
  // (2.5 גר'), משבצים כבר כאן (לפני שלבי המילוי) מנה מרוכזת: תורמוס/טמפה/אדממה, או יוגורט סויה כגיבוי
  if ((dri?._age||0)>=65) {
    const leuMeal=mk=>sumNuts((plan[mk]||[]).map(({fk,g,soaked})=>ingNut(fk,g,soaked))).leucine||0;
    const DENSE=[...shuffleArr(["lupinBeansCooked","tempeh","edamame"]),"soyYogurtPlain"];
    for (const mk of ["lunch","dinner"]) {
      if (leuMeal(mk)>=2.5) continue;
      for (const fk of DENSE) { if (!FDB[fk]||usedFks.has(fk)) continue;
        if (isSoyFamilyItem(fk)&&soyFamilyAlreadyInMeal(mk)) continue;
        if (tryAdd(mk, fk, 1.6)) break; }
    }
  }

  const prioritySaladPool = recipePool.filter(fk=>isPrioritySaladRecipe(recipeByIdNSF[fk]));
  const regularSaladPool = recipePool.filter(fk=>isSaladRecipe(recipeByIdNSF[fk]) && !prioritySaladPool.includes(fk));
  const otherRecipePool = recipePool.filter(fk=>!prioritySaladPool.includes(fk) && !regularSaladPool.includes(fk));
  // כלל חדש: "סלט ארוחה גדול" (עם וואקמה) — בדיוק פעם אחת בשבוע (לא כל יום, גם אם המתכון קיים אצל המשתמש).
  // dayIdx מגיע מבחוץ (יום השבוע הנבחר כרגע באפליקציה); ללא dayIdx נופל להסתברות 1/7
  const WAKAME_SALAD_NAME = "סלט ארוחה גדול";
  const wakameSaladRecipe = recipes.find(r=>(r.name||"").includes(WAKAME_SALAD_NAME));
  // כלל מעודכן שוב לבקשת המשתמש: פעם אחת בשבוע בלבד (לא פעמיים) — יום קבוע: ראשון (0)
  const isWakameSaladDay = dayIdx!=null ? (dayIdx===0) : (Math.random() < 1/7);
  let wakameSaladPlaced = false; // מדגם אם הסלט עם הוואקמה באמת נכנס לתפריט היום (לא רק "יום מיועד") — משמש בהמשך לצמצום מלח, וגם לכלל 3 (למטה)
  const mealHasSalad = {};
  NON_SNACK_MEALS.forEach(mk=>{ mealHasSalad[mk]=plan[mk].some(it=>isSaladRecipe(recipeByIdNSF[it.fk])); });
  // לבקשת המשתמש: מתכון "קערת יוגורט סויה, שיבולת שועל וזרעי פשתן" (מתכון אישי שמור, לא רכיבים גולמיים נפרדים
  // כמו בגרסה הקודמת) בארוחת הערב, בימים א', ג', ה' בלבד (dayIdx 0,2,4). נופל חזרה לשלושת הרכיבים הגולמיים רק
  // אם המתכון נמחק/שונה שם בעתיד ולא נמצא, כדי שהיום לא יישאר בלי דבר בערב
  const yogurtOatsBowlRecipe = recipes.find(r=>(r.name||"").includes("קערת יוגורט"));
  if (dayIdx!=null && (dayIdx===0||dayIdx===2||dayIdx===4)) {
    if (yogurtOatsBowlRecipe && !usedFks.has(yogurtOatsBowlRecipe.id)) {
      tryAdd("dinner", yogurtOatsBowlRecipe.id);
    } else if (!yogurtOatsBowlRecipe) {
      ["soyYogurtPlain","flaxseed"].forEach(fk=>{ if(!usedFks.has(fk)) tryAdd("dinner",fk); });
    }
  }
  // שלב א: מנסים למקם את "סלט ארוחה גדול" (עם/בלי וואקמה) פעם אחת ליום בלבד — לא בכל ארוחה בנפרד — בארוחה עם
  // הכי הרבה מקום תקציבי פנוי. חייבים לדעת את התוצאה של זה *לפני* שממשיכים לשלב ב', כדי שכלל 3 (איסור על סלט
  // בינוני/קטן באותו יום) יעבוד נכון בלי תלות בסדר הארוחות.
  // budgetMult=1.3 מפורש כאן (לא ברירת המחדל 0.9 של מתכון): "סלט ארוחה גדול" הוא מנה ענקית בכוונה (~1000 קק"ל,
  // מיועד להיות ארוחה שלמה בפני עצמה — זו המשמעות של "ארוחה" בשם) וגם המקור העיקרי ליוד (וואקמה) בתפריט השבועי.
  // תיקון לבאג: ברירת המחדל הנמוכה יותר (0.9, שנוספה כדי שמתכונים קטנים ישאירו מקום למגוון) מנעה ממנו להיכנס
  // לאף ארוחה בכלל (אף תקציב ארוחה, גם עם 1.4x בבחירת mkTarget למעלה, לא הכיל ~1000 קק"ל תחת 0.9x) — מה שהוביל
  // לכך שהמלח המיודד לא דולג (הכלל תלוי ב-wakameSaladPlaced) *וגם* היעד השבועי ליוד לא הושג, כי שני המנגנונים
  // (וואקמה + מלח) שנועדו יחד להבטיח יוד לא הופעלו בפועל
  if (isWakameSaladDay && wakameSaladRecipe && !usedFks.has(wakameSaladRecipe.id)) {
    const mkTarget = NON_SNACK_MEALS.reduce((best,mk)=>{
      const used = sumNuts(plan[mk].map(({fk,g,soaked})=>ingNut(fk,g,soaked))).kcal;
      const headroom = tgt*SHARE[mk]*1.4 - used;
      return headroom > (best.headroom ?? -Infinity) ? {mk,headroom} : best;
    }, {}).mk;
    if (tryAdd(mkTarget, wakameSaladRecipe.id, 1.3)) { mealHasSalad[mkTarget]=true; wakameSaladPlaced=true; }
  }
  // שלב ב: לכל ארוחה שעדיין אין לה סלט — מנסים סلט קטן/בינוני-מועדף, ואז כל סلט אחר, ואז כל מתכון אחר. כלל 3
  // (חדש): אם היום כבר "תפוס" ע"י סلט ארוחה גדול (wakameSaladPlaced) — מדלגים לגמרי על שכבת הסלט הקטן/בינוני
  // המועדף בכל הארוחות, לא רק באותה ארוחה שקיבלה את הגדול
  // כלל חדש (לבקשת המשתמש): "סלט ארוחה" — כל אחד מארבעת הסוגים (קטן/בינוני/גדול/גדול עם וואקמה) — מותר פעם
  // אחת בלבד ליום, בכל ארוחה שהיא. לא רק "לא לחזור על אותו סוג", אלא לא לערבב שני סוגים שונים (למשל קטן בבוקר
  // וגם בינוני בצהריים) — מזוהה לפי המילים "סלט ארוחה" בשם המתכון עצמו, לא כל מתכון שמכיל "סלט" (כמו "סלט בסיס"
  // או "סלט כרובים", שנשארים מותרים כרגיל, כולל כמה פעמים ביום אם צריך)
  const isMealSaladRecipe = r => (r?.name||"").includes("סלט ארוחה") || r?.foodGroup==="סלט_ארוחה";
  let mealSaladPlacedToday = wakameSaladPlaced || NON_SNACK_MEALS.some(mk=>plan[mk].some(it=>isMealSaladRecipe(recipeByIdNSF[it.fk]))); // הוואקמה עצמו הוא "סלט ארוחה גדול", לכן כבר סופר כאן
  shuffleArr(NON_SNACK_MEALS).forEach(mk=>{
    if (mealHasSalad[mk]) return;
    let placed=false;
    // לבקשת המשתמש: ערב לא מקבל מתכוני סלט כלל (המנה העיקרית שלו כבר טופלה למעלה) — רק בוקר וצהריים מקבלים כאן ניסיון סלט.
    if (mk!=="dinner" && !wakameSaladPlaced) {
      const noDupMealSalad = fk => !(mealSaladPlacedToday && isMealSaladRecipe(recipeByIdNSF[fk]));
      // תיקון (לבקשת המשתמש: "יש עוד סלטים עם משפחת המצליבים, האם הם מוצעים?" — אותר שסלט אחד ספציפי, זול-קלורית
      // באופן קיצוני (39 קק"ל, הכי-נמוך מכל המועמדים), נבחר ב-93% מהימים למרות usageWeightedOrder — כי גם
      // כשהוא נדחק לסוף הרשימה (בזכות שימוש-קודם), כל שאר המועמדים היקרים יותר נכשלים ב-tryAdd בגלל תקציב
      // מצומצם, והלולאה ממשיכה עד שמגיעה אליו ומצליחה שם. תקרה קשיחה של 2 שימושים בשבוע לכל מתכון-סלט בודד —
      // בלי רשת-ביטחון שמבטלת את התקרה (ניסיון קודם לכך פשוט חזר לאותה תוצאה) — אם אין מועמד תקין, נופלים
      // ל-otherRecipePool למטה במקום לוותר על התקרה; לא כל ארוחה חייבת סלט דווקא
      for (const fk of usageWeightedOrderCapped(prioritySaladPool.filter(fk=>!usedFks.has(fk)&&!(isSoyFamilyItem(fk)&&soyFamilyAlreadyInMeal(mk))&&noDupMealSalad(fk)), recipeUsage, 2)) { if (tryAdd(mk,fk,1.3)) { mealHasSalad[mk]=true; placed=true; if(isMealSaladRecipe(recipeByIdNSF[fk])) mealSaladPlacedToday=true; break; } }
      if (!placed) for (const fk of usageWeightedOrderCapped(regularSaladPool.filter(fk=>!usedFks.has(fk)&&!(isSoyFamilyItem(fk)&&soyFamilyAlreadyInMeal(mk))&&noDupMealSalad(fk)), recipeUsage, 2)) { if (tryAdd(mk,fk,1.3)) { mealHasSalad[mk]=true; placed=true; if(isMealSaladRecipe(recipeByIdNSF[fk])) mealSaladPlacedToday=true; break; } }
    }
    if (!placed) for (const fk of usageWeightedOrder(otherRecipePool.filter(fk=>!usedFks.has(fk)&&!(isSoyFamilyItem(fk)&&soyFamilyAlreadyInMeal(mk))), recipeUsage)) { if (tryAdd(mk,fk)) { placed=true; break; } }
    // לבקשת המשתמש: כששקשוקה טבעונית (מתכון אישי) נכנסה לארוחה כאן, מנסים לצרף אליה מיד את "לחם עדשים"
    if (placed && shakshukaRecipe && plan[mk].some(it=>it.fk===shakshukaRecipe.id) && lentilBreadRecipe && !usedFks.has(lentilBreadRecipe.id)) {
      tryAdd(mk, lentilBreadRecipe.id);
    }
  });

  // כלל 7 (מתוקן שוב לבקשת המשתמש): "קציצות טופו ואצות" — שתי מנות ממנו באותה ארוחה, אבל רק **פעם אחת בשבוע**
  // (לא פעמיים — "הסתפק בשתי מנות בארוחה אחת בלבד במשך השבוע"). יום קבוע: שישי (5, לא שלישי כקודם — לבקשת
  // המשתמש). ללא dayIdx נופל להסתברות 1/7. ארוחה קבועה: ערב בלבד (לא לפי מקום פנוי כמו קודם — זה בדיוק מה
  // שגרם לו להופיע בבוקר באחת הפעמים; "ערב" הוא חלק מהבקשה באותה מידה כמו היום עצמו, לא רק העדפה)
  {
    const TOFU_SEAWEED_NAME = "קציצות טופו ואצות";
    const dishRecipe = recipes.find(r=>(r.name||"").includes(TOFU_SEAWEED_NAME));
    const isTofuSeaweedDay = dayIdx!=null ? (dayIdx===5) : (Math.random() < 1/7);
    if (dishRecipe && !usedFks.has(dishRecipe.id) && isTofuSeaweedDay) {
      const baseServingG = servingG(dishRecipe.id);
      const doubleG = baseServingG*2;
      const nut = ingNut(dishRecipe.id, doubleG);
      if (nut.kcal>0 && nut.kcal <= (hardCapKcal-dayKcalUsed) && nut.sodium <= (sodiumCap-sodiumUsed)+0.5) {
        const mkTarget = "dinner";
        plan[mkTarget].push({fk:dishRecipe.id, g:doubleG});
        usedFks.add(dishRecipe.id);
        dayKcalUsed += nut.kcal; sodiumUsed += nut.sodium||0; potassiumUsed += nut.potassium||0; phosphorusUsed += nut.phosphorus||0;
      }
    }
  }

  // כלל 5: בכל ארוחה (משלוש הראשיות) שלא קיבלה סלט — חובה לנסות להוסיף לפחות פריט ירק אחד, לא רק כאפשרות
  // אקראית בשלב המילוי הכללי
  NON_SNACK_MEALS.forEach(mk=>{
    if (mealHasSalad[mk]) return;
    for (const fk of shuffleArr(vegPool.filter(fk=>!usedFks.has(fk)))) { if (tryAdd(mk,fk)) break; }
  });

  // כלל 8: משקה סויה (אורגני, ללא תוספות) — לפחות פעמיים ביום (לא בארוחת ביניים, כלל 9), אך אף פעם לא פעמיים
  // *באותה ארוחה* (כלל 6 חדש — לא לרכז שני כוסות משקה סויה יחד). לא כפוף למגבלת "פעם אחת ליום" הרגילה של
  // usedFks, כי צריך בכוונה יותר מהופעה אחת (בארוחות שונות). SOY_FAMILY_NSF/isSoyFamilyItem/soyFamilyAlreadyInMeal
  // כבר הוגדרו למעלה, מיד אחרי recipeByIdNSF — נחוצים כבר בשלב א'/ב' (וואקמה/סלט), לפני כאן
  function addRepeatable(fk, times){
    const fd = FDB[fk]||TEMP_FDB[fk]; if(!fd) return;
    let placed=0, attempt=0;
    const mealOrder = shuffleArr([...NON_SNACK_MEALS]);
    while (placed<times && attempt<times+5) {
      const mk = mealOrder[attempt % mealOrder.length];
      attempt++;
      if (plan[mk].some(it=>it.fk===fk)) continue; // כלל 6: לא פעמיים באותה ארוחה
      if (isSoyFamilyItem(fk) && soyFamilyAlreadyInMeal(mk)) continue; // לא מוצר סויה נוסף אם כבר יש אחר בארוחה הזו (כולל בתוך מתכון)
      let g = servingG(fk);
      const used = sumNuts(plan[mk].map(({fk,g,soaked})=>ingNut(fk,g,soaked))).kcal;
      const headroom = Math.min(tgt*SHARE[mk]*1.3-used, hardCapKcal-dayKcalUsed);
      let nut = ingNut(fk,g);
      if (nut.kcal > headroom) {
        if (headroom<=5) continue;
        const scale = headroom/nut.kcal; if (scale<0.3) continue;
        g = Math.round(g*scale*10)/10; nut = ingNut(fk,g);
      }
      if (nut.sodium > (sodiumCap-sodiumUsed)+0.5) continue;
      plan[mk].push({fk,g});
      dayKcalUsed += nut.kcal; sodiumUsed += nut.sodium||0; potassiumUsed += nut.potassium||0; phosphorusUsed += nut.phosphorus||0;
      placed++;
    }
  }
  addRepeatable("soymilkOrgPlain", 2);
  // תיקון (לבקשת המשתמש: "אל תוותר, רוצה שהם ייכללו" — כולל מתכוני-משקה, שהיו חסומים-מבנית לגמרי כי אף
  // משבצת-ארוחה לא מחפשת קטגוריית "משקאות") — נוספת כאן הזדמנות-אקראית (35%) להוסיף משקה-מתכון אחד ליום,
  // כתוספת ליד ארוחה קיימת, לא כתחליף למנה-ראשית
  if (Math.random() < 0.35) {
    const drinkPoolCat = recipePool.filter(fk=>catOfRecipeId(fk)==="משקאות" && !usedFks.has(fk));
    for (const fk of usageWeightedOrder(drinkPoolCat, recipeUsage)) { if (tryAdd(NON_SNACK_MEALS[Math.floor(Math.random()*NON_SNACK_MEALS.length)], fk)) break; }
  }

  // כלל 1 (חדש): לא להציע שני מתכוני "סלט" (כולל "סלט גדול"+"סלט קטן" וכו') באותה ארוחה. כלל 5 (חדש): לא
  // לרכז יותר משתי יחידות פרי באותה ארוחה — בכל הארוחות (לא רק ביניים)
  const fruitCountInMeal = mk => plan[mk].filter(it=>(FDB[it.fk]||TEMP_FDB[it.fk])?.cat==="פרי").length;
  // לבקשת המשתמש: שקשוקה טבעונית (מתכון אישי) עשויה מטופו, ויוגורט הסויה הביתי הוא גם הוא ממקור סויה — לא
  // מוצעים באותה ארוחה (אבל שניהם עדיין יכולים להופיע ביום, כל אחד בארוחה נפרדת)
  const isBlockedCandidate = (mk, fk) => {
    const fd = FDB[fk]||TEMP_FDB[fk];
    if (!fd) return true;
    if (fd.cat==="פרי" && fruitCountInMeal(mk)>=2) return true;
    if (fd._isRecipe && isSaladRecipe(recipeByIdNSF[fk]) && mealHasSalad[mk]) return true;
    if (fd._isRecipe && mealSaladPlacedToday && isMealSaladRecipe(recipeByIdNSF[fk])) return true;
    // מורחב מ"שקשוקה מול יוגורט" בלבד לכל משפחת הסויה (משקה סויה, יוגורט, טופו, טמפה וכו') — לא שני מוצרי סויה
    // שונים באותה ארוחה, לא רק זוג ספציפי אחד
    if (isSoyFamilyItem(fk) && soyFamilyAlreadyInMeal(mk)) return true;
    return false;
  };

  // שלב מילוי כללי לשלוש הארוחות הראשיות: כלל (פשתן/צ'יה) — מפוזרים בכוונה לשתי ארוחות *שונות* (לא שתיהן
  // לאותה ארוחה), כדי לא לגרום לזרעים "להצטבר" כולם בארוחה אחת. ואז ערבוב אקראי של אגוזים/זרעים/פרי
  // (+ ירק אם עדיין אין סלט) ולפעמים עוד מתכון, עד לתקציב הארוחה — עם הגבלה לכל היותר זרע אחד חדש לארוחה
  // בשלב האקראי (מעבר לפשתן/צ'יה שכבר שובצו), כדי להמשיך לפזר זרעים בין הארוחות ולא לגרום לריכוז בארוחה אחת
  {
    // לבקשת המשתמש: לא רק לא לחזור על אותו זרע — גם לא לערבב שני סוגי זרעים שונים (פשתן+צ'יה) באותה ארוחה,
    // כולל כשאחד מהם "מוסתר" בתוך מתכון שכבר שם (mealHasAnySeed בודק את שניהם)
    const seedMealOrder = shuffleArr([...NON_SNACK_MEALS]);
    if (!usedFks.has("flaxseed")) {
      const mkFlax = seedMealOrder.find(mk=>!mealHasAnySeed(mk));
      if (mkFlax) tryAdd(mkFlax, "flaxseed");
    }
    if (!usedFks.has("chiaseeds")) {
      const mkChia = seedMealOrder.find(mk=>!mealHasAnySeed(mk));
      if (mkChia) tryAdd(mkChia, "chiaseeds");
    }
  }
  NON_SNACK_MEALS.forEach(mk=>{
    let guard=0;
    while (guard<10 && dayKcalUsed < hardCapKcal-10) {
      guard++;
      const extraPool = mealHasSalad[mk] ? [] : vegPool;
      const mealAlreadyHasSeed = mealHasAnySeed(mk);
      let combined = usageWeightedOrder([...rawPoolNoStaple, ...extraPool, ...recipePool.filter(fk=>!usedFks.has(fk))], recipeUsage);
      if (mealAlreadyHasSeed) combined = combined.filter(fk=>(FDB[fk]||TEMP_FDB[fk])?.cat!=="זרעים");
      let cand = combined.find(fk=>!usedFks.has(fk) && !isBlockedCandidate(mk,fk));
      if (!cand) { // אין מועמד לא-זרע — מותר בכל זאת זרע נוסף עדיף על להשאיר תקציב לא מנוצל (עדיין כפוף לכללי 1/5)
        const fallback = usageWeightedOrder([...rawPoolNoStaple, ...extraPool, ...recipePool.filter(fk=>!usedFks.has(fk))], recipeUsage);
        cand = fallback.find(fk=>!usedFks.has(fk) && !isBlockedCandidate(mk,fk));
      }
      if (!cand) break;
      const before = plan[mk].length;
      tryAdd(mk,cand);
      const addedOk = plan[mk].length>before;
      if (!addedOk) usedFks.add(cand); // לא הצליח להיכנס בתקציב — לא ננסה שוב עם אותו פריט
      // לבקשת המשתמש: כשיוגורט הסויה הביתי או שקשוקה טבעונית נכנסים בהצלחה לארוחה, מנסים לצרף אליהם את "לחם עדשים" (אם קיים ועדיין לא נוצל)
      const pairsWithLentilBread = cand==="soyYogurtPlain" || (shakshukaRecipe && cand===shakshukaRecipe.id);
      if (addedOk && pairsWithLentilBread && lentilBreadRecipe && !usedFks.has(lentilBreadRecipe.id)) {
        tryAdd(mk, lentilBreadRecipe.id);
      }
      const mealTotal = sumNuts(plan[mk].map(({fk,g,soaked})=>ingNut(fk,g,soaked))).kcal;
      if (mealTotal >= tgt*SHARE[mk]*0.92) break;
    }
  });

  // כלל: ארוחת בוקר בטווח 30%-35% מהיעד היומי (רצפה = 30%)
  {
    const breakfastFloor = tgt*0.30;
    let guard=0;
    while (sumNuts(plan.breakfast.map(({fk,g,soaked})=>ingNut(fk,g,soaked))).kcal < breakfastFloor && dayKcalUsed < hardCapKcal-10 && guard<20) {
      guard++;
      const pool = shuffleArr([...rawPoolNoStaple, ...recipePool].filter(fk=>!usedFks.has(fk) && !isBlockedCandidate("breakfast",fk)));
      const cand = pool[0];
      if (!cand) break;
      if (!tryAdd("breakfast", cand)) usedFks.add(cand);
    }
  }

  // כלל 9 (וכלל 5): ארוחת ביניים — אך ורק 2 יחידות פרי (לא 2-3 יותר — כלל 5 קובע תקרה גורפת של 2), שום דבר אחר בכלל
  {
    const snackFruitCap = 2;
    let count=0, guard=0;
    while (count<snackFruitCap && guard<10) {
      guard++;
      const fruitCands = shuffleArr(rawPool.filter(fk=>!usedFks.has(fk) && FDB[fk]?.cat==="פרי" && fk!=="breadfruit"));
      const cand = fruitCands[0];
      if (!cand) break;
      if (tryAdd("snack",cand)) count++; else usedFks.add(cand);
    }
  }

  // כלל 4 (המשך): תעדוף כולין וויטמין E לפחות ל-100% מהיעד היומי (=שבועי/7), רק בשלוש הארוחות הראשיות
  // (לא בארוחת ביניים — כלל 9). יוד טופל בנפרד למטה (כלל 3) כי המקור שלו (מלח) הוא כמעט אפס-קלוריות ולא
  // מתאים לניקוד "נוטריאנט לקלוריה" הרגיל
  if (dri) {
    const currentTotals = ()=>sumNuts(Object.values(plan).flat().map(({fk,g,soaked})=>ingNut(fk,g,soaked)));
    [["choline",dri.choline?.dri||550],["vitE",dri.vitE?.dri||15]].forEach(([key,tgtVal])=>{
      let guard=0;
      while (currentTotals()[key] < tgtVal && dayKcalUsed < hardCapKcal-10 && guard<15) {
        guard++;
        const pool = [...rawPoolNoStaple, ...recipePool].filter(fk=>!usedFks.has(fk));
        const scored = pool.map(fk=>{
          const fd=FDB[fk]||TEMP_FDB[fk];
          const perKcal = fd?.per100?.kcal>0 ? (fd.per100[key]||0)/fd.per100.kcal : 0;
          return {fk,perKcal};
        }).filter(x=>x.perKcal>0).sort((a,b)=>b.perKcal-a.perKcal);
        if (!scored.length) break;
        const mkTarget = NON_SNACK_MEALS.reduce((best,mk)=>{
          const used = sumNuts(plan[mk].map(({fk,g,soaked})=>ingNut(fk,g,soaked))).kcal;
          const headroom = tgt*SHARE[mk]*1.3 - used;
          return headroom > (best.headroom ?? -Infinity) ? {mk,headroom} : best;
        }, {}).mk;
        if (!tryAdd(mkTarget, scored[0].fk)) usedFks.add(scored[0].fk); // מונע לולאה אינסופית אם לא נכנס בתקציב
        else protectedMicroFks.add(scored[0].fk);
      }
    });
  }

  // כלל 3 (עדכון נוסף לבקשת המשתמש): מלח מיודד מועדף עד תקרת נתרן של 2000 מ"ג ליום — אבל **מדולג לגמרי בימים
  // שבהם סלט הוואקמה כבר נכנס לתפריט** (wakameSaladPlaced), כי לפי נתוני התווית המדויקים (24,000 מק"ג יוד/100
  // גר' יבש) כמה גרם וואקמה כבר נותנים בעצמם יותר מהיעד היומי — הוספת מלח על גבי זה מיותרת ואף עלולה לדחוף
  // לעודף יוד. בימים בלי וואקמה, מלח נשאר המקור העיקרי, בהסתמך על כך שצריכת האשלגן הגבוהה בתזונה מהצומח
  // ממתנת חלק מהאפקט של הנתרן על לחץ הדם (יחס נתרן:אשלגן חשוב יותר לבריאות הלב-כלי-דם מנתרן בפני עצמו לפי
  // מחקרי INTERSALT/TOHP) — אך זה "ממתן", לא "מבטל", אז התקרה נשארת סבירה. אם יש בפרופיל הבריאות תקרת נתרן
  // רפואית מחמירה יותר (hp.sodiumMax), היא תמיד גוברת על ה-2000 מ"ג כברירת מחדל.
  // כלל 4: נורי אף פעם לא מוצע כרכיב עצמאי — גם לא כ"גיבוי" ליוד. מלח מיודד הוא המקור היחיד ליוד בימים בלי
  // וואקמה, עד תקרת הנתרן. אם היוד לא מגיע ל-100% בגלל תקרת הנתרן — זו מגבלה אמיתית של התזונה בקטגוריות
  // המותרות, לא משהו שהאלגוריתם "פותר" בכוח
  // תיקון-באג (לבקשת המשתמש, אחרי גילוי מקרה עודף-יוד עצום של כ-694% וחוסר קלורי שנוצר ע"י מלח, ולאחר מכן חוסר
  // יוד לא-עקבי ביום סלט-הוואקמה): מנגנון השלמת היוד-דרך-וואקמה הועבר לגמרי לסוף הפונקציה (ראה שם) — לא נשאר
  // כאן, כי כאן (מוקדם מדי) הוא לא ראה את הכמות ה*סופית* של וואקמה בתפריט. מתכון סلט-הוואקמה עצמו יכול להיחתך
  // בהמשך ע"י trimMealS/trimMealS2/balanceMealMacros (כדי לעמוד בתקציב קלורי/מאקרו), מה שמצמצם את תרומת היוד
  // הפנימית שלו בצורה לא צפויה — בדיקה כאן, לפני כל החיתוכים האלה, הייתה מחליטה "יש מספיק יוד" ומדלגת על
  // ההשלמה, בזמן שבפועל אחרי החיתוך נשאר הרבה פחות. הבדיקה הסופית (שבודקת ישירות את הכמות שבאמת נשארה בתפריט,
  // לא דגל בוליאני) גם מייתרת את הצורך בדגל wakameSaladPlaced לגמרי: אם המתכון כבר נתן מספיק יוד (גם בטרימה
  // חלקית), אין תוספת; אם הוא נחתך לגמרי, מתווספת וואקמה עצמאית להשלמה — בדיוק כמו בכל יום אחר

  // לבקשת המשתמש: לפחות שני מקורות ירק/עלים שונים בכל ארוחה עיקרית — סופרים גם ירקות "מוסתרים" בתוך מתכון סלט
  // שכבר נבחר לארוחה (למשל סלט כרוב מכיל רק כרוב = מקור אחד), לא רק פריטים גולמיים עצמאיים. אם יש פחות משניים,
  // מנסים להוסיף עוד ירק גולמי אחד מרשימה קצרה, בכפוף לתקציב הקלורי/נתרן הנותר של אותה ארוחה
  {
    const VEG_RAW_POOL = ["cucumber","tomato","carrot","redPepper","greenPepper","radish"];
    const vegFksInMeal = mk => {
      const set = new Set();
      (plan[mk]||[]).forEach(it=>{
        const fd = FDB[it.fk]||TEMP_FDB[it.fk];
        if (fd && !fd._isRecipe && (fd.cat==="ירק"||fd.cat==="עלים")) set.add(it.fk);
        if (fd && fd._isRecipe) {
          const r = recipeByIdNSF[it.fk];
          (r?.ings||[]).forEach(ing=>{ const ifd=FDB[ing.fk]; if (ifd && (ifd.cat==="ירק"||ifd.cat==="עלים")) set.add(ing.fk); });
        }
      });
      return set;
    };
    NON_SNACK_MEALS.forEach(mk=>{
      const existingVeg = vegFksInMeal(mk);
      if (existingVeg.size >= 2) return;
      const used = sumNuts(plan[mk].map(({fk,g,soaked})=>ingNut(fk,g,soaked))).kcal;
      const headroom = Math.min(tgt*SHARE[mk]*1.3-used, hardCapKcal-dayKcalUsed);
      if (headroom < 15) return;
      for (const fk of shuffleArr(VEG_RAW_POOL)) {
        if (usedFks.has(fk) || existingVeg.has(fk)) continue;
        let g = servingG(fk);
        let nut = ingNut(fk,g);
        // תיקון (לבקשת המשתמש: "אל תציע חלקי יחידות ירק - רק שלמות") — אותו תיקון בדיוק כמו addFallbackVeg
        if (nut.kcal > headroom) continue;
        if (nut.sodium > (sodiumCap-sodiumUsed)+0.5) continue;
        plan[mk].push({fk,g}); usedFks.add(fk);
        dayKcalUsed += nut.kcal; sodiumUsed += nut.sodium||0; potassiumUsed += nut.potassium||0; phosphorusUsed += nut.phosphorus||0;
        break;
      }
    });
  }

  // כלל חדש (לבקשת המשתמש, עקבי עם המחולל הכללי): לא יותר משני סוגי אגוזים שונים באותה ארוחה — רשת ביטחון
  // אחרונה למקרה שכמה שלבים שונים (מילוי כללי, השלמת כולין/E, השלמת הרצפה הקלורית) כל אחד הוסיף אגוז אחר לאותה ארוחה.
  // מוגדר כפונקציה (לא בלוק חד-פעמי) כי הוא מופעל פעמיים: כאן וגם שוב אחרי שלב השלמת הרצפה הקלורית למטה —
  // כדי לתפוס גם חריגה שהשלב ההוא עצמו עלול ליצור (ראו הסבר שם)
  const trimExcessNutTypes = () => {
    NON_SNACK_MEALS.forEach(mk=>{
      const nutIdxs=(plan[mk]||[]).map((it,idx)=>({it,idx})).filter(({it})=>{
        const fd=FDB[it.fk]||TEMP_FDB[it.fk]; return fd && fd.cat==="אגוזים" && !fd._isRecipe;
      });
      if (nutIdxs.length<=2) return;
      const toRemoveSet=new Set(nutIdxs.slice(2).map(({idx})=>idx));
      plan[mk]=(plan[mk]||[]).filter((it,idx)=>{
        if (!toRemoveSet.has(idx)) return true;
        const removedNut=ingNut(it.fk,it.g);
        dayKcalUsed-=removedNut.kcal; sodiumUsed-=removedNut.sodium||0;
        potassiumUsed-=removedNut.potassium||0; phosphorusUsed-=removedNut.phosphorus||0;
        usedFks.delete(it.fk);
        return false;
      });
    });
  };
  trimExcessNutTypes();

  // כלל חדש (לבקשת המשתמש, אחרי דיווח על ארוחה עם 4 פלפלים חריפים): לכל היותר פלפל חריף אחד (אדום+ירוק ביחד,
  // לא כל אחד בנפרד) בכל ארוחה — ורק בארוחה שכבר יש בה גם תבשיל דגנים וגם תבשיל קטניות (או מתכון שמשלב את
  // שניהם). ברוב הארוחות (בלי שני התבשילים האלה) לא מוצע פלפל חריף בכלל. פועל כרשת ביטחון אחרונה, מודל אחרי
  // trimExcessNutTypes למעלה — לא משנה משמעותית את מנגנון הבחירה, רק מגביל בדיעבד את מה שכבר נבחר
  {
    const HOT_PEPPER_FKS = new Set(["hotPepperRed","hotPepperGreen"]);
    const mealHasGrainAndLegumeStew = mk => {
      const hasGrainStew = (plan[mk]||[]).some(it=>{ const c=catOfRecipeId(it.fk); return c==="תבשילי דגנים"; });
      const hasLegumeStew = (plan[mk]||[]).some(it=>{ const c=catOfRecipeId(it.fk); return c==="תבשילי קטניות"; });
      return hasGrainStew && hasLegumeStew;
    };
    NON_SNACK_MEALS.forEach(mk=>{
      const hotIdxs = (plan[mk]||[]).map((it,idx)=>({it,idx})).filter(({it})=>HOT_PEPPER_FKS.has(it.fk));
      if (!hotIdxs.length) return;
      const allowed = mealHasGrainAndLegumeStew(mk);
      const keepCount = allowed ? 1 : 0;
      const toRemoveSet = new Set(hotIdxs.slice(keepCount).map(({idx})=>idx));
      if (!toRemoveSet.size) return;
      plan[mk] = (plan[mk]||[]).filter((it,idx)=>{
        if (!toRemoveSet.has(idx)) return true;
        const removedNut=ingNut(it.fk,it.g);
        dayKcalUsed-=removedNut.kcal; sodiumUsed-=removedNut.sodium||0;
        potassiumUsed-=removedNut.potassium||0; phosphorusUsed-=removedNut.phosphorus||0;
        usedFks.delete(it.fk);
        return false;
      });
    });
  }

  // רשת ביטחון (לבקשת המשתמש): מקור ירק אמיתי (לא סלט-קטניות בתחפושת) בכל ארוחה עיקרית — ארוחת צהריים כבר
  // מטופלת ישירות למעלה (בבחירת vCand); כאן רק לוקחים אחריות על בוקר וערב, שלא עוברים דרך אותו מנגנון ייעודי
  {
    const hasRealVegIn = mk => (plan[mk]||[]).some(it=>{
      const fd=FDB[it.fk]||TEMP_FDB[it.fk]; if(!fd) return false;
      if (fd.cat==="ירק") return true;
      return fd._isRecipe && catOfRecipeId(it.fk)==="סלטי ירקות" && !recipeIsLegumeDominant(it.fk);
    });
    ["breakfast","lunch","dinner"].forEach(mk=>{
      if (hasRealVegIn(mk)) return;
      const vCand = usageWeightedOrderCapped(realVegSaladPoolCat.filter(fk=>!usedFks.has(fk)), recipeUsage, 2)[0];
      if (vCand && tryAdd(mk, vCand, 0.4)) return;
      addFallbackVeg(mk);
    });
  }

  // רשת ביטחון ברמת היום כולו (לבקשת המשתמש): לפחות סלט-ירקות אמיתי אחד ביום ממש מקבוצות "סلט בסיס" או "סلט
  // ארוחה" — ירק גולמי בודד (עגבנייה/מלפפון וכו', גם אם כבר מובטח בכל ארוחה ע"י הבלוק שלמעלה) אינו מספיק כדי
  // לקיים את הדרישה הזו. אם אף אחת משלוש הארוחות העיקריות לא קיבלה בפועל מתכון מאחת משתי קבוצות המזון האלה
  // (למשל כי כל מועמדי הסלט כבר נכשלו בבדיקת התקציב של ארוחת הבוקר/הצהריים למעלה) — מנסים להכניס אחד עכשיו,
  // גם אם זה אומר לפרוץ את המסלול הרגיל (כולל ארוחת הערב, שבד"כ לא מקבלת מתכוני סלט) — כי לעמוד בדרישה גובר
  // על ההעדפה הסגנונית הזו.
  {
    const REQUIRED_SALAD_GROUPS = new Set(["סלט_בסיס","סלט_ארוחה"]);
    const dayHasRequiredSalad = NON_SNACK_MEALS.some(mk=>(plan[mk]||[]).some(it=>REQUIRED_SALAD_GROUPS.has(recipeByIdNSF[it.fk]?.foodGroup)));
    if (!dayHasRequiredSalad) {
      const candPool = usageWeightedOrderCapped(recipePool.filter(fk=>REQUIRED_SALAD_GROUPS.has(recipeByIdNSF[fk]?.foodGroup) && !usedFks.has(fk)), recipeUsage, 2);
      const orderedMeals = [...NON_SNACK_MEALS].sort((a,b)=>{
        const usedA = sumNuts(plan[a].map(({fk,g,soaked})=>ingNut(fk,g,soaked))).kcal;
        const usedB = sumNuts(plan[b].map(({fk,g,soaked})=>ingNut(fk,g,soaked))).kcal;
        return (tgt*SHARE[a]-usedA) < (tgt*SHARE[b]-usedB) ? 1 : -1;
      });
      let placedSalad = false;
      for (const cand of candPool) {
        if (placedSalad) break;
        for (const mk of orderedMeals) { if (tryAdd(mk, cand, 1.6)) { placedSalad = true; break; } }
      }
    }
  }

  // כלל חדש (לבקשת המשתמש, אחרי דיווח על ארוחה עם 5 פרוסות לחם): לכל היותר 2 פרוסות לחם בכל ארוחה — נבדק לפי
  // גרמים בפועל (לא רק ספירת-שורות), כי לחם הוא פריט FDB בודד שיכול לצבור כמות גדולה בשורה אחת ממוזגת. פועל
  // כרשת ביטחון אחרונה, אחרי מיזוג הפריטים הכפולים, כדי לתפוס כל צבירה אפשרית ללא קשר לאיזה שלב קודם גרם לה
  {
    const BREAD_FKS = new Set(["wholeWheatBread","wholePita"]);
    NON_SNACK_MEALS.forEach(mk=>{
      (plan[mk]||[]).forEach((it,idx)=>{
        if (!BREAD_FKS.has(it.fk)) return;
        const fd=FDB[it.fk]; if(!fd) return;
        const sliceG = wholeUnitStepG(it.fk) || 32;
        const maxG = sliceG*2;
        if (it.g > maxG) {
          const removedNut=ingNut(it.fk, it.g-maxG);
          plan[mk][idx] = {fk:it.fk, g:maxG};
          dayKcalUsed -= removedNut.kcal; sodiumUsed -= removedNut.sodium||0;
          potassiumUsed -= removedNut.potassium||0; phosphorusUsed -= removedNut.phosphorus||0;
        }
      });
    });
  }

  // כלל חדש: מבטיחים לפחות 99% מהיעד הקלורי היומי (התקרה של 101% כבר מובטחת בכל שלב ע"י hardCapKcal בתוך
  // tryAdd עצמו — זה רק ה"רצפה" התחתונה, שלב ניקוי אחרון לפני סיום — ולכן מוקם כאן, ממש בסוף, אחרי כל שלבי
  // הניקוי/ההשלמה האחרים (2 מקורות ירק, לא יותר מ-2 אגוזים) ולא לפניהם: מיקום קודם גרם לכך ששלבים מאוחרים
  // יותר (בעיקר ניקוי האגוזים) היו לפעמים *מסירים* בדיעבד בדיוק את מה שהשלב הזה הוסיף, בלי ששום דבר כאן יֵדע
  // שזה קרה — מה שיצר פער שיטתי בין dayKcalUsed הפנימי (שנראה תקין) לבין סכום הקלוריות בפועל של plan שהוחזר).
  // עדיין כפוף לכללי 1/5 (לא סלט כפול, לא יותר מ-2 פרי לארוחה). כל פריט אגוזים/זרעים/פרי/מתכון מוגבל מטבעו
  // לפעם אחת ביום — אז המאגר של פריטים *חדשים* יכול פשוט להיגמר לפני שמגיעים ליעד (זו מגבלה אמיתית של ההגבלה
  // הקטגורית + התקרות שקבענו, לא באג). כשזה קורה, במקום לוותר, מנסים "עוד מנה" ממתכון שכבר בתפריט (הכי הגיוני
  // מבחינה קולינרית — "עוד מנה מהתבשיל"). לבקשת המשתמש (דיוק קלורי גבוה יותר — 97%-100% בפועל): הועלתה הרצפה
  // מ-98% ל-99%, ומועמד שלא נכנס לארוחה ה"מובילה" עדיין מנוסה גם מול שתי הארוחות האחרות (לא נפסל אחרי כישלון
  // יחיד) לפני שנפסל סופית. הערה: "מנה חלקית" של מתכון קיים כמוצא-אחרון (שנוסה בעבר) הוסרה — normalizeRecipeServings
  // בסוף הפונקציה מעגל כל מנת מתכון בחזרה למספר שלם של מנות ממילא, כך שתוספת חלקית הייתה מתבטלת בשקט; רק תוספת
  // של מנה שלמה נוספת (או פריט גולמי שלם) שורדת את העיגול הזה
  {
    const minKcal = tgt*0.99;
    let guard=0;
    while (dayKcalUsed < minKcal && guard<60) {
      guard++;
      // מדרג את שלוש הארוחות לפי מקום פנוי (מהגדול לקטן) — ומנסה כל מועמד מול כולן בסדר הזה, לא רק מול
      // הארוחה עם הכי הרבה מקום. באג שתוקן: קודם המועמד נבחן רק מול הארוחה ה"מובילה" ולפי כישלון שם (למשל
      // כי budget הפנימי של tryAdd מחמיר יותר, ×1.25 ולא ×1.5) נפסל לצמיתות מה-usedFks — גם אם היה נכנס
      // בנוחות לארוחה אחרת עם עוד מקום. עכשיו מועמד נפסל סופית רק אחרי שנכשל בכל שלוש הארוחות
      const mealsByHeadroom = NON_SNACK_MEALS.map(mk=>{
        const used = sumNuts(plan[mk].map(({fk,g,soaked})=>ingNut(fk,g,soaked))).kcal;
        return {mk, headroom: tgt*SHARE[mk]*1.5 - used};
      }).sort((a,b)=>b.headroom-a.headroom).map(x=>x.mk);
      const pool = shuffleArr([...rawPoolNoStaple, ...recipePool].filter(fk=>!usedFks.has(fk)));
      // תיקון (לבקשת המשתמש: "סדר-ניסיון חכם יותר — לנסות תחילה מתכונים דלי-שומן/מנגן כשכבר קרוב לתקרה"):
      // כשכבר נצרך 60%+ מתקרת השומן או המנגן, ממיינים את המועמדים לפי יעילות שומן/מנגן (הכי-דל קודם) — לא
      // עוד ערבוב אקראי גרידא — כדי שמועמד עתיר לא "יבזבז" ניסיון שנכשל בוודאות. כשעדיין רחוק מהתקרה (למשל
      // בארוחת בוקר מוקדמת), נשאר ערבוב אקראי רגיל — מתכונים עתירים עדיין יכולים "להיכנס" מוקדם כשיש מקום
      // תיקון (לבקשת המשתמש: "ננסה לעלות לפחות ל-98%") — הסף הורד מ-60% ל-45%: המיון-החכם מתחיל מוקדם יותר,
      // לפני שהתקציב כמעט אזל, כדי לתת עוד הזדמנות למועמד-דל להיכנס לפני שהמצב נהיה קריטי
      const fatNearCap = fatUsed > fatCapG*0.45;
      const mnNearCap = manganeseUsed > manganeseCapMg*0.45;
      if (fatNearCap || mnNearCap) {
        pool.sort((a,b)=>{
          const fdA = FDB[a]||TEMP_FDB[a], fdB = FDB[b]||TEMP_FDB[b];
          if (!fdA || !fdB || !(fdA.per100.kcal>0) || !(fdB.per100.kcal>0)) return 0;
          const scoreA = (fatNearCap?(fdA.per100.fat||0)/fdA.per100.kcal:0) + (mnNearCap?(fdA.per100.manganese||0)/fdA.per100.kcal:0);
          const scoreB = (fatNearCap?(fdB.per100.fat||0)/fdB.per100.kcal:0) + (mnNearCap?(fdB.per100.manganese||0)/fdB.per100.kcal:0);
          return scoreA - scoreB;
        });
      }
      let cand = null;
      for (const fkCand of pool) {
        let ok = false;
        for (const mk of mealsByHeadroom) {
          if (isBlockedCandidate(mk,fkCand)) continue;
          // "לא יותר מ-2 סוגי אגוזים בארוחה" — נבדק גם כאן במפורש (לא רק ב-trimExcessNutTypes אחרי הלולאה),
          // כדי לא לבזבז תקציב על אגוז שלישי שיוסר ממילא ברגע האחרון
          const fdCand = FDB[fkCand]||TEMP_FDB[fkCand];
          if (fdCand?.cat==="אגוזים" && !fdCand._isRecipe) {
            const nutCount = (plan[mk]||[]).filter(it=>{ const f2=FDB[it.fk]||TEMP_FDB[it.fk]; return f2&&f2.cat==="אגוזים"&&!f2._isRecipe; }).length;
            if (nutCount>=2) continue;
          }
          if (tryAdd(mk, fkCand, 3.0)) { ok=true; break; }
        }
        if (ok) { cand=fkCand; break; }
      }
      if (cand) { continue; }
      // אין שום מועמד חדש שנכנס לאף אחת משלוש הארוחות — עוברים לגיבוי: מגדילים מנה קיימת של מתכון שכבר
      // בתפריט (מנה נוספת זהה — שלמה, שורדת את עיגול normalizeRecipeServings), לא אגוז/פרי (כדי לא לשבור
      // את התקרות שנקבעו להם במפורש)
      let bumped=false;
      const existingRecipes=[];
      NON_SNACK_MEALS.forEach(mk3=>{ (plan[mk3]||[]).forEach(it=>{ const fd3=FDB[it.fk]||TEMP_FDB[it.fk]; if(fd3?._isRecipe) existingRecipes.push(it); }); });
      // תיקון-באג (לבקשת המשתמש, אחרי גילוי הכפלה בלתי-מוגבלת): "it.g += it.g" הכפיל את המנה בלי שום תקרה —
      // ומכיוון שהלולאה החיצונית יכולה לרוץ עד 60 פעם, אותו מתכון יכול היה לעבור הכפלות חוזרות (1×→2×→4×→8×...)
      // עד מנה אבסורדית. כעת מוגבל לכל היותר 3× מנת-היסוד המוגדרת של המתכון (_servingG) — "3 מנות" הוא כבר נדיב
      for (const it of shuffleArr(existingRecipes)) {
        const fdIt = FDB[it.fk]||TEMP_FDB[it.fk];
        const baseServing = fdIt?._servingG || it.g;
        if (it.g + it.g > baseServing*3) continue; // תוספת נוספת הייתה חוצה את התקרה — מדלגים למועמד הבא
        const extraNut = ingNut(it.fk, it.g); // מנה נוספת זהה לגודל הקיים
        if (dayKcalUsed+extraNut.kcal > hardCapKcal) continue;
        if ((sodiumUsed+(extraNut.sodium||0)) > sodiumCap+0.5) continue;
        it.g += it.g;
        dayKcalUsed += extraNut.kcal; sodiumUsed += extraNut.sodium||0; potassiumUsed += extraNut.potassium||0; phosphorusUsed += extraNut.phosphorus||0;
        bumped=true;
        break;
      }
      if (!bumped) break; // באמת אין שום דרך סבירה נוספת — עוצרים; היום עלול להישאר קצת מתחת ליעד
    }
  }
  // רשת ביטחון שנייה: הלולאה שלמעלה יכולה תיאורטית להוסיף עוד אגוז לארוחה שכבר יש בה 2 (למשל דרך "עוד מנה
  // ממתכון קיים" שמכיל אגוז כרכיב פנימי — לא נבדק ע"י הבדיקה המפורשת בלולאה, שמסתכלת רק על פריטי אגוזים גולמיים
  // ישירים). מריצים שוב את אותה בדיקה בדיוק כדי לתפוס גם את זה, לפני העיגול הסופי של מנות המתכונים
  trimExcessNutTypes();

  // תיקון-באג (לבקשת המשתמש, אחרי דיווח על אותו מתכון שמופיע פעמיים באותה ארוחה בשתי שורות נפרדות): מיזוג-סופי
  // — פריטים עם אותו fk באותה ארוחה מתמזגים לשורה אחת; מתכון מוגבל לכל היותר מנה שלמה אחת בארוחה (לא מצטבר).
  // מתכון מזוהה גם לפי שם (he), לא רק fk — שני מתכונים בעלי id שונה אך שם זהה גם הם נחשבים כפילות
  Object.keys(plan).forEach(mk=>{
    const merged = []; const idxByFk = new Map(); const idxByRecipeName = new Map();
    (plan[mk]||[]).forEach(it=>{
      const fd = FDB[it.fk]||TEMP_FDB[it.fk];
      if (fd?._isRecipe) {
        const nameKey = (fd.he||"").trim();
        if (idxByRecipeName.has(nameKey)) return;
        idxByRecipeName.set(nameKey, merged.length); merged.push({...it});
      } else if (idxByFk.has(it.fk)) {
        merged[idxByFk.get(it.fk)].g += it.g;
      } else {
        idxByFk.set(it.fk, merged.length); merged.push({...it});
      }
    });
    plan[mk] = merged;
  });
  // רשת ביטחון סופית (לבקשת המשתמש, אחרי דיווח חוזר על ארוחה עם תבשיל קטניות בלי דגן): לכל ארוחה עיקרית שעדיין
  // חסר לה קטנית או דגן, משלימים מהמאגר הרחב ביותר האפשרי — ללא תלות בזה שנכשל בשלב מוקדם יותר
  {
    const FINAL_GRAIN_FALLBACK = ["quinoaCooked","brownRiceCooked","buckwheatCooked","bulgurCooked"];
    // תיקון (לבקשת המשתמש: "במקום קטנית תופיע ליד הדגן מנת טופו או יוגורט סויה או משקה סויה") — נוספו שלוש
    // חלופות-סויה לרשימת-המוצא-האחרון, כתחליף-חלבון תקין לצד דגן כשאף קטנית-קלאסית לא הצליחה להיכנס
    const FINAL_LEGUME_FALLBACK = ["chickpeas","redLentils","blackBeans","whiteBeans","edamame","tofu","soyYogurtOrgPlain","soymilkFortified"];
    const finalMealHasGrain2 = its => (its||[]).some(it=>{
      const fd=FDB[it.fk]||TEMP_FDB[it.fk]; if(!fd) return false;
      if (fd._isRecipe) return (fd._ings||[]).some(ing=>(FDB[ing.fk]||TEMP_FDB[ing.fk])?.cat==="דגן");
      return fd.cat==="דגן"||fd.cat==="מאפה";
    });
    // מתכון שמשלב דגן וקטנית יחד (כמו תבשיל גריסי פנינה ועדשים) נחשב לבקשת המשתמש כ"פחמימות" בלבד — לא
    // מספק את דרישת הקטנית של הארוחה, כדי שתמיד תתלווה אליו מנת קטנית אמיתית ונפרדת (capCatOf כבר מיישם את זה)
    const finalMealHasLegume2 = its => (its||[]).some(it=>capCatOf(it.fk)==="קטנית");
    // תיקון (לבקשת המשתמש: "יחס 2/3 תבשילי קטניות/דגנים, לא קטניות/דגנים מבושלות גולמיות") — רשת-הביטחון הזו
    // רצה לכל ארוחה עיקרית שעדיין חסרה קטנית/דגן, ומוסיפה תמיד גולמי, בלי שום ניסיון-מתכון קודם — נמצא
    // בסימולציה שזו אחת התרומות הגדולות ביותר לדומיננטיות הגולמית. עכשיו מנסים קודם מתכון-תבשיל מתאים שטרם
    // נוצל היום, ורק אם אף אחד לא מתאים לתקציב (≤120% מהיעד), נופלים לגולמי כמקודם
    const tryStewFirst = (pool, mk) => {
      const usedTodayFinal2 = new Set(Object.values(plan).flat().map(it=>it.fk));
      const dayKcalNow2 = () => sumNuts(Object.values(plan).flat().map(({fk,g,soaked})=>ingNut(fk,g,soaked))).kcal;
      for (const rfk of usageWeightedOrder(pool.filter(f=>!usedTodayFinal2.has(f)), recipeUsage)) {
        const rfd = TEMP_FDB[rfk]; if (!rfd) continue;
        // תיקון (לבקשת המשתמש: "אל תציע רבעי מנות, רק שלמות") — רק מנה מלאה
        const rg = rfd._servingG || 200;
        const rnut = ingNut(rfk, rg);
        if (rnut.kcal>0 && dayKcalNow2()+rnut.kcal <= tgt*1.20) { plan[mk].push({fk:rfk,g:rg}); return true; }
      }
      return false;
    };
    shuffleArr(["breakfast","lunch","dinner"]).forEach(mk=>{
      if (!(plan[mk]||[]).length) return;
      const dayKcalNow = () => sumNuts(Object.values(plan).flat().map(({fk,g,soaked})=>ingNut(fk,g,soaked))).kcal;
      const usedTodayFinal = () => new Set(Object.values(plan).flat().map(it=>it.fk));
      if (!finalMealHasGrain2(plan[mk]) && !tryStewFirst(grainStewPool, mk)) {
        const cand = FINAL_GRAIN_FALLBACK.find(fk=>!usedTodayFinal().has(fk)) || shuffleArr(FINAL_GRAIN_FALLBACK)[0];
        if (cand) {
          const gFull = wholeUnitStepG(cand) || getServingUnit(cand,FDB[cand],"he")?.g || 160;
          // אם מנה מלאה לא נכנסת בתקרת 101% היומית — מנסים חצי מנה לפני שמוותרים לגמרי, כדי שהארוחה
          // (בדרך כלל ערב, עם התקציב הקטן ביותר) לא תישאר בלי שום דגן מבושל
          for (const g of [gFull, gFull*0.5]) {
            const nut = ingNut(cand,g);
            if (nut.kcal>0 && dayKcalNow()+nut.kcal <= tgt*1.20) { plan[mk].push({fk:cand,g}); break; }
          }
        }
      }
      if (!finalMealHasLegume2(plan[mk]) && !tryStewFirst(legumeStewPool, mk)) {
        const cand = FINAL_LEGUME_FALLBACK.find(fk=>!usedTodayFinal().has(fk)) || shuffleArr(FINAL_LEGUME_FALLBACK)[0];
        if (cand) {
          const g = wholeUnitStepG(cand) || getServingUnit(cand,FDB[cand],"he")?.g || 150;
          const nut = ingNut(cand,g);
          if (nut.kcal>0 && dayKcalNow()+nut.kcal <= tgt*1.20) plan[mk].push({fk:cand,g});
        }
      }
    });
  }

  // רשת ביטחון נוספת (לבקשת המשתמש): צהריים וערב מקבלים לפחות פרי אחד, אם עדיין אין
  {
    const FINAL_FRUIT_FALLBACK = ["apple","orange","pear","kiwi","banana","grapes"];
    ["lunch","dinner"].forEach(mk=>{
      const hasFruit = (plan[mk]||[]).some(it=>(FDB[it.fk]||TEMP_FDB[it.fk])?.cat==="פרי");
      if (hasFruit) return;
      const usedTodayFinal2 = new Set(Object.values(plan).flat().map(it=>it.fk));
      const cand = FINAL_FRUIT_FALLBACK.find(fk=>!usedTodayFinal2.has(fk));
      if (!cand) return;
      const g = getServingUnit(cand,FDB[cand],"he")?.g || 150;
      const nut = ingNut(cand,g);
      const dayKcalNow2 = sumNuts(Object.values(plan).flat().map(({fk,g,soaked})=>ingNut(fk,g,soaked))).kcal;
      if (nut.kcal>0 && dayKcalNow2+nut.kcal <= tgt*1.01) plan[mk].push({fk:cand,g});
    });
  }

  // רשת ביטחון (לבקשת המשתמש): כל מתכון ממרח שכבר בתפריט מקבל לצידו, באותה ארוחה, מתכון מאפה — אם עדיין אין
  {
    Object.keys(plan).forEach(mk=>{
      const hasSpread = (plan[mk]||[]).some(it=>{ const r=recipeByIdNSF[it.fk]; return r && bookCategoryOf(r)==="ממרחים"; });
      if (!hasSpread) return;
      const hasBaked = (plan[mk]||[]).some(it=>{ const r=recipeByIdNSF[it.fk]; return r && bookCategoryOf(r)==="מאפים"; });
      if (hasBaked) return;
      const bCand = usageWeightedOrder(bakedGoodPoolCat.filter(fk=>!usedFks.has(fk)), recipeUsage)[0];
      if (bCand) tryAdd(mk, bCand);
    });
  }

  // רשת ביטחון (לבקשת המשתמש): כל יוגורט (סויה — ביתי/אורגני, או מתכון שמכיל יוגורט כרכיב) שכבר בתפריט מקבל
  // לצידו, באותה ארוחה, מתכון מאפה — אם עדיין אין. אותו עיקרון בדיוק כמו כלל הממרח למעלה, מודל אחריו ישירות
  {
    const YOGURT_FKS = new Set(["soyYogurtPlain","soyYogurtOrgPlain","yogurtPlain3","yogurtGreek"]);
    const mealHasYogurt = mk => (plan[mk]||[]).some(it=>{
      if (YOGURT_FKS.has(it.fk)) return true;
      const r = recipeByIdNSF[it.fk];
      return r ? (r.ings||[]).some(ing=>YOGURT_FKS.has(ing.fk)) : false;
    });
    Object.keys(plan).forEach(mk=>{
      if (!mealHasYogurt(mk)) return;
      const hasBaked = (plan[mk]||[]).some(it=>{ const r=recipeByIdNSF[it.fk]; return r && bookCategoryOf(r)==="מאפים"; });
      if (hasBaked) return;
      const bCand = usageWeightedOrder(bakedGoodPoolCat.filter(fk=>!usedFks.has(fk)), recipeUsage)[0];
      if (bCand) tryAdd(mk, bCand);
    });
  }

  // רשת ביטחון (לבקשת המשתמש): בארוחת בוקר — אם יש קטניות (תבשיל קטניות, או פריט/מתכון עם קטנית מוטמעת), אבל
  // אין לצידן שום בסיס דגנים (תבשיל דגנים, מתכון מאפה, או דגן גולמי) — מוסיפים תבשיל דגנים. לא נוגע בשאר
  // הארוחות (צהריים/ערב כבר מטופלות בכללים הייעודיים למעלה — תבשיל דגן+קטנית ביחד, או מסלולי א'/ב')
  {
    const mealHasLegumeAny = mk => (plan[mk]||[]).some(it=>{
      const fd=FDB[it.fk]||TEMP_FDB[it.fk]; if(!fd) return false;
      if (fd.cat==="קטנית") return true;
      if (fd._isRecipe) return catOfRecipeId(it.fk)==="תבשילי קטניות" || (recipeByIdNSF[it.fk]?.ings||[]).some(ing=>(FDB[ing.fk]||{}).cat==="קטנית");
      return false;
    });
    const mealHasGrainAny = mk => (plan[mk]||[]).some(it=>{
      const fd=FDB[it.fk]||TEMP_FDB[it.fk]; if(!fd) return false;
      if (fd.cat==="דגן") return true;
      if (fd._isRecipe) return catOfRecipeId(it.fk)==="תבשילי דגנים" || bookCategoryOf(recipeByIdNSF[it.fk]||{})==="מאפים";
      return false;
    });
    if (mealHasLegumeAny("breakfast") && !mealHasGrainAny("breakfast")) {
      const gCand = usageWeightedOrder(grainStewPool.filter(fk=>!usedFks.has(fk)), recipeUsage)[0];
      if (gCand) tryAdd("breakfast", gCand, 0.85);
    }
  }

  Object.keys(plan).forEach(mk=>{ plan[mk] = normalizeRecipeServings(plan[mk]); });

  // חלוקת קלוריות מפורשת בין הארוחות (לבקשת המשתמש): בוקר ~38% (36%-40%), צהריים ~36% (34%-38%), ערב ~20%
  // (18%-22%). אותה גישה כמו ב-generatePersonalDayPlan: רק הגדלה/הקטנה של פריטים קיימים, מוגבל 3 תוספות לפריט
  {
    const mealKcalS = mk => sumNuts((plan[mk]||[]).map(({fk,g,soaked})=>ingNut(fk,g,soaked))).kcal;
    const bfMinS=tgt*0.30, bfMaxS=tgt*0.35, lunchMinS=tgt*0.30, lunchMaxS=tgt*0.35, dinnerMinS=tgt*0.18, dinnerMaxS=tgt*0.26;
    const trimMealS = (mk, maxKcal) => {
      let guard=0;
      while (mealKcalS(mk) > maxKcal && guard<15) {
        guard++;
        let best=null,bestKcal=-1;
        (plan[mk]||[]).forEach((it,idx)=>{
          const fd=FDB[it.fk]||TEMP_FDB[it.fk]; if(!fd||protectedMicroFks.has(it.fk)) return;
          const nut=ingNut(it.fk,it.g);
          if (nut.vitE>=vitEProtectThreshold) return; // סבב ראשון: דילוג על תורם ויטמין-E משמעותי
          if (nut.kcal>bestKcal) { bestKcal=nut.kcal; best={idx,fk:it.fk,g:it.g,fd}; }
        });
        if (!best || bestKcal<=0) { // סבב שני (רשת ביטחון): כל הפריטים מוגנים/עתירי-E — אין ברירה, מוותרים על ההגנה הפעם
          (plan[mk]||[]).forEach((it,idx)=>{
            const fd=FDB[it.fk]||TEMP_FDB[it.fk]; if(!fd) return;
            const nut=ingNut(it.fk,it.g);
            if (nut.kcal>bestKcal) { bestKcal=nut.kcal; best={idx,fk:it.fk,g:it.g,fd}; }
          });
        }
        if (!best || bestKcal<=0) break;
        const {idx,fk,g,fd}=best;
        if (fd._isRecipe) { plan[mk].splice(idx,1); dayKcalUsed -= bestKcal; continue; }
        const wholeStep=wholeUnitStepG(fk);
        const newG = wholeStep!=null ? Math.max(0,g-wholeStep) : Math.max(0,Math.round(g*0.7*10)/10);
        const removedNut=ingNut(fk,g-newG);
        if (newG < (wholeStep?wholeStep*0.5:15)) plan[mk].splice(idx,1); else plan[mk][idx]={...best,g:newG};
        dayKcalUsed -= removedNut.kcal;
      }
    };
    const growMealS = (mk, minKcal) => {
      let guard=0;
      // תיקון-באג קריטי (לבקשת המשתמש, אחרי "1120 גר' אבטיח" שחזר בסימולציה): זה בלוק *נפרד* לגמרי מ-growMealS2
      // (הצעד הסופי) — יש לו מבנה קוד שונה (growCounts, לא capG), ולכן שום אחד מהתיקונים הקודמים לא נגע בו בכלל.
      // אין כאן שום מגבלת-קטגוריה ושום תקרה מוחלטת בגרמים — רק "עד 3 תוספות" בלי הקשר לכמות שכבר הייתה קיימת.
      // עכשיו משתמש באותה תקרה מוחלטת ומודעת-קטגוריה בדיוק כמו growMealS2: פרי/קטנית/משקה-סויה לכל היותר ×1,
      // שאר הפריטים ×2
      while (mealKcalS(mk) < minKcal && guard<20) {
        guard++;
        const candidates = (plan[mk]||[]).filter(it=>{ const fd=FDB[it.fk]||TEMP_FDB[it.fk]; return fd && !fd._isRecipe && fd.cat!=="שומן" && fd.cat!=="אגוזים" && it.fk!=="wakame"; });
        let acted=false;
        for (const it of candidates) {
          const itFd = FDB[it.fk]||TEMP_FDB[it.fk];
          const isSingle = itFd && (itFd.cat==="פרי" || itFd.cat==="קטנית" || it.fk==="soymilkOrgPlain" || it.fk==="soymilkFortified");
          const capG = servingG(it.fk) * (isSingle ? 1 : 2);
          if (it.g >= capG) continue;
          const idx = plan[mk].indexOf(it);
          const step = wholeUnitStepG(it.fk) || Math.round(it.g*0.25*10)/10;
          if (step<=0) continue;
          const addedNut = ingNut(it.fk, step);
          if (dayKcalUsed+addedNut.kcal > hardCapKcal) continue;
          plan[mk][idx] = {...it, g: it.g+step};
          dayKcalUsed += addedNut.kcal;
          acted=true; break;
        }
        if (!acted) break;
      }
    };
    if (mealKcalS("breakfast") > bfMaxS) trimMealS("breakfast", bfMaxS);
    if (mealKcalS("lunch") > lunchMaxS) trimMealS("lunch", lunchMaxS);
    if (mealKcalS("dinner") > dinnerMaxS) trimMealS("dinner", dinnerMaxS);
    if (mealKcalS("breakfast") < bfMinS) growMealS("breakfast", bfMinS);
    if (mealKcalS("lunch") < lunchMinS) growMealS("lunch", lunchMinS);
    if (mealKcalS("dinner") < dinnerMinS) growMealS("dinner", dinnerMinS);
    // רשת ביטחון (לבקשת המשתמש, אחרי מקרה של ארוחת ערב שנשארה ריקה לגמרי — 0 קק"ל): growMealS לעיל לא יכולה
    // לעשות דבר בארוחה שמתחילה ריקה (אין פריט קיים להגדיל). אם אחרי כל השלבים למעלה ארוחה עיקרית עדיין ריקה
    // לגמרי, מעתיקים אליה פריט בודד קיים מארוחה אחרת של אותו יום (כפילות מוגבלת בלבד, מוצא אחרון) — עדיף מאשר
    // ארוחה עם 0 קלוריות. אם אין שום פריט זמין להעתיק (כל הארוחות ריקות), מוותרים בשקט
    ["breakfast","lunch","dinner"].forEach(mk=>{
      if ((plan[mk]||[]).length) return;
      for (const other of ["lunch","dinner","breakfast"]) {
        if (other===mk || !(plan[other]||[]).length) continue;
        const src = plan[other][0];
        const fd = FDB[src.fk]||TEMP_FDB[src.fk];
        if (!fd) continue;
        plan[mk] = [{...src}];
        const nut = ingNut(src.fk, src.g);
        dayKcalUsed += nut.kcal;
        break;
      }
    });
  }

  // איזון מאקרו סופי לכל ארוחה עיקרית (לבקשת המשתמש): חלבון שואף ל-18-20% מהקלוריות, שומן ≤25%, פחמימות
  // היתרה — אותו מנגנון בדיוק כמו ב-generateDayPlan וב-generatePersonalDayPlan. תיקון-באג: מחולל זה (הצע
  // ארוחות ממתכונים) היה היחיד מבין שלושת מחוללי היום שמעולם לא קרא ל-balanceMealMacros בכלל — כך שהוא
  // המשיך לייצר ימים שחורגים מיעדי המאקרו גם אחרי שהתיקון הוחל על שני המחוללים האחרים. תיקון-באג נוסף (לבקשת
  // המשתמש): תקציב אמיתי (hardCapKcal-dayKcalUsed שנותר) מועבר ל-balanceMealMacros ומנוכה בפועל בין הארוחות —
  // בלי זה, מהלכי "הוספה/הגדלה" לתיקון חלבון יכלו להוסיף קלוריות בלי תקרה בכלל, ולדחוף את סך היום הרחק מעל 100%
  let macroBudget = Math.max(0, hardCapKcal-dayKcalUsed);
  // תיקון-באג תואם (ראו הערה זהה ב-generateDayPlan/generatePersonalDayPlan): מגבילים גם לתקרת-החלק של כל ארוחה
  // בנפרד (SHARE[mk] מהיעד היומי), לא רק לתקציב היומי הכולל שנותר
  ["breakfast","lunch","dinner"].forEach(mk=>{
    if (!(plan[mk]||[]).length) return;
    const beforeKcal = sumNuts(plan[mk].map(({fk,g,soaked})=>ingNut(fk,g,soaked))).kcal;
    const mealBudget = Math.max(0, Math.min(macroBudget, target*SHARE[mk]-beforeKcal));
    plan[mk] = balanceMealMacros(plan[mk], mealBudget, protectedMicroFks, vitEProtectThreshold);
    const afterKcal = sumNuts(plan[mk].map(({fk,g,soaked})=>ingNut(fk,g,soaked))).kcal;
    macroBudget -= Math.max(0, afterKcal-beforeKcal);
  });

  // כלל חדש (לבקשת המשתמש): להבטיח 98-100% מהיעד הקלורי היומי גם אחרי איזון המאקרו — איזון המאקרו למעלה
  // (בפרט מהלך הסרת מנה עתירת-שומן) יכול להשאיר "חור" קלורי שלא תמיד מתמלא בחזרה באותו סבב (למשל אם לא היה
  // עוד מקום בתקציב לתוספת חלבון). ממלאים אותו כאן בנפרד, אחרי שהמאקרו כבר סופי, בפריטים נמוכי-שומן יחסית
  // (קטניות/דגנים/פרי/סויה — לא אגוזים/שומן/מנות שעלולות רק להיחסם שוב מיד). תיקון-באג: לא מספיק לבחור פריטים
  // "בדרך כלל" דלי-שומן — כל תוספת נבדקת בפועל מול mealMacroPctOf של אותה ארוחה ספציפית *לפני* שהיא מתבצעת,
  // ומדלגים על אותה ארוחה אם היא הייתה דוחפת את השומן שלה מעל 25% (עוברים לארוחה הבאה בתור במקום זאת) — אחרת
  // מילוי הקלוריות היה יכול לשבור מחדש בדיוק את מה שאיזון המאקרו הקודם עבד קשה כדי להשיג
  {
    // תיקון (לבקשת המשתמש: "שוב נפלנו ביעד הקלוריות" — אותר שהסרת טופו מכאן, לצד הבאגים האחרים שתוקנו, צמצמה
    // את מגוון-המועמדים הזמין להשלמה מדויקת. הורחב עם עוד כמה אפשרויות תקינות ולא-אסורות, לא רק להחזיר את טופו
    const FILLER_POOL = ["chickpeas","redLentils","blackBeans","whiteBeans","greenLentils","brownRiceCooked","quinoaCooked","banana","apple","orange","soymilkOrgPlain","soyYogurtPlain","soyYogurtOrgPlain","mungBeans","pearlBarleyCooked","freekeh","couscousCooked","sweetPotatoCooked","splitPeas"];
    // תיקון-באג (לבקשת המשתמש, אחרי ארוחת צהריים ב-37.7% מהיעד היומי): תקרת-חלק לכל ארוחה, כדי שמנגנון המילוי
    // הזה לא ידחוף ארוחה ספציפית מעבר לתקרת ה-30-35%/30-35%/20-30% שלה, גם אם סך היום עדיין תקין
    const FILLER_MEAL_CAP = mk => mk==="dinner" ? tgt*0.26 : tgt*0.35;
    const totalKcal = () => sumNuts(Object.values(plan).flat().map(({fk,g,soaked})=>ingNut(fk,g,soaked))).kcal;
    const fatOkAfter = (mk, trialList) => mealMacroPctOf(trialList).f <= 25.5;
    // תיקון-באג (לבקשת המשתמש, אחרי גילוי שהמילוי כאן ובהמשך הפונקציה מעולם לא בדק נתרן בכלל): sodiumUsed החיצוני
    // כבר לא אמין בשלב הזה (balanceMealMacros/trimMealS יכלו להסיר פריטים בלי לעדכן אותו) — לכן מחשבים כאן נתרן
    // טרי ישירות מ-plan בכל בדיקה, ואוכפים תקרה יומית קשיחה של 2000 מ"ג (לבקשת המשתמש), לא 2300 המקורית של הפונקציה
    const sodiumUsedNow = () => sumNuts(Object.values(plan).flat().map(({fk,g,soaked})=>ingNut(fk,g,soaked))).sodium||0;
    const sodiumCapFiller = Math.min(2000, sodiumCap);
    let guardTop=0;
    // תיקון-באג (לבקשת המשתמש, אחרי תקרית "9 כוסות משקה סויה"): הלולאה הקודמת בחרה תמיד את אותו פריט-ממלא
    // ראשון שנמצא בארוחה (plan[mk].find), וכל סבב נוסף המשיך להגדיל *אותו פריט בדיוק* — עד עודף אבסורדי בפריט
    // בודד (למשל תפוז יחיד שגדל ל-2+ ק"ג). כעת עוברים על כל פריטי-הממלא הקיימים בארוחה בכל סבב (לא רק הראשון),
    // וגם מגבילים כל פריט בנפרד לכל היותר 3 תוספות מצטברות באותו סבב-מילוי — כדי שתמיד יתפזר על פני כמה פריטים
    // שונים, לעולם לא יתרכז כולו באחד
    // תיקון-באג (לבקשת המשתמש, אחרי "1200 גר' משקה סויה" שהתגלה בסימולציה): ספירת "עד 3 תוספות" לא הביאה
    // בחשבון כמות קיימת-מראש מהשלבים המוקדמים יותר בפונקציה — פריט שכבר היה בכמות גדולה (למשל 2 מנות) יכול
    // היה לקבל עוד 3 תוספות מעבר לזה, בלי תקרה אמיתית. כעת בודקים תקרה מוחלטת בגרמים (4× המנה הרגילה), לא
    // ספירת-תוספות יחסית — זו התקרה שבאמת לא ניתן לחצות, ללא קשר לכמה כבר היה בארוחה קודם לכן
    while (totalKcal() < tgt*0.997 && guardTop<100) {
      guardTop++;
      let acted=false;
      for (const mk of ["breakfast","lunch","dinner"]) {
        if (!plan[mk]) continue;
        for (const existing of plan[mk].filter(it=>FILLER_POOL.includes(it.fk))) {
          // תיקון-באג (לבקשת המשתמש, אחרי "4 כוסות פטל" ו"2 כוסות משקה סויה בארוחה אחת"): תקרת 4× הייתה
          // סבירה למניעת ריבוי-קיצוני, אבל עדיין אפשרה כמויות לא-הגיוניות לפריטים שנמדדים ביחידות גדולות (כוס
          // פרי, כוס משקה סויה, כוס קטניות מבושלות) — אלה לעולם לא אמורים לחרוג ממנה אחת בארוחה בודדת. דגנים
          // (אורז/קינואה/שיבולת שועל) עדיין מותרים עד כפול, כי מנה גדולה יותר שלהם היא סבירה בפועל
          // תיקון-באג (לבקשת המשתמש, אחרי "1120 גר' אבטיח" שהתגלה בסימולציה): הרשימה הקודמת מנתה רק 3 פירות
          // ספציפיים בשם (בננה/תפוח/תפוז) — כל שאר הפירות (אבטיח, מלון, ענבים, תותים וכו') נשארו בטעות בתקרת
          // ה-2× הרגילה. עכשיו הבדיקה לפי קטגוריה (fd.cat) ולא רשימת-שמות חלקית — כך שכל פרי/קטנית באמת מוגבל ל-1×
          const existingFd = FDB[existing.fk]||TEMP_FDB[existing.fk];
          const isSingleServingCat = existingFd && (existingFd.cat==="פרי" || existingFd.cat==="קטנית" || existing.fk==="soymilkOrgPlain" || existing.fk==="soymilkFortified");
          const capG = servingG(existing.fk) * (isSingleServingCat ? 1 : 2);
          if (existing.g >= capG) continue;
          const step = wholeUnitStepG(existing.fk) || Math.round(existing.g*0.25*10)/10;
          const nut = ingNut(existing.fk, step);
          const idx = plan[mk].findIndex(it=>it.fk===existing.fk);
          const trial = plan[mk].map((it,i)=>i===idx?{...it,g:it.g+step}:it);
          const mealKcalNowFillF = sumNuts(trial.map(({fk,g,soaked})=>ingNut(fk,g,soaked))).kcal;
          if (nut.kcal>0 && totalKcal()+nut.kcal <= tgt*1.00 && mealKcalNowFillF <= FILLER_MEAL_CAP(mk)*1.05 && nut.sodium <= (sodiumCapFiller-sodiumUsedNow())+0.5 && fatOkAfter(mk,trial)) {
            plan[mk] = trial;
            acted=true; break;
          }
        }
        if (acted) break;
        const usedToday = new Set(Object.values(plan).flat().map(it=>it.fk));
        // תיקון-באג קריטי (לבקשת המשתמש, אחרי דיווח על ארוחה עם 4 קטניות שונות נערמות בלי שום דגן): הבחירה
        // הקודמת כאן בדקה רק "עוד לא נעשה בו שימוש היום בכלל" — בלי מודעות לכך שהארוחה הנוכחית (mk) כבר
        // מכילה קטנית/דגן. מכיוון שהלולאה החיצונה תמיד מתחילה מארוחת הבוקר בכל סבב, וש-FILLER_POOL מתחיל
        // ברשימת קטניות שלמה, ארוחה אחת ספגה כמה קטניות שונות ברצף עד שכולן נוצלו. עכשיו נבדקת גם קטגוריית
        // קטנית/דגן קיימת באותה ארוחה לפני שמוסיפים מועמד חדש מאותה קטגוריה
        const mealCatsAlready = new Set((plan[mk]||[]).map(it=>{
          return capCatOf(it.fk);
        }).filter(c=>c==="קטנית"||c==="דגן"));
        // תיקון-באג (לבקשת המשתמש, אחרי דיווח על שני סוגי יוגורט-סויה שונים באותה ארוחה): החרגת קטנית/דגן
        // למעלה לא כיסתה משפחת "חלבון" (soyYogurtPlain/soyYogurtOrgPlain שניהם cat="חלבון") — שני הווריאנטים
        // נחשבו מועמדים בלתי-תלויים לגמרי, כך שהלולאה יכלה להוסיף את שניהם לאותה ארוחה בשני סבבים נפרדים.
        // מוחרג עכשיו במפורש: אם לארוחה כבר יש איזשהו יוגורט-סויה, לא מוסיפים עוד וריאנט שלו
        const SOY_YOGURT_FAMILY = new Set(["soyYogurtPlain","soyYogurtOrgPlain"]);
        const mealHasSoyYogurt = (plan[mk]||[]).some(it=>SOY_YOGURT_FAMILY.has(it.fk));
        const fk = FILLER_POOL.find(f=>{
          if (usedToday.has(f)) return false;
          if (SOY_YOGURT_FAMILY.has(f) && mealHasSoyYogurt) return false;
          const capCat = capCatOf(f);
          if ((capCat==="קטנית"||capCat==="דגן") && mealCatsAlready.has(capCat)) return false;
          return true;
        });
        if (fk) {
          // תיקון (לבקשת המשתמש: "בכל השבוע נכנסו רק פעמיים-שלוש תבשילי קטניות מהמתכונים, לעומת הרבה קטניות
          // מבושלות גולמיות כמילוי — רוצה לפחות 2/3 כתבשילי קטניות", ובהמשך: "באותו אופן התייחס גם לתבשילי
          // הדגנים") — כשהמועמד שנבחר הוא קטנית/דגן גולמי (chickpeas/redLentils/brownRiceCooked/וכו', לא
          // מתכון), מנסים קודם להחליף אותו במתכון-תבשיל מתאים (קטניות/דגנים בהתאם) שטרם נוצל היום, תחת בדיוק
          // אותם תנאי-תקציב/נתרן/שומן — כדי שמתכוני התבשיל ישמשו אבן-בסיס אמיתית, לא רק מאגר-השלמה. נופלים
          // חזרה לגולמי רק אם אף מתכון לא מתאים לתקציב שנותר
          const RAW_LEGUME_FKS = new Set(["chickpeas","redLentils","blackBeans","whiteBeans","greenLentils","mungBeans","splitPeas"]);
          // תיקון (לבקשת המשתמש: "באותו אופן התייחס גם לתבשילי הדגנים" — אבן-בסיס, לא רק מאגר-השלמה) — אותה
          // בדיוק לוגיקה, הפעם לדגנים גולמיים-מבושלים (אורז חום/קינואה/גריסי פנינה/פריקה/קוסקוס) מול מתכוני
          // תבשיל-דגנים
          const RAW_GRAIN_FKS = new Set(["brownRiceCooked","quinoaCooked","pearlBarleyCooked","freekeh","couscousCooked"]);
          let placedViaRecipe = false;
          if (RAW_LEGUME_FKS.has(fk) || RAW_GRAIN_FKS.has(fk)) {
            const stewPoolForFk = RAW_LEGUME_FKS.has(fk) ? legumeStewPool : grainStewPool;
            outerLoop:
            // תיקון (לבקשת המשתמש: יחס 2/3, אחרי סימולציה שהראתה שגם עם עשרות מועמדים ומנות-חלקיות ההחלפה
            // עדיין נכשלת הרבה — FILLER_MEAL_CAP*1.05 צר מדי כשהארוחה כבר כמעט מלאה בשלב המאוחר הזה): מרווח
            // מדורג, כמוצא-אחרון-ממש
            for (const capMargin of [1.05, 1.3, 1.6]) {
            // תיקון (לבקשת המשתמש: וידוא מגוון) — cap=2 עוזר למגוון בקטנית (31 מתכונים, יש מרווח) אבל פוגע
            // בדגן (רק 8 מתכונים - cap ממצה את המאגר מהר מדי ודוחף חזרה לגולמי, כפי שאושר בסימולציה)
            const stewCap = RAW_LEGUME_FKS.has(fk) ? 2 : 999;
            for (const lfk of usageWeightedOrderCapped(stewPoolForFk.filter(f=>!usedToday.has(f)), recipeUsage, stewCap)) {
              const lfd = TEMP_FDB[lfk]; if (!lfd) continue;
              // תיקון (לבקשת המשתמש: "אל תציע רבעי מנות, רק שלמות") — רק מנה מלאה
              const lg = lfd._servingG || 200;
              const lnut = ingNut(lfk, lg);
              const ltrial = [...plan[mk], {fk:lfk, g:lg}];
              const lmealKcal = sumNuts(ltrial.map(({fk,g,soaked})=>ingNut(fk,g,soaked))).kcal;
              if (lnut.kcal>0 && totalKcal()+lnut.kcal<=tgt*1.00 && lmealKcal<=FILLER_MEAL_CAP(mk)*capMargin && lnut.sodium<=(sodiumCapFiller-sodiumUsedNow())+0.5 && fatOkAfter(mk,ltrial)) {
                plan[mk]=ltrial; acted=true; placedViaRecipe=true; break outerLoop;
              }
            }
            }
          }
          if (!placedViaRecipe) {
            const g = wholeUnitStepG(fk) || (getServingUnit(fk,FDB[fk],"he")?.g||100);
            const nut = ingNut(fk,g);
            const trial = [...plan[mk], {fk,g}];
            const mealKcalNowFillF2 = sumNuts(trial.map(({fk,g,soaked})=>ingNut(fk,g,soaked))).kcal;
            if (nut.kcal>0 && totalKcal()+nut.kcal <= tgt*1.00 && mealKcalNowFillF2 <= FILLER_MEAL_CAP(mk)*1.05 && nut.sodium <= (sodiumCapFiller-sodiumUsedNow())+0.5 && fatOkAfter(mk,trial)) {
              plan[mk] = trial;
              acted=true;
            }
          }
          if (acted) break;
        }
      }
      if (!acted) break;
    }
  }

  // צעד סופי (לבקשת המשתמש, שוב): אכיפת חלוקת הקלוריות כ"מילה אחרונה" — אותה סיבה בדיוק כמו בשני המחוללים
  // האחרים. עותק עצמאי (לא תלוי בהיקף המשתנים של הבלוק המוקדם יותר, שכבר נסגר) של אותו trimMealS/growMealS בטוח
  {
    const mealKcalS2 = mk => sumNuts((plan[mk]||[]).map(({fk,g,soaked})=>ingNut(fk,g,soaked))).kcal;
    const bfMinS2=tgt*0.30, bfMaxS2=tgt*0.35, lunchMinS2=tgt*0.30, lunchMaxS2=tgt*0.35;
    const trimMealS2 = (mk, maxKcal) => {
      let guard=0;
      while (mealKcalS2(mk) > maxKcal && guard<15) {
        guard++;
        if ((plan[mk]||[]).length<=1) break; // לעולם לא לרוקן ארוחה לגמרי — משאירים תמיד פריט אחד לפחות
        // תיקון-באג (לבקשת המשתמש, אחרי עלייה חדה בהפרות שומן≤25% שנצפתה): מיון לפי כמות-שומן בפועל, לא לפי
        // הכי-הרבה-קק"ל — כדי שהצמצום הזה לא יסיר בטעות את הפריט הרזה ("מאזן" את הארוחה) וישאיר את הפריט השמנוני
        let best=null,bestFat=-1;
        (plan[mk]||[]).forEach((it,idx)=>{
          const fd=FDB[it.fk]||TEMP_FDB[it.fk]; if(!fd||protectedMicroFks.has(it.fk)) return;
          const nut=ingNut(it.fk,it.g);
          if (nut.vitE>=vitEProtectThreshold) return; // סבב ראשון: דילוג על תורם ויטמין-E משמעותי
          if (nut.fat>bestFat) { bestFat=nut.fat; best={idx,fk:it.fk,g:it.g,fd,kcal:nut.kcal}; }
        });
        if (!best || best.kcal<=0) { // סבב שני (רשת ביטחון): כל הפריטים מוגנים/עתירי-E — מוותרים על ההגנה הפעם
          (plan[mk]||[]).forEach((it,idx)=>{
            const fd=FDB[it.fk]||TEMP_FDB[it.fk]; if(!fd) return;
            const nut=ingNut(it.fk,it.g);
            if (nut.fat>bestFat) { bestFat=nut.fat; best={idx,fk:it.fk,g:it.g,fd,kcal:nut.kcal}; }
          });
        }
        if (!best || best.kcal<=0) break;
        const {idx,fk,g,fd}=best;
        if (fd._isRecipe) { plan[mk].splice(idx,1); continue; }
        const wholeStep=wholeUnitStepG(fk);
        const newG = wholeStep!=null ? Math.max(0,g-wholeStep) : Math.max(0,Math.round(g*0.7*10)/10);
        if (newG < (wholeStep?wholeStep*0.5:15)) plan[mk].splice(idx,1); else plan[mk][idx]={...best,g:newG};
      }
    };
    const growMealS2 = (mk, minKcal) => {
      let guard=0;
      // תיקון-באג קריטי (לבקשת המשתמש, אחרי "560/840 גר' אבטיח" שחזר שוב ושוב בסימולציה): זו הייתה עותק *שלישי*
      // ונפרד של growMealS2 שהתיקון הקודם (capG מודע-קטגוריה) פספס לגמרי — עדיין עם growCounts הישן, בלי שום
      // תקרה מוחלטת בגרמים. עכשיו אותה תקרה בדיוק כמו בכל שאר מנגנוני ההגדלה: פרי/קטנית/משקה-סויה לכל היותר ×1,
      // שאר הפריטים ×2 מהמנה הרגילה — ללא קשר לכמה תוספות כבר בוצעו
      while (mealKcalS2(mk) < minKcal && guard<20) {
        guard++;
        const candidates = (plan[mk]||[]).filter(it=>{ const fd=FDB[it.fk]||TEMP_FDB[it.fk]; return fd && !fd._isRecipe && fd.cat!=="שומן" && fd.cat!=="אגוזים" && it.fk!=="wakame"; });
        let acted=false;
        for (const it of candidates) {
          const itFd = FDB[it.fk]||TEMP_FDB[it.fk];
          const isSingle = itFd && (itFd.cat==="פרי" || itFd.cat==="קטנית" || it.fk==="soymilkOrgPlain" || it.fk==="soymilkFortified");
          const capG = servingG(it.fk) * (isSingle ? 1 : 2);
          if (it.g >= capG) continue;
          const idx = plan[mk].indexOf(it);
          const step = wholeUnitStepG(it.fk) || Math.round(it.g*0.25*10)/10;
          if (step<=0) continue;
          const addedNut = ingNut(it.fk, step);
          const curTotal = sumNuts(Object.values(plan).flat().map(({fk,g,soaked})=>ingNut(fk,g,soaked))).kcal;
          if (curTotal+addedNut.kcal > tgt*1.00) continue;
          // תיקון-באג (לבקשת המשתמש, אחרי עלייה חדה בהפרות שומן≤25% שנצפתה): בודקים שההגדלה לא דוחפת את שומן
          // הארוחה מעל 25% — לא מספיק לשלול רק קטגוריות שומן/אגוזים, כי פריטים "מותרים" אחרים (למשל טופו) גם
          // תורמים שומן משמעותי
          const trial = plan[mk].map((x,i)=>i===idx?{...x,g:x.g+step}:x);
          if (mealMacroPctOf(trial).f > 25.5) continue;
          plan[mk][idx] = {...it, g: it.g+step};
          acted=true; break;
        }
        if (!acted) break;
      }
    };
    if (mealKcalS2("breakfast") > bfMaxS2) trimMealS2("breakfast", bfMaxS2);
    if (mealKcalS2("lunch") > lunchMaxS2) trimMealS2("lunch", lunchMaxS2);
    if (mealKcalS2("breakfast") < bfMinS2) growMealS2("breakfast", bfMinS2);
    if (mealKcalS2("lunch") < lunchMinS2) growMealS2("lunch", lunchMinS2);
    const dinnerTargetS2 = Math.max(150, tgt - mealKcalS2("breakfast") - mealKcalS2("lunch") - mealKcalS2("snack"));
    if (mealKcalS2("dinner") > dinnerTargetS2*1.1) trimMealS2("dinner", dinnerTargetS2);
    if (mealKcalS2("dinner") < dinnerTargetS2*0.9) growMealS2("dinner", dinnerTargetS2);

    // תיקון-באג קריטי (לבקשת המשתמש, אחרי גילוי פער קלורי גדול במחולל "הצע ממתכונים"): trimMealS2 למעלה יכול
    // להסיר מנה/מתכון שלם לגמרי (הכי-שומני בארוחה) כדי לעמוד בתקרת חלוקת-הקלוריות בין הארוחות — אבל בניגוד לשלב
    // המילוי המקביל שרץ לפני איזון-המאקרו (FILLER_POOL), לצעד הסופי הזה מעולם לא היה שום מנגנון השלמה — כך שהסרת
    // מתכון גדול (למשל 400-700 קק"ל, שכיח כשהמתכונים עצמם הם "ארוחה שלמה") הייתה משאירה את היום עם חור קלורי גדול
    // וקבוע, בלי שום ניסיון למלא אותו בחזרה. כעת, ממש אחרי הצעד הסופי, משלימים את הפער בחזרה — קודם ע"י הוספת
    // מתכון (חדש, או מנה שנייה של מתכון שכבר בתפריט היום — עד 2 מנות מאותו מתכון ביום, בבקשת המשתמש), ורק אם אף
    // מתכון לא נכנס בתקציב/בשומן — נופלים לפריטים גולמיים קטנים (בדיוק כמו FILLER_POOL המקורי)
    // תיקון-באג (בסיבוב בדיקה נוסף): התוספת הזו בדקה במקור רק את תקרת הקלוריות הכוללת של היום (hardCapKcal), לא
    // את תקרת חלוקת-הקלוריות בין הארוחות שהצעד הסופי בדיוק אכף רגע קודם — מה שאיפשר לה "להחזיר" קלוריות ישר
    // לתוך אותה ארוחה שזה עתה נחתכה, ולפעמים אף לדחוף אותה מעל 100% מהיעד היומי כתוצאה מכך. כעת כל תוספת (מתכון
    // או פריט גולמי) נבדקת גם מול תקרת-הארוחה שלה עצמה (עם מרווח סביר של 10% מעבר לתקרה, כדי לא לחסום לגמרי
    // השלמה קטנה), לא רק מול התקרה היומית הכוללת
    {
      const totalKcalF = () => sumNuts(Object.values(plan).flat().map(({fk,g,soaked})=>ingNut(fk,g,soaked))).kcal;
      const fatOkAfterF = (mk, trialList) => mealMacroPctOf(trialList).f <= 25.5;
      const mealCapF = mk => mk==="breakfast" ? bfMaxS2*1.2 : mk==="lunch" ? lunchMaxS2*1.2 : dinnerTargetS2*1.4;
      // תיקון-באג (לבקשת המשתמש): כמו בשלב FILLER_POOL הקודם, גם ההשלמה הזו מעולם לא בדקה נתרן — מחשבים טרי
      // מ-plan ואוכפים תקרה יומית קשיחה של 2000 מ"ג (לא 2300)
      const sodiumUsedNowF = () => sumNuts(Object.values(plan).flat().map(({fk,g,soaked})=>ingNut(fk,g,soaked))).sodium||0;
      const sodiumCapF = Math.min(2000, sodiumCap);
      const recipeUseCountF = new Map();
      Object.values(plan).flat().forEach(it=>{ if (isDishFk(it.fk)) recipeUseCountF.set(it.fk,(recipeUseCountF.get(it.fk)||0)+1); });
      const RAW_FILLER_POOL_F = ["chickpeas","redLentils","blackBeans","whiteBeans","greenLentils","brownRiceCooked","quinoaCooked","banana","apple","orange","soymilkOrgPlain","soyYogurtPlain","soyYogurtOrgPlain","mungBeans","pearlBarleyCooked","freekeh","couscousCooked","sweetPotatoCooked","splitPeas"];
      let guardF2=0;
      while (totalKcalF() < tgt*0.997 && guardF2<100) {
        guardF2++;
        let actedF=false;
        for (const mk of shuffleArr(["breakfast","lunch","dinner"])) {
          if (!plan[mk]) continue;
          const mealKcalNow = mealKcalS2(mk);
          const candRecipes = shuffleArr(recipePool.filter(fk=>(recipeUseCountF.get(fk)||0) < 2));
          for (const fk of candRecipes) {
            const fdR = FDB[fk]||TEMP_FDB[fk]; if (!fdR) continue;
            const gR = Math.round(fdR._servingG||80);
            const nutR = ingNut(fk,gR);
            if (nutR.kcal<=0 || totalKcalF()+nutR.kcal > tgt*1.00) continue;
            if (mealKcalNow+nutR.kcal > mealCapF(mk)) continue; // לא לדחוף ארוחה בודדת מעל התקרה שלה שוב
            if (nutR.sodium > (sodiumCapF-sodiumUsedNowF())+0.5) continue;
            const trialR = [...plan[mk], {fk,g:gR}];
            if (!fatOkAfterF(mk,trialR)) continue;
            plan[mk] = trialR;
            recipeUseCountF.set(fk,(recipeUseCountF.get(fk)||0)+1);
            actedF=true; break;
          }
          if (actedF) break;
        }
        if (actedF) continue;
        for (const mk of ["breakfast","lunch","dinner"]) {
          if (!plan[mk]) continue;
          const mealKcalNow = mealKcalS2(mk);
          const usedTodayF = new Set(Object.values(plan).flat().map(it=>it.fk));
          // אותו תיקון-באג בדיוק כמו ב-FILLER_POOL למעלה: לא מוסיפים קטנית/דגן חדשים אם הארוחה כבר מכילה כאלה
          const mealCatsAlreadyF = new Set((plan[mk]||[]).map(it=>{
            return capCatOf(it.fk);
          }).filter(c=>c==="קטנית"||c==="דגן"));
          const fkF = RAW_FILLER_POOL_F.find(f=>{
            if (usedTodayF.has(f)) return false;
            const capCat = capCatOf(f);
            if ((capCat==="קטנית"||capCat==="דגן") && mealCatsAlreadyF.has(capCat)) return false;
            return true;
          });
          if (!fkF) continue;
          // תיקון (לבקשת המשתמש: יחס 2/3 תבשילי קטניות/דגנים) — אותו טיפול בדיוק כמו ב-FILLER_POOL המקורי:
          // לפני שמוסיפים קטנית/דגן גולמי כאן, מנסים קודם מתכון-תבשיל מתאים שטרם נוצל היום
          if (RAW_LEGUME_GRAIN_STAPLE.has(fkF)) {
            const stewPoolF = capCatOf(fkF)==="קטנית" ? legumeStewPool : grainStewPool;
            let placedViaRecipeF = false;
            outerLoopF:
            for (const rfk of usageWeightedOrder(stewPoolF.filter(f=>!usedTodayF.has(f)), recipeUsage)) {
              const rfd = TEMP_FDB[rfk]; if (!rfd) continue;
              // תיקון (לבקשת המשתמש: "אל תציע רבעי מנות, רק שלמות") — רק מנה מלאה
              const rg = rfd._servingG || 200;
              const rnut = ingNut(rfk, rg);
              if (mealKcalNow+rnut.kcal > mealCapF(mk)) continue;
              if (rnut.sodium > (sodiumCapF-sodiumUsedNowF())+0.5) continue;
              const rtrial = [...plan[mk], {fk:rfk, g:rg}];
              if (rnut.kcal>0 && totalKcalF()+rnut.kcal<=tgt*1.00 && fatOkAfterF(mk,rtrial)) {
                plan[mk]=rtrial; actedF=true; placedViaRecipeF=true; break outerLoopF;
              }
            }
            if (placedViaRecipeF) break;
          }
          const gF = wholeUnitStepG(fkF) || (getServingUnit(fkF,FDB[fkF],"he")?.g||100);
          const nutF = ingNut(fkF,gF);
          if (mealKcalNow+nutF.kcal > mealCapF(mk)) continue;
          if (nutF.sodium > (sodiumCapF-sodiumUsedNowF())+0.5) continue;
          const trialF = [...plan[mk], {fk:fkF,g:gF}];
          if (nutF.kcal>0 && totalKcalF()+nutF.kcal <= tgt*1.00 && fatOkAfterF(mk,trialF)) {
            plan[mk] = trialF;
            actedF=true; break;
          }
        }
        if (!actedF) break;
      }
    }
  }

  // רשת ביטחון (לבקשת המשתמש, אחרי עלייה בארוחות ריקות שנצפתה): גם אחרי הצעד הסופי, ארוחה יכולה להישאר ריקה
  // (למשל אם מהלך "הסרת מנה" באיזון המאקרו הריק אותה ואחריו growMealS2 לא מצא שום פריט מתאים להגדיל). אותה
  // רשת ביטחון בדיוק כמו קודם בפונקציה — מעתיקים פריט בודד מארוחה אחרת כמוצא אחרון
  ["breakfast","lunch","dinner"].forEach(mk=>{
    if ((plan[mk]||[]).length) return;
    for (const other of ["lunch","dinner","breakfast"]) {
      if (other===mk || !(plan[other]||[]).length) continue;
      const src = plan[other][0];
      const fd = FDB[src.fk]||TEMP_FDB[src.fk];
      if (!fd) continue;
      plan[mk] = [{...src}];
      break;
    }
  });


  // תקרת-שפיות אחרונה, כלל-פריט (לבקשת המשתמש, אחרי גילוי "840 גר' אבטיח" בסימולציה — מנגנון זה היה חסר
  // לגמרי במחולל הזה, בניגוד לשני האחרים): מגבילה כל פריט גולמי (לא מתכון, לא יחידת-ספירה טבעית כמו אגוז/פרי-
  // שלם) ללא קשר לאיזה מנגנון גרם לגידול — פרי/קטנית/משקה-סויה לכל היותר ×1 מהמנה הרגילה, כל שאר הפריטים ×3
  {
    const SANE_SINGLE_CATS = new Set(["פרי","קטנית"]);
    MEAL_KEYS.forEach(mk=>{
      (plan[mk]||[]).forEach((it,idx)=>{
        const fd = FDB[it.fk]||TEMP_FDB[it.fk]; if(!fd||fd._isRecipe) return;
        const wholeStep = wholeUnitStepG(it.fk); if (wholeStep!=null) return;
        const normalG = getServingUnit(it.fk,fd,"he")?.g||100;
        const isSingle = SANE_SINGLE_CATS.has(fd.cat) || it.fk==="soymilkOrgPlain" || it.fk==="soymilkFortified";
        const maxG = normalG * (isSingle ? 1 : 3);
        if (it.g > maxG) plan[mk][idx] = {fk:it.fk, g:maxG};
      });
    });
  }

  // תקרה יומית למשקה סויה (לבקשת המשתמש): לא יותר מ-2 כוסות (480 גר') סה"כ ביום, מכל שילוב של הזנים (רגיל/מועשר) —
  // גם אם כל ארוחה בנפרד נראית סבירה (כוס אחת), הצטברות על פני כמה ארוחות (בוקר+צהריים+ערב) יכולה לעבור את הסביר
  {
    const SOY_MILK_FKS = ["soymilkOrgPlain","soymilkFortified"];
    const SOY_MILK_DAILY_CAP_G = 240; // 1 כוס (עודכן לבקשת המשתמש — היה 2 כוסות/480 גר')
    let soyMilkTotalG = 0;
    Object.values(plan).flat().forEach(it=>{ if (SOY_MILK_FKS.includes(it.fk)) soyMilkTotalG += it.g; });
    if (soyMilkTotalG > SOY_MILK_DAILY_CAP_G) {
      let excess = soyMilkTotalG - SOY_MILK_DAILY_CAP_G;
      for (const mk of ["dinner","lunch","breakfast","snack"]) {
        if (excess<=0) break;
        if (!plan[mk]) continue;
        for (let i=plan[mk].length-1; i>=0 && excess>0; i--) {
          const it = plan[mk][i];
          if (!SOY_MILK_FKS.includes(it.fk)) continue;
          const reduceBy = Math.min(it.g, excess);
          const newG = Math.round((it.g - reduceBy)*10)/10;
          if (newG < 30) plan[mk].splice(i,1); else plan[mk][i] = {...it, g:newG};
          excess -= reduceBy;
        }
      }
    }
  }

  // תיקון-באג (לבקשת המשתמש, אחרי גילוי מקרה עודף-יוד עצום של כ-694%, ולאחר מכן חוסר יוד לא-עקבי ביום סלט-
  // הוואקמה): מנגנון השלמת היוד עבר לכאן — ממש בסוף הפונקציה, אחרי כל שלבי הטרימה/גידול/איזון-המאקרו — כי
  // רק כאן רואים את הכמות ה*סופית* של וואקמה שבאמת נשארה בתפריט (מתכון סלט-הוואקמה יכול להיחתך חלקית או
  // לגמרי בשלבים קודמים כדי לעמוד בתקציב קלורי/מאקרו, מה שמצמצם את תרומת היוד הפנימית שלו בצורה לא צפויה).
  // הבדיקה כאן ישירה על הכמות בפועל — לא על דגל בוליאני — כך שבין אם המתכון נתן מספיק יוד (גם בטרימה חלקית),
  // ובין אם נחתך לגמרי או לא הוצע כלל, ההשלמה תמיד מדויקת למה שבאמת חסר. מלח מיודד הוסר לגמרי (לבקשת המשתמש):
  // וואקמה ריכוזית ביוד פי מאות מירק רגיל (24,000 מק"ג/100 גר' יבש) אך דלת-נתרן יחסית לכמות היוד (1,050 מ"ג/100
  // גר') — מגיעה ליעד המלא (150 מק"ג) בפחות מגרם אחד (כ-0.625 גר') ועם פחות מ-7 מ"ג נתרן, כמעט בלי סימן על
  // תקציב הנתרן. תוספת בגרמים מדויקים (לא כפית קבועה), מוגבלת גם כלפי מעלה (105%) כדי לא ליצור עודף. הוואקמה
  // הזו לעולם לא "תגדל" בטעות ע"י growMealS/growMealS2 בהמשך, כי הפונקציה הזו כבר לא רצה שוב אחריה — זו
  // ההוספה האחרונה לפני ההחזרה
  if (dri) {
    const iodineTarget = dri.iodine?.dri||150;
    const iodineCap105 = iodineTarget*1.05;
    const wakamePer100 = FDB.wakame?.per100;
    if (wakamePer100 && wakamePer100.iodine>0) {
      const ct = sumNuts(Object.values(plan).flat().map(({fk,g,soaked})=>ingNut(fk,g,soaked)));
      const iodineGap = iodineTarget - (ct.iodine||0);
      if (iodineGap > 0) {
        const gForFullTarget = iodineGap / wakamePer100.iodine * 100;
        const gForCap = (iodineCap105 - (ct.iodine||0)) / wakamePer100.iodine * 100;
        const wakameQtrStepG2 = (getServingUnit("wakame", FDB.wakame, "he")?.g||2)/4; // רבע כפית וואקמה
        // לעולם לא מוסיפים וואקמה בכמות שביר-כפית זעירה שמוצגת כ"0 כפית" — מעגלים תמיד לרבע כפית הקרוב, ברצפה של רבע כפית שלם
        const rawAddG = Math.max(0, Math.min(gForFullTarget, gForCap));
        const addG = rawAddG < wakameQtrStepG2*0.5 ? 0 : Math.max(wakameQtrStepG2, Math.round(rawAddG/wakameQtrStepG2)*wakameQtrStepG2);
        if (addG > 0) {
          const bestMealForAdd = NON_SNACK_MEALS.reduce((best,mk)=>{
            const used = sumNuts((plan[mk]||[]).map(({fk,g,soaked})=>ingNut(fk,g,soaked))).kcal;
            const headroom = tgt*SHARE[mk]*1.3 - used;
            return headroom > (best.headroom ?? -Infinity) ? {mk,headroom} : best;
          }, {}).mk;
          if (plan[bestMealForAdd]) {
            const existing = plan[bestMealForAdd].find(it=>it.fk==="wakame");
            if (existing) existing.g = Math.round((existing.g+addG)*100)/100;
            else plan[bestMealForAdd].push({fk:"wakame", g:addG});
          }
        }
      }
    }
  }
  // לבקשת המשתמש: השלמת נתרן ע"י רבע כפית מלח מיודד, אם צריך ויש מרווח עד התקרה (ראו applySodiumSaltTopup
  // למעלה). ב"יום בודד" (לא דרך השבוע) זה תמיד פעיל; בגרסה השבועית applySalt=false כאן, וההחלטה על אילו
  // ימים בשבוע מקבלים את התוספת (עד 3) נעשית שם, אחרי שרואים את הנתרן הסופי של כל 7 הימים
  // תיקון אקטיבי סופי ליחס אומגה 6:3 (אותו עיקרון בדיוק כמו ב-generateDayPlan/generatePersonalDayPlan, מותאם
  // למשתני dayKcalUsed/hardCapKcal של הפונקציה הזו): מגדילים מקור אומגה3 קיים, אח"כ מוסיפים מקור חדש אם חסר
  // לגמרי, ורק אם זה עדיין לא מספיק — מקטינים/מסירים את הפריט עתיר-האומגה6 שתורם הכי הרבה בפועל
  {
    const dayNutNowR = () => sumNuts(Object.values(plan).flat().map(({fk,g,soaked})=>ingNut(fk,g,soaked)));
    const currentRatioR = () => { const n=dayNutNowR(); return n.omega3>0 ? n.omega6/n.omega3 : (n.omega6>0?Infinity:0); };
    const O3_BOOST_CAPS_R = {flaxseed:24, chiaseeds:28, walnuts:15};
    const HIGH_O6_ITEMS_R = new Set(["hazelnuts","brazilNuts","cashews","almonds","sunflowerS","pumpkinS","tahini","tahiniRaw","tahiniFullRaw","peanutButter","almondbutter","peanuts","pistachio","sesame"]);
    let guardOmegaR=0;
    while (currentRatioR() > 5 && guardOmegaR<16) {
      guardOmegaR++;
      let acted=false;
      for (const boostFk of Object.keys(O3_BOOST_CAPS_R)) {
        const flat = Object.keys(plan).flatMap(mk=>(plan[mk]||[]).map((it,idx)=>({...it,mk,idx})));
        const loc = flat.find(it=>it.fk===boostFk);
        if (!loc) continue;
        const cap = O3_BOOST_CAPS_R[boostFk];
        if (loc.g >= cap-0.5) continue;
        const stepG = wholeUnitStepG(boostFk) || 2;
        const newG = Math.min(cap, loc.g+stepG);
        if (newG<=loc.g) continue;
        const extraKcal = ingNut(boostFk, newG-loc.g).kcal;
        if (extraKcal > (hardCapKcal-dayKcalUsed)+5) continue;
        plan[loc.mk][loc.idx] = {fk:boostFk, g:newG};
        dayKcalUsed += extraKcal;
        acted=true;
        break;
      }
      if (acted) continue;
      const missingSourceR = Object.keys(O3_BOOST_CAPS_R).find(fk=>!Object.values(plan).flat().some(it=>it.fk===fk));
      if (missingSourceR) {
        const mk = shuffleArr(NON_SNACK_MEALS.filter(m=>plan[m]))[0] || Object.keys(plan)[0];
        const g = wholeUnitStepG(missingSourceR) || getServingUnit(missingSourceR,FDB[missingSourceR],"he")?.g || 10;
        const nut = ingNut(missingSourceR, g);
        if (mk && plan[mk] && nut.kcal <= (hardCapKcal-dayKcalUsed)+5) { plan[mk].push({fk:missingSourceR,g}); dayKcalUsed += nut.kcal; acted=true; }
      }
      if (acted) continue;
      const allItemsR = Object.keys(plan).flatMap(mk=>(plan[mk]||[]).map((it,idx)=>({...it,mk,idx})));
      const worstO6R = allItemsR.filter(it=>HIGH_O6_ITEMS_R.has(it.fk)).map(it=>({...it,o6:ingNut(it.fk,it.g).omega6||0})).sort((a,b)=>b.o6-a.o6)[0];
      if (worstO6R) {
        const wholeStepR = wholeUnitStepG(worstO6R.fk);
        const oldKcalR = ingNut(worstO6R.fk,worstO6R.g).kcal;
        if (wholeStepR && worstO6R.g<=wholeStepR+0.5) {
          plan[worstO6R.mk].splice(worstO6R.idx,1);
          dayKcalUsed -= oldKcalR;
        } else {
          const newGR = wholeStepR ? Math.max(0, worstO6R.g-wholeStepR) : Math.max(0, +(worstO6R.g*0.6).toFixed(1));
          if (newGR<=0) { plan[worstO6R.mk].splice(worstO6R.idx,1); dayKcalUsed -= oldKcalR; }
          else { plan[worstO6R.mk][worstO6R.idx]={fk:worstO6R.fk,g:newGR}; dayKcalUsed -= (oldKcalR - ingNut(worstO6R.fk,newGR).kcal); }
        }
        acted=true;
      }
      if (!acted) break;
    }
  }
  // רשת ביטחון ייעודית לסידן (לבקשת המשתמש, אחרי דיווח חוזר על חוסר סידן במצב "ממתכונים" — במיוחד תחת גירעון
  // קלורי): במקור הותר רק לשלוף אגוזים/זרעים/פרי (ALLOWED_CATS) לתוספת עצמאית במצב הזה — אבל המשתמש אישר
  // במפורש (אחרי שהסברתי את המגבלה) גם טופו, כרוב ומשפחת המצליבים כמקורות סידן נוספים, גם אם זה חורג
  // מ"אך ורק אגוזים/זרעים/פרי" הרגיל של המצב. אלה גם הרבה יותר יעילים קלורית לסידן (בוק צ'וי/כרוב/כרוב-ניצנים/
  // ברוקולי/כרובית נותנים הרבה יותר סידן לקק"ל מאשר שקדים) — כך שהם ננסים ראשונים, וצ'יה/שקדים (שגם תורמים
  // ויטמין E, שאין לו תחליף דל-קלוריות דומה) נשארים כגיבוי אחרון
  {
    const calciumTarget = (dri?.calcium?.dri || 1000) * 1.15;
    // תיקון (לבקשת המשתמש: "שוב נפלנו ביעד הקלוריות") — שבעה מתוך תשעת המועמדים כאן נחסמו כעצמאיים (bokChoy/
    // kale/cabbageRed/broccoli/cauliflower/brusselsSp/tofu), נשארו רק צ'יה ושקדים — מה שצמצם מאוד את יכולת-
    // ההשלמה-הקלורית של המנגנון הזה. נוספו שני מועמדים תקינים ולא-אסורים (משקה סויה מועשר, שעועית לבנה)
    const CA_SOURCES = [
      {fk:"bokChoy",cap:200,step:30},{fk:"kale",cap:150,step:30},{fk:"cabbageRed",cap:150,step:30},
      {fk:"broccoli",cap:200,step:30},{fk:"cauliflower",cap:200,step:30},{fk:"brusselsSp",cap:150,step:30},{fk:"tofu",cap:150,step:20},
      {fk:"soymilkFortified",cap:240,step:40},{fk:"whiteBeans",cap:200,step:30},
      {fk:"chiaseeds",cap:40,step:5},{fk:"almonds",cap:60,step:5}
    ];
    const dayCalciumNow = () => sumNuts(Object.values(plan).flat().map(({fk,g,soaked})=>ingNut(fk,g,soaked))).calcium||0;
    let guardCa=0;
    while (dayCalciumNow() < calciumTarget && guardCa<120) {
      guardCa++;
      let acted=false;
      for (const {fk,cap,step} of CA_SOURCES) {
        const flat = Object.keys(plan).flatMap(mk=>(plan[mk]||[]).map((it,idx)=>({...it,mk,idx})));
        const loc = flat.find(it=>it.fk===fk);
        const fd=FDB[fk]; if(!fd) continue;
        // צעד מותאם לכל מקור (ולא יחידת המנה הטבעית, כמו חופן שקדים=28 גר') — כדי שההשלמה תוכל להיכנס גם
        // למרווח קלורי צר מאוד, בלי לדלג לגמרי כי קפיצה שלמה לא נכנסת. לירקות (עלים/מצליבים, תקרה גבוהה
        // ודלת-קלוריות) צעד גדול יותר (30 גר') כדי לא לבזבז את כל תקציב-הסבבים על מילוי מקור אחד בלבד
        const stepG = step || 5;
        if (loc) {
          if (loc.g>=cap-0.5) continue;
          const remainingHeadroom = Math.max(0, hardCapKcal-dayKcalUsed);
          const kcalPerG = (fd.per100.kcal||0)/100;
          const maxAffordableG = kcalPerG>0 ? Math.floor((remainingHeadroom-5)/kcalPerG) : stepG;
          const addG = Math.max(0, Math.min(stepG, cap-loc.g, maxAffordableG));
          if (addG<=0) continue;
          const newG = loc.g+addG;
          const extraKcal=ingNut(fk,addG).kcal;
          plan[loc.mk][loc.idx]={fk,g:newG};
          dayKcalUsed += extraKcal;
          acted=true; break;
        } else {
          // תיקון (לבקשת המשתמש: "אל תציע כרישה וניצני כרוב... אל תציע טופו כרכיב עצמאי אלא אם כן הוא במתכון")
          // — הענף הזה יוצר הופעה חדשה-לגמרי כפריט עצמאי. אם fk נמצא ברשימת-האיסור הגלובלית, מדלגים על
          // יצירת הופעה חדשה (עדיין מותר לגדל הופעה קיימת למעלה, אם הגיעה ממתכון)
          if (GLOBAL_BANNED_STANDALONE.has(fk)) continue;
          const remainingHeadroom = Math.max(0, hardCapKcal-dayKcalUsed);
          const kcalPerG = (fd.per100.kcal||0)/100;
          const maxAffordableG = kcalPerG>0 ? Math.floor((remainingHeadroom-5)/kcalPerG) : stepG;
          const g = Math.max(0, Math.min(stepG, cap, maxAffordableG));
          if (g<=0) continue;
          const nut=ingNut(fk,g);
          // תיקון (לבקשת המשתמש: "בארוחת ביניים מופיעה קטנית בניגוד לכלל") — אותר: whiteBeans (קטנית) נוסף
          // כמועמד-סידן בסבב קודם, ובחירת-הארוחה-הבברירת-מחדל כאן יכולה ליפול על "snack" אם breakfast ריקה
          // באותו שלב, בלי שום בדיקה שזו קטנית/דגן שאסורים בארוחת-ביניים. מוחרג כאן במפורש
          // תיקון (המשך לתיקון-קטנית-בסנאק): "מצא ראשון שאינו-סנאק" גרם לרגרסיה משמעותית בטווח-הקלוריות —
          // כי הבאג הקודם (שנפל לפעמים על snack) בפועל "עבד" טוב יותר להשלמת-קלוריות, כי לסנאק תמיד יש הרבה
          // מרווח יחסי (תקרה של 8% בלבד). התיקון הנכון: לבחור את הארוחה-הלא-סנאק עם הכי-הרבה מרווח-יחסי, לא
          // סתם "הראשונה שנמצאת" — כך שהמנגנון מצליח באותה אמינות, על ארוחה תקינה במקום על סנאק
          const nonSnackMeals = Object.keys(plan).filter(k=>k!=="snack" && plan[k]);
          const mk = nonSnackMeals.sort((a,b)=>{
            const capA = GLOBAL_MEAL_SHARE_MAX[a]||0.38, capB = GLOBAL_MEAL_SHARE_MAX[b]||0.38;
            return (mealKcalOfGlobal(plan,a)/capA) - (mealKcalOfGlobal(plan,b)/capB);
          })[0];
          if(!mk) continue;
          plan[mk].push({fk,g});
          dayKcalUsed += nut.kcal;
          acted=true; break;
        }
      }
      if (!acted) break;
    }
  }
  // רשת ביטחון ייעודית לויטמין E (לבקשת המשתמש, בהמשך ישיר לתיקון הסידן): באותו מצב "ממתכונים" עם אותה
  // בעיה מבנית — צ'יא/שקדים לבד (המקורות היחידים המותרים במקור) לא תמיד מספיקים תחת גירעון קלורי. לבקשת
