function servingLabel(fk,g,lang){
  const fd=FDB[fk]||TEMP_FDB[fk]; const u=getServingUnit(fk,fd,lang); const gr=lang==="he"?"ג׳":"g";
  if(!u){
    const cat=fd?.cat||"";
    let fallbackHe="",fallbackEn="",baseG=100;
    if(cat==="עלים"){fallbackHe="כוס";fallbackEn="cup";baseG=30;}
    else if(cat==="ירק"){fallbackHe="יח׳ בינונית";fallbackEn="medium";baseG=100;}
    else if(cat==="פרי"){fallbackHe="יח׳ בינונית";fallbackEn="medium";baseG=120;}
    else if(cat==="קטנית"){fallbackHe="כוס מבושל";fallbackEn="cup (cooked)";baseG=165;}
    else if(cat==="דגן"){fallbackHe="כוס מבושל";fallbackEn="cup (cooked)";baseG=160;}
    else if(cat==="זרעים"){fallbackHe="כף";fallbackEn="tbsp";baseG=10;}
    else if(cat==="אגוזים"){fallbackHe="חופן";fallbackEn="handful";baseG=28;}
    else if(cat==="שומן"){fallbackHe="כף";fallbackEn="tbsp";baseG=15;}
    else if(cat==="חלבון"){fallbackHe="כוס";fallbackEn="cup";baseG=240;}
    else{return `${g}${gr}`;}
    const ratio=g/baseG;
    const count=Math.abs(ratio-1)<0.1?"":Math.abs(ratio-0.5)<0.1?"½ ":Math.abs(ratio-2)<0.1?"2 ":fmtN(ratio,1)+" ";
    return `${count}${lang==="he"?fallbackHe:fallbackEn} (${g}${gr})`;
  }
  const ratio=g/u.g;
  const count=Math.abs(ratio-1)<0.1?"":Math.abs(ratio-0.5)<0.1?"½ ":Math.abs(ratio-2)<0.1?"2 ":Math.abs(ratio-0.25)<0.05?"¼ ":fmtN(ratio,1)+" ";
  const label=lang==="he"?u.he:u.en;
  return `${count}${label} (${g}${gr})`;
}

