const PRICE_OVERRIDE_STORAGE="wfpb_price_overrides";
// תיקון (לבקשת המשתמש: "האפליקציה אמורה להציע ניהול תכנון הארוחות על פי תקציב שנקבע בידי המשתמש") — תקציב
// שבועי-אישי נשמר גם הוא רק במכשיר המשתמש, בדיוק כמו מחירי-המשתמש. null = אין תקציב מוגדר (ברירת מחדל)
const WEEKLY_BUDGET_STORAGE="wfpb_weekly_budget";
// תיקון-ארכיטקטורה: מחירי-המשתמש נשמרים בנפרד לגמרי מברירות-המחדל, בדיוק כמו RECIPE_STORAGE - כל
// משתמש רואה/עורך רק את עצמו, לעולם לא משפיע על משתמשים אחרים ולא על ברירות-המחדל שנשארות ללא-שינוי
function getPricePer100g(fk, overrides){
  if (overrides && overrides[fk]!=null) return overrides[fk];
  return DEFAULT_PRICES_PER_100G[fk] ?? 0;
}
function ingCost(fk, g, overrides){
  return getPricePer100g(fk, overrides) * (g||0) / 100;
}
// עלות פריט בודד בתפריט - מטפלת גם ברכיב-גולמי וגם במתכון (סכום עלויות-המרכיבים שלו, לפי היחס בין הכמות
// שהוצעה בפועל ל-בין סך-משקל-המתכון-המוגדר-במקור)
function itemCost(it, overrides){
  const fd = FDB[it.fk]||TEMP_FDB[it.fk];
  if (!fd) return 0;
  if (!fd._isRecipe) return ingCost(it.fk, it.g, overrides);
  const definedTotalG = (fd._ings||[]).reduce((s,ing)=>s+(ing.g||0),0)||1;
  const scaleRatio = (it.g||0)/definedTotalG;
  const recipeFullCost = (fd._ings||[]).reduce((s,ing)=>s+ingCost(ing.fk, ing.g, overrides),0);
  return recipeFullCost * scaleRatio;
}
function mealCost(items, overrides){
  return (items||[]).reduce((s,it)=>s+itemCost(it, overrides),0);
}
function dayCost(day, overrides){
  return Object.values(day||{}).reduce((s,items)=>s+mealCost(items, overrides),0);
}
function weekCost(week, overrides){
  return Object.values(week||{}).reduce((s,day)=>s+dayCost(day, overrides),0);
}
// תיקון (לבקשת המשתמש: "האפליקציה אמורה להציע ניהול תכנון הארוחות על פי תקציב") — מזהה את הפריטים-הגולמיים-
// היקרים-ביותר-ליום (לא נוגעת במתכונים אישיים, כדי לא "לפרק" מנה שהמשתמש בנה בכוונה), ולכל אחד מחפשת חלופה
// זולה-יותר מאותה קבוצת-מזון עם תכולת-קלוריות דומה (עד 20% הפרש) — כדי שההחלפה תישאר ניטרלית-קלורית-בקירוב
function suggestCostSwaps(day, overrides, maxSuggestions=5){
  const suggestions = [];
  Object.keys(day||{}).forEach(mk=>{
    (day[mk]||[]).forEach((it,idx)=>{
      const fd = FDB[it.fk]; if (!fd || fd._isRecipe) return;
      const curCost = ingCost(it.fk, it.g, overrides);
      if (curCost < 1) return; // לא שווה להציע החלפה על פריט זול-ממילא
      const curKcal = ingNut(it.fk, it.g).kcal;
      const sameCat = Object.keys(DEFAULT_PRICES_PER_100G).filter(fk=>{
        const ofd = FDB[fk]; return ofd && !ofd._isRecipe && ofd.cat===fd.cat && fk!==it.fk;
      });
      let best=null, bestSavings=0;
      sameCat.forEach(fk=>{
        const ofd = FDB[fk];
        if (!(ofd.per100.kcal>0)) return;
        const altG = (curKcal/ofd.per100.kcal)*100;
        const altCost = ingCost(fk, altG, overrides);
        const savings = curCost - altCost;
        if (savings > bestSavings && savings > 0.5) { bestSavings=savings; best={fk, g:Math.round(altG*10)/10, cost:altCost}; }
      });
      if (best) suggestions.push({mk, idx, fromFk:it.fk, fromG:it.g, fromCost:curCost, toFk:best.fk, toG:best.g, toCost:best.cost, savings:bestSavings});
    });
  });
  return suggestions.sort((a,b)=>b.savings-a.savings).slice(0,maxSuggestions);
}

